const EXERCISES_DATA = {
  // ── BACK ──────────────────────────────────────────────────────────────────
  "wide-grip-lat-pulldown": { injuryFlags: [], name: "Seated Wide-Grip Lat Pull Down", muscle: "Back", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Grip the bar just outside shoulder width, palms facing away.|Lean back slightly, chest up.|Pull the bar down to your upper chest, driving your elbows down and back.|Squeeze your lats hard at the bottom.|Return with control  - full stretch at the top before the next rep.|Don't use momentum. Pull with your back, not your arms." },
  "one-arm-dumbbell-row": { injuryFlags: ["lumbar-flexion-loaded"], name: "One Arm Dumbbell Row", muscle: "Back", equipment: "Dumbbells", eachSide: true, difficulty: "beginner", coachingCue: "Place one knee and hand on a bench for support, back flat and parallel to the floor.|Hold the dumbbell with the working arm hanging straight down.|Row the dumbbell toward your hip, driving your elbow straight back past your side.|Squeeze your lat and upper back at the top.|Lower with control  - full extension at the bottom.|Keep your back flat the entire time. No twisting." },
      "assisted-pull-up": { injuryFlags: ["shoulder-overhead"], name: "Assisted Pull Up", muscle: "Back", equipment: "Assisted Pull Up Machine", difficulty: "beginner", coachingCue: "Let the machine assist but still create tension. Drive elbows down and back, not just with your arms. Full range every rep." },
  "cable-rope-pull-through": { name: "Cable Pull Throughs", muscle: "Glutes", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Cable at low setting, rope between legs, facing away from machine. Hinge forward, then drive hips through to standing. This is a hip hinge not a squat. Squeeze glutes hard at the top." },
  "chest-press-machine": { injuryFlags: [], name: "Chest Press Machine", muscle: "Chest", equipment: "Chest Press Machine", difficulty: "beginner", coachingCue: "Adjust seat so handles are at mid-chest. Press straight out, not up. Control the return. Let the stretch happen before pressing again. Do not lock elbows at the top." },
  "low-incline-dumbbell-bench-press": { injuryFlags: ["shoulder-impingement"], name: "Dumbbell Bench Press", muscle: "Chest", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["shoulder-impingement"], coachingCue: "Lie on bench, dumbbells at chest, elbows at 45-75 degrees. Press up and slightly in. Lower with control getting a full stretch. Dumbbells should not drift apart at the top." },
      "elevated-pushup": { name: "Elevated Push Up", muscle: "Chest", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["wrist-load"], coachingCue: "Hands elevated on bench. Body in a straight line. Lower chest toward the bench, elbows at 45 degrees. Full push to straight arms. Elevation shifts load to upper chest." },
    "standing-shoulder-press": { name: "Shoulder Press", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["shoulder-overhead"], coachingCue: "Hold dumbbells at shoulder height, palms facing forward or slightly in.|Press overhead to full extension without locking out hard.|Lower back to shoulder height with control.|Keep your core braced  - don't hyperextend your lower back.|Drive straight up, no forward lean.|The press should feel like you're pushing the ceiling." },
  "arnold-press": { name: "Arnold Press", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["shoulder-impingement","shoulder-overhead"], coachingCue: "Start with palms facing you in a bicep curl position. As you press up, rotate palms away from you. This rotation recruits all three heads of the deltoid. Lower and rotate back down." },
  "band-arnold-press": { name: "Band Arnold Press", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "intermediate", injuryFlags: ["shoulder-impingement","shoulder-overhead"], coachingCue: "Stand on the band, start with palms facing you at shoulder height.|As you press up, rotate palms away from you.|Full extension at the top without locking out.|Lower and rotate palms back to face you.|Keep core braced throughout.|Control the band on the way down." },
  "standing-lateral-dumbbell-raise": { name: "Lateral Raise", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner" , injuryFlags: ["shoulder-impingement"], coachingCue: "Stand with dumbbells at your sides.|Raise both arms out to the sides to shoulder height.|Lead with your elbows, not your wrists.|A slight forward lean and slight elbow bend is fine.|Lower with control  - don't let the dumbbells drop.|This is medial deltoid isolation. Go lighter than you think you need to."},
  "rear-delt-fly-machine": { name: "Rear Delt Fly Machine", muscle: "Shoulders", equipment: "Fly Machine", difficulty: "beginner", injuryFlags: [], coachingCue: "Chest against pad, handles in front. Push handles back in a fly motion, squeezing shoulder blades together. Control the return. Targets the rear delt." },
  "face-pull": { name: "Face Pull", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "beginner", injuryFlags: ["shoulder-impingement"], coachingCue: "Set the cable at face height with a rope attachment.|Grip both ends, step back, arms extended in front of you.|Pull the rope toward your face, spreading the ends apart reach your ears.|Elbows high and wide at the end.|Squeeze the rear delts and external rotators at the peak.|Return with control. This is one of the most important shoulder health exercises you can do." },
  "band-face-pull": { name: "Band Face Pull", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["shoulder-overhead"], coachingCue: "Attach band at eye level or slightly above.|Stand facing the anchor point holding one end of the band in each hand.|Pull the band towards your face keeping your elbows high and wide.|Squeeze your shoulder blades together at the end of the movement." },
  "side-lying-external-rotation": { name: "Side Lying Dumbbell External Rotation", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Lie on your side on a bench or floor, elbow bent at 90 degrees.|Hold a light dumbbell in the top hand.|Rotate your forearm upward, opening the shoulder externally.|Hold at the end range for a beat.|Lower back down with control.|This is rotator cuff work. Go light. Slow and controlled. This is longevity work." },
    "rope-tricep-pushdown": { name: "Rope Tricep Pushdowns", muscle: "Triceps", equipment: "Cable Machine", difficulty: "beginner", injuryFlags: ["elbow-load"], coachingCue: "High cable with rope. Keep elbows pinned to your sides. Push down and slightly apart at the bottom, fully extending. Squeeze the tricep hard at the bottom." },
    "tricep-dips": { name: "Tricep Dips", muscle: "Triceps", equipment: "Bench", difficulty: "beginner", injuryFlags: ["elbow-load","wrist-load"] , coachingCue: "Sit on the edge of a platform with hands beside hips.|Slide hips off the platform, bending elbows.|Lower hips towards the ground, then push back up.|Keep elbows close to the body.|Lower until elbows are at 90 degrees.|Engage triceps to push back up." },
    "two-hand-overhead-extension": { name: "Two Hand Overhead Extension", muscle: "Triceps", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["elbow-load","shoulder-overhead"], coachingCue: "Attach door anchor high.|Stand in a split stance facing away.|Hold the band with both hands overhead.|Extend arms overhead, engaging triceps.|Keep a stable stance and engage triceps fully at the extension.|Control the band on the descent." },
  // Same mistagging bug-bar-preacher-curl - named "EZ Bar Skull
  // Crusher", but was tagged equipment: "Barbell" instead of "EZ Bar". The
  // real dumbbell alternative (lying-dumbbell-skull-crusher) already exists
  // own correctly-tagged exercise elsewhere in this file, so the
  // existing auto-swap logic in filterExercisesByEquipment will pick it up
  // automatically for buildings without an EZ bar - no need to touch this
  // exercise's own identity to make that happen.
  "skull-crusher": { name: "EZ Bar Skull Crusher", muscle: "Triceps", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["elbow-load"], coachingCue: "Lie on bench, bar above chest. Lower toward forehead, elbows do not flare. Extend back to start. Control the lowering. No one wants to experience how this got its name." },
  "dumbbell-curl": { injuryFlags: ["elbow-load"], name: "Dumbbell Curl", muscle: "Biceps", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Stand upright, dumbbells at sides. Curl up keeping elbows pinned to your sides. Squeeze hard at the top. Lower with control. Do not let gravity do the work." },
      "band-upright-row": { name: "Band Upright Row", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["shoulder-impingement"], coachingCue: "Stand on the band with feet shoulder-width apart.|Hold the band with palms facing you.|Lift the band straight up towards the chin.|Keep elbows high on the pull.|Control the band on the way down." },
  "seated-lat-pulldown-band": { name: "Band Lat Pulldown", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Sit with legs bent and band attached to a high anchor.|Hold the band with palms facing forward.|Pull the band towards your chest, rotating palms to face each other, engaging lats.|Maintain a straight back.|Squeeze shoulder blades together.|Control the band on the return." },
        "goblet-squat": { name: "Goblet Squat", muscle: "Quads", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["knee-deep-flexion"], coachingCue: "Hold weight at chest, feet shoulder-width, toes slightly out. Squat between your legs keeping elbows inside your knees. Chest up throughout. Drive through heels to stand." },
  "barbell-squat": { name: "Barbell Back Squat", muscle: "Quads", equipment: "Barbell", difficulty: "advanced", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Bar across your upper back, feet shoulder-width, toes slightly out.|Brace your core and take a breath.|Lower until your thighs are at least parallel to the floor.|Drive through your heels to stand.|Keep your chest up and knees tracking over your toes throughout.|The squat is a full-body movement. Treat it like one."},
            "low-platform-on-off-step": { name: "Low Platform On/Off Step", muscle: "Quads", equipment: "Step Platform", difficulty: "beginner", coachingCue: "Step up onto the platform one foot at a time | Step back down the same way — controlled, not a drop | Keep your chest up and core braced throughout | Lead with the same foot for all reps, then switch | Land quietly — noise means you're not absorbing the impact | Simple movement, but own every step" },
  "lying-alternate-leg-raise": { name: "Lying Alternate Leg Raise", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["hip-flexion-loaded","lumbar-flexion-loaded"], coachingCue: "Lie flat, lower back pressed into the floor | Raise one leg to about 45 degrees while the other stays low | Lower with control before switching | The lower the leg, the harder the core works | Don't let your lower back arch off the floor | Slow and steady beats fast and sloppy here" },
  "cardio-options": { name: "Cardio Options", muscle: "Cardio", equipment: "Varies", difficulty: "beginner", coachingCue: "Pick your machine or modality and commit to it | Keep intensity steady — conversational pace unless noted | Focus on duration over speed, especially early in the program | Breathe through your nose if you can | This is active recovery is conditioning | Show up for the cardio the same way you show up for the lifts" },
    "single-leg-press": { name: "Machine Single Leg Press", muscle: "Quads", equipment: "Leg Press Machine", eachLeg: true, difficulty: "intermediate", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "One foot centered on the platform, the other stays off | Lower until knee hits 90 — don't let it cave in | Press through your whole foot, not just the toes | Hips stay flat against the seat the whole time | Full extension at the top without locking the knee | Match reps and depth on both sides" },
  "cable-rear-delt-fly": { name: "Cable Rear Delt Fly", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "intermediate", coachingCue: "Set cables at face height, cross the handles | Slight hinge at the hips, soft knee bend | Pull the handles out and back in a wide arc | Lead with your elbows, not your hands | Squeeze your rear delts at the end of the pull | Keep your core braced — don't rock to generate momentum" },
  "dumbbell-side-lunge": { name: "Dumbbell Side Lunge", muscle: "Quads", equipment: "Dumbbells", eachLeg: true, difficulty: "intermediate", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Step wide to one side, push your hips back lower | Bend the working leg, keep the other leg straight | Chest stays up — don't fold forward at the bottom | Drive through the working heel to return to center | Keep both feet flat on the floor throughout | Own the stretch in the inner thigh before you push back" },
      "walking-lunge-bodyweight": { name: "Walking Lunge (Bodyweight)", muscle: "Quads", equipment: "Bodyweight", eachLeg: true, difficulty: "beginner", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Step forward and lower the back knee toward the floor | Front knee stays stacked over your front foot | Drive through the front heel to bring the back foot forward | Keep your torso tall — don't lean into the lunge | Arms can swing naturally for balance | Own each step before you take the next one" },
      "machine-leg-extension": { name: "Machine Leg Extension", muscle: "Quads", equipment: "Machine", difficulty: "beginner", injuryFlags: [], coachingCue: "Sit tall with your back flat against the pad | Ankle pad sits just above the foot | Extend fully at the top — squeeze the quad | Lower slowly, don't let the weight crash down | Keep hips glued to the seat throughout | Control is the whole point of this machine" },
    "band-stiff-leg-deadlift": { name: "Band Stiff Leg Deadlift", muscle: "Hamstrings", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Stand on the band with feet hip-width apart.|Hinge at the hips, keeping knees slightly bent.|Lower the band towards the ground, then return.|Maintain a straight back.|Keep a slight bend in the knees.|Engage hamstrings and glutes." },
                "band-glute-bridge": { name: "Banded Glute Bridge", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Lie on your back with the band just above your knees, feet flat on the floor.|Drive your knees outward against the band press your hips up.|Squeeze your glutes hard at the top  - hold for one full second.|Lower with control and repeat.|The band adds lateral resistance that activates the hip abductors and outer glutes.|Push your knees out the entire time. Don't let them cave in." },
  "dumbbell-hip-thrust": { injuryFlags: ["hip-flexion-loaded"], name: "Dumbbell Hip Thrust", muscle: "Glutes", equipment: "dumbbell", difficulty: "beginner", coachingCue: "Upper back on bench, dumbbell on hips. Feet flat, shoulder-width. Drive hips to ceiling, fully extending. Squeeze hard at the top. Lower with control." },
  "cable-kickback": { name: "Cable Kickback", muscle: "Glutes", equipment: "Cable Machine", eachLeg: true, difficulty: "beginner" , coachingCue: "Attach a single handle to the low cable, hinge forward at the hips.|Keep your upper arm pinned close to your side, elbow at 90 degrees.|Extend your forearm straight back to full lockout.|Squeeze the tricep hard at the top.|Return with control.|This is isolation work  - keep the upper arm completely still."},
    "lying-scissors": { name: "Lying Scissors", muscle: "Core", equipment: "Bodyweight", isTime: true, difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded"] , coachingCue: "Lie flat on your back, hands under your glutes, lower back pressed into the floor.|Raise both legs a few inches off the floor.|Scissor your legs  - one goes up other stays low, then switch.|Keep both legs throughout.|The lower the legs, the more lower ab demand  - adjust height based on your strength.|Keep breathing. Don't hold your breath through the movement."},
  "modified-side-plank": { injuryFlags: ["wrist-load"], name: "Modified Side Plank", muscle: "Core", equipment: "Bodyweight", eachSide: true, isTime: true, difficulty: "beginner" , coachingCue: "Lie on your side, supporting your body on your elbow.|Keep your body in a straight line.|Hold the position for the specified time.|Elbow directly beneath the shoulder.|Engage core to prevent sagging.|Switch sides for balanced work." },
  "side-elbow-plank": { name: "Side Plank", muscle: "Core", equipment: "Bodyweight", eachSide: true, isTime: true, difficulty: "intermediate", injuryFlags: ["shoulder-impingement"], coachingCue: "On one forearm and the side of one foot, body in a straight line. Drive your hip up away from the floor. Do not let it sag. Hold steady. Obliques are working." },
    "dead-bug": { name: "Dead Bug", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Lie flat on your back, arms extended toward the ceiling, knees at 90 degrees.|Press your lower back firmly into the floor  - it stays there the entire set.|Lower one arm overhead and the opposite leg toward the floor simultaneously.|Return to start and alternate sides.|The challenge is keeping your lower back pressed down while your limbs move.|Go slow. Control is everything here." },
        "russian-twists": { name: "Russian Twists", muscle: "Core", equipment: "Bodyweight", eachSide: true, difficulty: "intermediate", injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Seated, feet elevated off floor, leaning back. Twist side to side. The elevated feet increase core demand significantly." },
  "mountain-climbers": { name: "Mountain Climbers", muscle: "Core", equipment: "Bodyweight", isTime: true, difficulty: "beginner", injuryFlags: ["hip-flexion-loaded"], coachingCue: "Hands on floor, body in high plank. Drive knees to chest alternately allows.|Core stays tight throughout — don't let the hips rise or sag.|Pick a tempo you can sustain for the full interval.|Slow mountain climbers = core exercise. Fast = cardio and core.|Drive the knee all the way through and return to full extension each rep." },
    "single-leg-lateral-leap": { name: "Single-Leg Lateral Leaps", muscle: "Cardio", equipment: "Bodyweight", difficulty: "advanced", eachLeg: true, injuryFlags: ["ankle-impact"], coachingCue: "Leap laterally off one foot and land on the opposite. Develop single-leg power and lateral explosiveness. Land softly with a bent knee." },
  "box-jump": { name: "Box Jumps", muscle: "Quads", equipment: "Plyo Box", difficulty: "intermediate", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand in front of a box, feet hip-width.|Bend your knees and swing your arms back.|Jump explosively, landing softly on top of the box with bent knees.|Step back down  - don't jump down.|Reset and repeat.|Land on the full foot, not just your toes. Soft landing protects your joints."},
  "v-up-toe-touch": { name: "V-Up Toe-Touches", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"] , coachingCue: "Lie flat, arms extended overhead, legs straight.|Simultaneously raise your arms and legs, reaching your hands toward your feet at the top.|Your body forms a V-shape at the peak.|Lower with control  - arms and legs go back down together.|Keep your legs straight throughout.|This is a full-body core compression. The challenge is keeping both halves moving at the same rate."},
    "cable-ab-twist": { name: "Oblique Cable Twists", muscle: "Core", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true, injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Cable at shoulder height, stand perpendicular. Rotate pulling cable across your body. Obliques and core stabilizers resist rotation. Keep hips still." },
      "back-row-machine-wide-pronated": { name: "Back Row Machine (Wide Pronated)", muscle: "Back", equipment: "Row Machine", difficulty: "intermediate", coachingCue: "Chest against the pad, grip the handles. Pull back squeezing shoulder blades like holding a pencil between them. Full extension forward before the next rep." },
  // Was mistagged equipment: "Barbell" - a copy-paste slip from a nearby
  // barbell exercise, almost certainly, since every other EZ bar exercise
  // in this file is correctly tagged "EZ Bar" and this one is even named
  // "Ez Bar Preacher Curl". The mistagging meant the equipment filter
  // matched it against a building's barbell instead of checking for the
  // actual EZ curl bar it requires, so it was recommended to buildings that
  // genuinely didn't have the right equipment. The existing swap logic in
  // filterExercisesByEquipment already handles finding a same-muscle
  // alternative automatically once the equipment check correctly fails -
  // this one-line retag is the entire fix needed.
  "ez-bar-preacher-curl": { name: "Ez Bar Preacher Curl", muscle: "Biceps", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["elbow-load"], coachingCue: "Chest on preacher pad, arms over the angled surface. Curl up, elbows stay on the pad. Eliminates cheating completely. Full extension at the bottom." },
  "standing-cable-pallof-press": { injuryFlags: ["lumbar-rotation-loaded"], name: "Standing Cable Pallof Press", muscle: "Core", equipment: "Cable Machine", difficulty: "intermediate", coachingCue: "Stand sideways to cable. Press straight out at chest height. Hold briefly. Resist rotation throughout. Core braced the entire time. Don't let the cable pull you." },
  "alternating-cross-body-dumbbell-curl": { injuryFlags: ["elbow-load"],name: "Alternating Cross-Body Dumbbell Curls", muscle: "Biceps", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, coachingCue: "Alternate curling each arm across your body toward the opposite shoulder. This angle hits the outer bicep and brachialis differently." },
  "back-row-machine": { name: "Back Row Machine (Narrow Neutral)", muscle: "Back", equipment: "Row Machine", difficulty: "intermediate", coachingCue: "Chest on pad, neutral grip. Row back evenly, elbows tracking close to your body. Pause and squeeze at the end of each rep." },
  "side-plank-with-rotation": { injuryFlags: ["lumbar-rotation-loaded","wrist-load"], name: "Foot-on-Foot Needle-Threading Side Planks", muscle: "Core", equipment: "Bodyweight", difficulty: "advanced", eachSide: true, isTime: true, coachingCue: "Get into a side plank on your elbow, feet stacked.|From this position, rotate your top arm under your body, threading it toward the ground.|Return to the side plank and repeat.|This combines a side plank hold with thoracic rotation.|Keep your hips elevated throughout  - don't let them drop.|Advanced oblique and rotational core challenge." },
      "lying-dumbbell-skull-crusher": { name: "Lying Dumbbell Skull Crushers", muscle: "Triceps", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["elbow-load"], coachingCue: "Lying on bench, dumbbells above chest. Lower toward temples, elbows forward. Extend back to lockout. Dumbbells allow independent arm movement." },
    "incline-plate-press": { name: "Incline Plate Press (30-45°)", muscle: "Chest", equipment: "Weight Plate", difficulty: "advanced", coachingCue: "Set the bench to 30 to 45 degrees, grip the outside edges of a weight plate.|Press the plate overhead from chest height.|Squeeze hard at the top.|Lower with control back to your chest.|The plate keeps your hands together, changing the pressing angle.|Focus on the upper chest squeeze at the top of every rep." },
      "drop-jumps": { name: "Chair Drop Max-Jumps", muscle: "Quads", equipment: "Plyo Box", difficulty: "advanced", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Stand on a box or sturdy chair.|Step off  - don't jump off.|The instant your feet hit the ground, explode upward can.|This is reactive strength training  - the goal is minimum ground contact time.|Land softly and reset before the next rep.|High intensity. Quality over quantity on this one." },
    "walking-lunge-dumbbell-curl": { name: "Walking Lunges & Dumbbell Curls", muscle: "Full Body", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["elbow-load","hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Hold dumbbells at your sides.|Step into a lunge.|At the bottom of each lunge, curl both dumbbells up.|Lower the dumbbells and drive through your front heel to step forward.|Alternate legs walk.|The curl happens at the bottom of the lunge  - one fluid movement. Legs and arms work simultaneously." },
  "lying-flutter-kick": { name: "Lying Flutter Kicks", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", isTime: true, coachingCue: "Lie flat on your back, hands under your glutes, lower back pressed into the floor.|Raise both legs a few inches off the floor.|Alternate kicking up and down in small, fast, controlled movements.|The lower your legs, the harder it is  - adjust height to your strength level.|Keep your lower back flat  - if it arches, raise your legs higher.|This is endurance work for the hip flexors and lower abs. Keep breathing."},
  "standing-back-alternating-row": { name: "Standing Back Alternating Row (attach low)", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", eachSide: true , coachingCue: "Attach band to a middle fixed point.|Hold the band with palms facing each other.|Lift arms out to the sides, targeting upper back.|Keep a slight bend in the elbows.|Squeeze the shoulder blades together.|Control the band on the return." },
      "alt-side-bend-band": { name: "Standing Alternating Side Bend", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", eachSide: true , coachingCue: "Stand with feet shoulder-width apart.|Hold the band with one hand, bend to the side.|Alternate sides for each repetition.|Keep a straight back.|Engage the obliques.|Control the band on the way up." },
  "external-shoulder-rotation-band": { injuryFlags: ["lumbar-rotation-loaded"], name: "External Shoulder Rotation (Band)", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", eachSide: true , coachingCue: "Attach bands to an anchor at waist level.|Hold the band with one hand, elbow at 90 degrees.|Rotate the forearm outward, engaging the shoulder.|Keep the elbow close to the body.|Control the rotation.|Engage the shoulder muscles."},
  "kneeling-ab-crunch-band": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"],name: "Kneeling Crunch (Band)", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Attach the band high on a door anchor.|Kneel facing away, hold the band behind your head.|Crunch forward, engaging the core.|Keep a neutral spine.|Engage the core throughout the movement.|Control the band on the way back." },
  "abduction-ankle-straps": { injuryFlags: [], name: "Single Leg Hip Abduction (Ankle Straps)", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true , coachingCue: "Use ankle straps for this exercise.|Lift one leg out to the side, engaging hip muscles.|Hold onto something for stability if needed.|Keep a straight leg during the lift.|Engage the hip muscles.|Control the leg on the way down."},
  "lying-reverse-crunch-band": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"],name: "Reverse Crunch (Band, attach low)", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Lie on your back with hands behind your head.|Bring opposite knee and elbow towards each other, cycling legs.|Use resistance band for added tension.|Engage core throughout the movement.|Keep the lower back pressed into the floor.|Maintain a steady pace." },
    "sit-up-knee-grab": { name: "Sit-Up Knee Grab", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Lie on your back with knees straight.|Perform a sit-up, bringing knees towards chest.|Reach for your knees at the top of the movement.|Engage core throughout the movement.|Bring knees towards chest.|Reach for knees at the top." },
    "commando-plank": { name: "Commando Plank", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", isTime: true, injuryFlags: ["wrist-load"] , coachingCue: "Start in a plank position.|Lower down to forearms, then back up to hands.|Maintain a straight line from head to heels.|Keep hips stable and body in a straight line.|Alternate between hands and forearms.|Engage core throughout the movement." },
  "laydown-pushup": { name: "Laydown Pushups", muscle: "Chest", equipment: "Bodyweight", difficulty: "intermediate" , injuryFlags: ["wrist-load"], coachingCue: "Start in a plank position.|Slowly lower hips to one side.|Return to plank and switch sides.|Keep hips stable and body in a straight line.|Rotate from the core.|Engage obliques during the rotation." },
  "low-side-side-lunge": { name: "Low Side-Side Lunge", muscle: "Quads", equipment: "Bodyweight", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand with feet wider than shoulder-width apart.|Shift weight to one side, bending that knee.|Alternate sides before completing a set.|Keep back straight and chest up.|Push hips back during the lunge.|Engage inner thighs and glutes." },
  "walking-lunge-band": { name: "Walking Lunge (Band)", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand with feet together.|Take a step forward with one leg, lowering into a lunge.|Alternate legs, walking forward with each lunge.|Keep a straight back and chest up.|Lower the back knee towards the ground.|Take controlled steps with each lunge." },
  "band-leg-extension": { name: "Band Leg Extension", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, injuryFlags: [], coachingCue: "Attach band low on a door anchor.|Stand away from door anchor until you feel tension.|Extend one leg back against resistance.|Return to starting position.|Control the leg movement.|Keep the core engaged for stability.|Ensure a smooth, controlled extension." },
  "band-lateral-walk": { name: "Band Crab Walk", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", isTime: true , coachingCue: "Place band slightly above knees.|Assume a squat position and walk sideways.|Take two steps in each direction.|Keep a low squat position.|Maintain constant tension on the band.|Perform controlled, deliberate steps." },
    "standing-single-leg-hamstring-curl": { injuryFlags: [], name: "Single Leg Standing Hamstring Curl (Band)", muscle: "Hamstrings", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true , coachingCue: "Stand on one leg, hold onto something for stability.|Curl the other leg towards the glutes.|Engage hamstrings during the curl.|Keep a stable stance on the standing leg.|Control the movement throughout.|Engage hamstrings fully at the curl."},
  "band-pullthroughs": { name: "Band Pullthroughs", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Loop the band around a fixed point.|Face away from the anchor point and pull the band through your legs.|Stand up, engaging glutes at the top.|Hinge at the hips during the pull.|Squeeze glutes at the top.|Keep a slight bend in the knees." },
  "salsa-plank": { injuryFlags: ["wrist-load"],name: "Salsa Plank", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", eachSide: true, coachingCue: "Start in a plank position.|Slowly lower hips to one side.|Return to plank and switch sides.|Keep hips stable and body in a straight line.|Rotate from the core.|Engage obliques during the rotation." },
  "squatting-concentration-curl": { injuryFlags: ["elbow-load","knee-deep-flexion","knee-impact","knee-shear"], name: "Squatting Concentration Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", eachSide: true , coachingCue: "Perform a squat with a band under feet.|Curl the band towards the shoulder, one arm at a time.|Keep a stable stance and engage biceps.|Maintain tension on the band.|Fully contract biceps at the curl.|Control the band on the descent." },
  "standing-back-fly-band": { name: "Standing Back Fly (Band)", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Stand on the band with feet shoulder-width apart.|Lift one arm straight in front and the other out to the side simultaneously.|Control the descent of the band.|Keep a slight bend in the elbows.|Lift arms to shoulder height.|Control the band on the way back." },
  "thrusters-band": { name: "Band Thruster", muscle: "Full Body", equipment: "Resistance Band", difficulty: "intermediate" , coachingCue: "Stand on the band with feet shoulder-width apart.|Hold the band at shoulder height.|Perform a squat, then press band overhead.|Keep a straight back during the squat.|Press through heels when standing.|Fully extend arms overhead." },
          "band-lunge": { name: "Band Lunge", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand with one foot on the band, holding the handles at shoulder height.|Step back with the opposite foot, lowering the back knee towards the ground.|Drive through the front foot on the band back to the starting position.|Repeat for desired reps.|Switch legs and complete reps to finish the set.|Keep a straight back and chest up throughout." },
    "resistance-band-curtsy-lunge": { name: "Curtsy Drop Lunge (Band)", muscle: "Glutes", equipment: "Resistance Band", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand with feet together.|Step back into a lunge at an angle, dropping the back knee towards the ground.|Alternate legs after desired reps.|Lower back knee towards the ground.|Keep a straight back and chest up.|Engage glutes and quads." },
  "squatting-curl-band": { injuryFlags: ["elbow-load","knee-deep-flexion","knee-impact","knee-shear"], name: "Squatting Curl (Band)", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Stand on the band with feet hip-width apart.|Hold the band with palms facing up.|Perform bicep curls, fully contracting the muscles.|Keep elbows close to the body.|Fully contract biceps at the top.|Control the band on the way down." },
  "lying-single-leg-raise-band": { injuryFlags: ["hip-flexion-loaded","lumbar-flexion-loaded"], name: "Lying Single Leg Raise (Band)", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true , coachingCue: "Attach band to a low fixed point.|Lie on your back with legs extended.|Raise one leg at a time towards the ceiling.|Engage the core throughout.|Keep a neutral spine.|Engage lower abs.|Control the movement to avoid straining the lower back." },
    "chest-fly-band": { name: "Chest Fly (Band)", muscle: "Chest", equipment: "Resistance Band", difficulty: "beginner" , injuryFlags: ["shoulder-impingement"], coachingCue: "Start in a split stance with band under back foot.|Press one hand towards the ceiling, alternating sides.|Keep a slight bend in the elbows.|Engage chest muscles during the press.|Maintain a stable core.|Control the band on the descent." },
  "overhead-extension-band": { name: "Overhead Extensions (Band)", muscle: "Triceps", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["elbow-load","shoulder-overhead"] , coachingCue: "Stand with one foot on the band.|Hold the band with one hand, extend arm overhead.|Perform overhead extensions, targeting triceps.|Keep a stable stance on the band.|Engage triceps fully at the extension.|Control the band on the descent." },
          "band-bent-over-back-fly": { name: "Reverse Fly (Band)", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Hold a resistance band in front of you.|Pull the band apart, squeezing the shoulder blades.|Return to the starting position.|Keep a slight bend in the elbows.|Squeeze the shoulder blades together.|Control the band on the return." },
  "band-hip-flexor": { injuryFlags: ["hip-flexion-loaded"], name: "Band Hip Flexor Kick", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true , coachingCue: "Anchor the resistance band low behind you.|Stand facing away from the anchor point with the band around one ankle.|With your legs straight kick forwards feeling tension on the band.|Stay balanced and engage hip flexor during the movement.|Option to hold onto something for stability." },
  "band-kickback": { name: "Band Kickback", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true , coachingCue: "Stand on the band, hinge at the hips.|Hold the band with palms facing back.|Extend arms straight back, engaging triceps.|Keep a slight bend in the elbow.|Squeeze triceps at the top.|Maintain a stable, bent-over position." },
  "lying-knee-ins-band": { name: "Lying Knee-Ins (Band)", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Lie on your back with the resistance band looped around your ankles.|Keep your arms flat by your sides for stability.|Bring your knees towards your chest engaging your core.|Slowly lower your legs back down and repeat." },
  "band-sit-up": { name: "Band Sit-Up", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Lie on your back, anchor band low.|Lift the legs towards the ceiling.|Perform a reverse crunch, lifting hips off the ground.|Keep a neutral spine.|Engage lower abs during the lift.|Control the descent of the legs." },
  "seated-band-russian-twist": { name: "Band Russian Twist", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", eachSide: true, injuryFlags: ["lumbar-rotation-loaded"] , coachingCue: "Sit on the floor with legs extended and knees slightly bent.|Loop the resistance band around your feet and hold the ends with both hands.|Lean back slightly to engage your core muscles.|Twist your torso to one side, bringing the band towards your hip.|Return to the center and then twist to the other side.|Keep your core engaged and maintain tension on the band throughout." },
  "reverse-wood-chop": { injuryFlags: ["lumbar-rotation-loaded"], name: "Reverse Wood Chop (Band)", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Anchor the resistance band low to your side.|Stand sideways to the anchor point holding the band with both hands.|Pull the band up and across your body in a chopping motion rotating your torso.|Keep your core engaged and control the movement.|Return to the starting position and repeat." },
  "pronated-grip-row-band": { name: "Pronated Grip Row (Band)", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Sit on the ground with legs bent and bands attached to a low anchor point.|Hold the band with palms facing down.|Pull the band towards your upper chest, squeezing shoulder blades.|Keep a straight back.|Squeeze shoulder blades together.|Control the band on the return." },
  "banded-fire-hydrants": { name: "Banded Fire Hydrants (with hold)", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, coachingCue: "Place band around knees.|Get on all fours, lift one knee out to the side.|Optionally hold at the top for 10-15 secs for increased difficulty.|Keep a 45-degree angle during leg lift.|Engage outer glutes and hips.|Add a hold for an extra challenge." },
    "seated-neutral-grip-row": { name: "Seated Neutral Grip Row (Band)", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Stand on the band with feet shoulder-width apart.|Hold the band with palms facing you.|Lift the band straight up towards the chin.|Keep elbows high on pull.|Lift the band towards the chin.|Control the band on the way down." },
    "trap-bar-squat": { name: "Trap Bar Squat", muscle: "Quads", equipment: "Trap Bar", difficulty: "intermediate", injuryFlags: ["lumbar-hinge-heavy", "knee-deep-flexion"] , coachingCue: "Stand inside the trap bar, handles at your sides.|Hinge and grip the handles.|Drive through your heels to stand tall.|Lower with control, sitting the hips back and down.|The trap bar keeps the weight in line with your center of gravity  - more knee-friendly than a barbell squat.|Full depth, flat back."},
  "machine-hamstring-curl": { injuryFlags: [], name: "Machine Hamstring Curl", muscle: "Hamstrings", equipment: "Leg Curl Machine", difficulty: "beginner" , coachingCue: "Lie face down on the machine, pad positioned just above your heels.|Curl your legs up toward your glutes.|Squeeze the hamstrings hard at the top.|Lower with control  - 2 to 3 seconds down.|Don't let your hips rise off the pad curl.|Full range both ways."},
  "machine-single-leg-extension": { name: "Machine Single Leg Extensions", muscle: "Quads", equipment: "Leg Extension Machine", difficulty: "beginner", eachLeg: true, injuryFlags: [] , coachingCue: "Sit in the leg extension machine, one leg on the pad.|Extend to full lockout, squeezing the quad hard at the top.|Lower with control.|Single-leg extensions correct strength imbalances between your quads.|Don't swing the leg  - slow and controlled.|The non-working leg stays relaxed."},
  "kettlebell-rdl": { name: "Kettle Bell Romanian Deadlift", muscle: "Hamstrings", equipment: "Kettlebell", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "KB held in front of thighs or one in each hand. Hip hinge, soft knee bend. Lower until you feel the hamstring stretch. Drive hips forward, stand tall." },
  "dumbbell-split-squat": { name: "Dumbbell Split Squats", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand in a split stance, dumbbells at your sides.|Lower your back knee toward the floor.|Drive through your front heel to return to the top.|Unlike a lunge, your feet stay planted throughout the set.|Find a comfortable split stance width for your hips.|Chest up, torso upright."},
      "dumbbell-frog-pump": { name: "Dumbbell Frog Pumps", muscle: "Glutes", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Lie on your back, bring the soles of your feet together with knees wide.|Hold a dumbbell across your hips.|Drive your hips up, squeezing your glutes hard at the top.|Lower with control and repeat.|The wide knee position changes the angle of hip extension and hits the glutes in a unique way.|Short range movement  - but maximum tension throughout." },
  "barbell-deadlift": { name: "Barbell Deadlift", muscle: "Hamstrings", equipment: "Barbell", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Stand with feet hip-width, bar over your midfoot.|Hinge at the hips, grip the bar just outside your legs.|Brace your core hard, chest up, back flat  - not rounded.|Drive your feet through the floor and pull the bar up along your legs.|Lock out at the top  - hips forward, glutes squeezed.|Lower with control. Bar stays close to your body the whole way down." },
    "pause-single-leg-machine-extension": { injuryFlags: [], name: "Pause Single Leg Machine Leg Extensions", muscle: "Quads", equipment: "Leg Extension Machine", difficulty: "intermediate", eachLeg: true , coachingCue: "Sit in the leg extension machine, adjust the pad above one foot.|Extend to full lockout and hold for 2 to 3 seconds.|Lower with control.|The pause at the top eliminates momentum and increases quad tension.|Go lighter than usual  - the pause makes it significantly harder.|Keep the non-working leg relaxed."},
              "kettlebell-deadlift": { name: "Kettle Bell Deadlift", muscle: "Hamstrings", equipment: "Kettlebell", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "KB between feet. Hip hinge to pick up. Back stays flat, hips are the hinge. Drive through heels, stand tall with hips and knees extended." },
    "plyo-lunge-switches": { name: "Plyo Lunge Switches (no weights)", muscle: "Quads", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear","ankle-impact"], coachingCue: "Bodyweight jump lunge, switching legs in the air each rep. Land softly. Develops single-leg power and cardiovascular conditioning." },
  "cable-glute-kickback": { name: "Cable Machine Glute Kickbacks", muscle: "Glutes", equipment: "cable", difficulty: "beginner", eachLeg: true, coachingCue: "Stand facing machine, ankle strap. Drive leg back and slightly up. Controlled movement. Lean slightly for support." },
            "incline-dumbbell-fly": { name: "Incline Dumbbell Flyes", muscle: "Chest", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["shoulder-impingement"], coachingCue: "Incline bench, dumbbells held above chest. Lower arms in a wide arc with soft elbows, feeling the stretch across your chest. Bring back up squeezing the chest." },
    "assisted-machine-chest-dip": { name: "Assisted Machine Chest Dips", muscle: "Chest", equipment: "Assisted Dip Machine", difficulty: "intermediate", injuryFlags: ["elbow-load","wrist-load"], coachingCue: "Lean forward significantly to hit chest over triceps. Lower until you feel a stretch in your chest. Press back up through your palms. The forward lean is everything." },
    "seated-alternating-zottman-curl": { injuryFlags: ["elbow-load"], name: "Seated Alternating Zottman Curls", muscle: "Biceps", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, coachingCue: "Curl up with palms supinated, then rotate to pronated on the way down. The eccentric with a pronated grip loads the brachialis and brachioradialis." },
  "bosu-ball-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Bosu Ball Crunches", muscle: "Core", equipment: "Bosu Ball", difficulty: "beginner" , coachingCue: "Sit on top of the bosu ball  - dome side up  - and walk your feet out until your lower back is resting on the ball.|Arms crossed at your chest or hands behind your head.|Crunch up, then extend back over the ball to get the full stretch at the bottom.|The bosu gives you a greater range of motion than the floor.|Let your spine follow the curve of the ball on the way back.|Don't just shorten the range to make it easier  - the stretch is the point."},
    "alternating-dumbbell-bench-press": { name: "Alternating Dumbbell Bench Press", muscle: "Chest", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, injuryFlags: ["shoulder-impingement"], coachingCue: "Flat bench. Press one arm up while the other stays at chest. Alternating challenges your stability and core. Keep the non-pressing arm controlled." },
        "seated-supinated-cable-row": { injuryFlags: ["lumbar-flexion-loaded"],name: "Seated Supinated Cable Row", muscle: "Back", equipment: "Cable Machine", difficulty: "intermediate", coachingCue: "Underhand grip, sit tall. Pull to your lower abs, elbows hugging your sides. Supinated grip allows a deeper squeeze and increases bicep engagement." },
        "side-motion-pushup": { name: "Side Motion Pushups", muscle: "Chest", equipment: "Bodyweight", difficulty: "intermediate", eachSide: true , injuryFlags: ["wrist-load"], coachingCue: "Start in a pushup position.|Lower your chest to the floor.|As you press up, shift your bodyweight to one side, opening into a side plank briefly.|Return to center and repeat to the other side.|This adds lateral movement and oblique engagement to a standard pushup.|Keep your core locked and hips level throughout."},
    "ez-bar-upright-row": { name: "EZ Bar Upright Row", muscle: "Shoulders", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["shoulder-impingement"], coachingCue: "Narrow grip on EZ bar. Pull bar up to chin, elbows drive high. EZ bar reduces wrist strain versus straight bar. Hold at top, lower controlled." },
  "seated-dumbbell-alt-front-raise": { injuryFlags: ["shoulder-impingement"],name: "Seated Dumbbell Alternating Front Raises", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, coachingCue: "Seated upright. Alternate raising each arm forward to shoulder height. Sitting removes leg drive and isolates the front delt." },
        "banded-pushup": { name: "Banded Pushups", muscle: "Chest", equipment: "Resistance Band", difficulty: "intermediate" , injuryFlags: ["wrist-load"], coachingCue: "Get into a pushup position with hands close together.|Lower the chest towards the hands, forming a diamond shape.|Press back up to the starting position.|Keep the elbows close to the body.|Engage the chest and triceps.|Control the descent and ascent." },
      "standing-dumbbell-front-raise": { injuryFlags: ["shoulder-impingement"], name: "Dumbbell Standing Front Raises", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner" , coachingCue: "Stand with dumbbells at your sides, palms facing your thighs.|Raise one or both arms straight in front to shoulder height.|Keep a slight bend in the elbows.|Lower with control.|Don't swing your torso to generate momentum.|This isolates the anterior deltoid."},
  "swiss-ball-hamstring-curl": { injuryFlags: [], name: "Stability Ball Hamstring Curl", muscle: "Hamstrings", equipment: "Swiss Ball", difficulty: "intermediate", coachingCue: "Lying on back, both heels on Swiss ball. Bridge hips up. Curl ball toward glutes then extend back out. Keep hips elevated throughout."},
  "dumbbell-curl-to-press": { injuryFlags: ["elbow-load"], name: "Dumbbell Curl to Press", muscle: "Full Body", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Curl dumbbells up then press overhead in one fluid movement. Bicep and shoulder combined. Control both the curl and press phases." },
        "half-kneeling-single-arm-lat-pulldown": { name: "1/2 Kneeling Single Arm Lat Pulldowns", muscle: "Back", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true, coachingCue: "Kneeling increases core demand. Single arm pulls let you focus each side. Pull elbow to hip. No rotation in your torso." },
  "half-kneeling-rear-delt-pull": { name: "1/2 Kneeling Rear Delt Pulls", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true, coachingCue: "Half kneeling, cable at face height. Pull handle to your temple in a rear delt motion. Single arm, controlled. Rear delt and external rotator cuff." },
  "ez-bar-wide-grip-upright-row": { name: "EZ Bar Wide Grip Upright Row", muscle: "Shoulders", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["shoulder-impingement"], coachingCue: "Wider grip on EZ bar for upright row. Wide grip shifts the load more toward the lateral deltoid and less to the traps. Drive elbows up and out." },
  "ez-bar-wide-grip-underhand-row": { name: "Bent Over EZ Bar Supinated Row", muscle: "Back", equipment: "EZ Bar", difficulty: "intermediate", coachingCue: "Underhand wide grip, bent at hips. Pull to your upper abs, elbows wide. Targets upper back and rear delts differently than close grip." },
  "incline-close-grip-press": { name: "Incline Close Grip Press", muscle: "Chest", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["elbow-load"], coachingCue: "Incline bench, narrow grip on bar. Close grip increases tricep involvement while incline keeps the upper chest targeted. Lower to upper chest and press back up." },
      "cable-upright-row-single-handle": { name: "Cable Upright Row (single handle)", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true, injuryFlags: ["shoulder-impingement"], coachingCue: "Single handle allows natural elbow path. Pull to chin height, elbow driving up. Alternate sides or do one complete set per side." },
  "lying-bicycle-leg-extension": { name: "Lying Bicycle Leg Extensions", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Lying on back, alternate extending each leg straight while the other bends. Core braces to prevent lower back from arching." },
  "oblique-side-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded","lumbar-rotation-loaded"],name: "Oblique Side Crunches", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Lying on your side, crunch upward toward your hip. Pure oblique isolation. Full range on each rep." },
  "trx-jump-squat": { name: "TRX Jump Squat", muscle: "Quads", equipment: "TRX", difficulty: "intermediate", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Hold the TRX handles, lean back slightly.|Lower into a squat.|Explode up can.|Land softly, immediately lowering back into the next squat.|The TRX provides just enough stability to let you focus on the explosive power.|Absorb each landing with control."},
          "reverse-lat-pulldown": { name: "Reverse Grip Lat Pulldown", muscle: "Back", equipment: "Cable Machine", difficulty: "beginner", injuryFlags: ["shoulder-overhead"], coachingCue: "Underhand grip, shoulder-width. Lean back slightly, pull bar to chest. Reverse grip recruits biceps more and shifts lat activation toward the lower portion." },
          "overhead-rope-tricep-extension": { name: "Overhead Rope Tricep Extensions", muscle: "Triceps", equipment: "Cable Machine", difficulty: "intermediate", injuryFlags: ["elbow-load"] , coachingCue: "Attach the rope to the high cable, face away from the stack.|Grip both ends of the rope, bring them behind your head.|Extend your forearms forward to full lockout, spreading the rope slightly at the end.|Squeeze the triceps at full extension.|Return with control, full stretch behind your head.|Keep your upper arms close to your ears the whole time."},
      "ab-curl-machine": { injuryFlags: ["hip-flexion-loaded","lumbar-flexion-loaded"], name: "Machine Ab Crunch", muscle: "Core", equipment: "Ab Curl Machine", difficulty: "beginner", coachingCue: "Seated in ab crunch machine. Crunch elbows toward knees. Squeeze abs hard at the bottom. Control the return."},
    "hammer-dumbbell-curl-to-overhead-press": { name: "Hammer Dumbbell Bicep Curl to Overhead Press", muscle: "Full Body", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["elbow-load","shoulder-overhead","neck-flexion"], coachingCue: "Neutral grip curl, then press overhead. Hammer grip through both movements. Full arm and shoulder recruitment in one exercise." },
  "mini-band-pushup": { name: "Mini Band Pushups", muscle: "Chest", equipment: "Resistance Band", difficulty: "intermediate", injuryFlags: ["wrist-load"], coachingCue: "Band around wrists. As you push up, the band creates outward resistance forcing your chest and shoulders to stabilize. Enhances muscle activation." },
        "kneeling-ab-wheel-rollout": { name: "Kneeling Ab Wheel Rollout", muscle: "Core", equipment: "Ab Wheel", difficulty: "advanced", coachingCue: "On knees, ab wheel extended forward can maintain a braced core. Roll back in. One of the most effective core exercises." },
          "kettle-bell-sumo-squat": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"],name: "Kettle Bell Sumo Squat", muscle: "Glutes", equipment: "Kettlebell", difficulty: "intermediate", coachingCue: "Wide stance, KB hanging between legs. Descend between your legs, chest up. Drive through whole foot and squeeze glutes stand." },
    "trx-row": { name: "TRX Row", muscle: "Back", equipment: "TRX", difficulty: "intermediate" , coachingCue: "Set the TRX handles at waist height, grip and lean back.|Body in a straight line, heels on the floor.|Pull your chest up to the handles, driving elbows back.|Squeeze your back at the top.|Lower with control.|The more horizontal your body, the harder the movement. Walk your feet forward to increase difficulty."},
  "dumbbell-lunge-pushoff": { name: "Dumbbell Lunge Pushoffs", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Lunge forward, at the bottom push off explosively with the front foot back to starting position. Single-leg power drill." },
    "alternating-medicine-ball-pushup": { name: "Lying Plyo Medicine Ball Chest Tosses", muscle: "Chest", equipment: "Medicine Ball", difficulty: "advanced", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear","wrist-load"], coachingCue: "Lie flat on your back, holding the medicine ball at your chest with both hands.|Press the ball explosively straight up into the air and release it.|Catch it on the way down, absorb into your chest, then immediately press again.|Keep your core braced. Do not arch your lower back.|This trains explosive chest power. The faster the press, the better the stimulus.|Start light until you are confident with the catch." },
    "trx-pushup": { name: "TRX Pushup", muscle: "Chest", equipment: "TRX", difficulty: "intermediate", injuryFlags: ["wrist-load"], coachingCue: "Handles at mid-height. TRX creates instability that fires more stabilizer muscles. Keep your body rigid, elbows in at 45 degrees." },
  "lying-dumbbell-external-rotation": { name: "Lying Dumbbell External Arm Rotations", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Lie on your side on a bench or floor.|Hold a light dumbbell in the top hand, elbow bent at 90 degrees, upper arm against your side.|Rotate your forearm upward, opening the shoulder externally.|Lower back down with control.|This is rotator cuff work. Always go light.|Slow, controlled, no momentum. This is health and longevity work  - take it seriously." },
    "half-kneeling-cable-woodchop": { name: "Half Kneeling Cable Woodchops", muscle: "Core", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true , injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Set the cable at shoulder height or higher. Kneel on one knee sideways to the machine.|Grip the handle with both hands and pull it down and across your body  - rotating through your torso.|Return slowly and with control.|Your hips stay facing forward  - the rotation comes from your core, not your arms.|The half-kneeling position removes your legs from the equation  - your core has to stabilize everything.|This trains rotational power in the transverse plane. Feel it in your obliques."},
  "bird-dog-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-extension","lumbar-flexion-loaded"], name: "Bird Dog Crunch", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", eachSide: true, coachingCue: "Get into a tabletop position on all fours.|Extend one arm forward and the opposite leg back simultaneously.|Then drive your elbow and knee toward each other under your body.|Return to extended and repeat.|Keep your back flat and hips square throughout.|The crunch at the end engages your core more than the standard bird dog." },
  "wall-moving-bug": { name: "Wall Moving Bug", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", eachLeg: true, coachingCue: "Stand facing a wall, hands flat on the wall at chest height.|Alternate driving your knees up toward your chest.|Stay on the balls of your feet and keep your pace controlled.|The wall position forces your core to stabilize while your legs move.|This is a standing anti-extension core exercise.|Keep your hips level  - don't let them rock side to side." },
  "half-kneeling-pallof-press": { injuryFlags: ["lumbar-rotation-loaded"], name: "Half Kneeling Pallof Press", muscle: "Core", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true , coachingCue: "Set the cable at chest height. Kneel on one knee  - the knee closest to the machine is down.|Hold the handle at your chest with both hands, elbows in.|Press it straight out from your chest  - hold for a beat  - return.|The cable is pulling you toward the machine. You're resisting that rotation the entire time.|The kneeling position removes your legs' ability to compensate  - your core has to do it all.|Don't twist. Stay square. The whole point is anti-rotation."},
  "lying-swiss-ball-pass": { name: "Swiss Ball Pass", muscle: "Core", equipment: "Swiss Ball", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Lie flat on your back, swiss ball held between your feet, arms extended overhead.|Simultaneously raise your legs and arms, passing the ball from your feet to your hands.|Lower both back to the floor with the ball in your hands.|Raise again and pass it back to your feet.|Keep your lower back pressed into the floor throughout.|This is a full range core movement. Control the descent every time." },
              "dumbbell-reverse-lunge": { name: "Dumbbell Reverse Lunge", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand holding dumbbells, step one foot straight back.|Lower your back knee toward the floor.|Drive through your front heel to return.|Keep your front shin|Alternate legs or complete full sets on each side.|This is easier on the knees than a forward lunge for most people."},
  "bent-over-row-overhand": { name: "Bent Over Row Overhand Grip", muscle: "Back", equipment: "Barbell", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Overhand grip, hinge until back is nearly parallel. Pull bar to your lower chest, elbows flare out. Squeeze hard at the top." },
  "bent-over-underarm-barbell-row": { name: "Bent Over Row Underhand Grip", muscle: "Back", equipment: "Barbell", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Underhand grip shifts emphasis to lower lats and biceps. Same hip hinge position. Pull to your navel, elbows stay tight to your sides." },
  "plank-shoulder-tap": { injuryFlags: ["wrist-load"], name: "Plank Shoulder Taps", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", isTime: true, coachingCue: "High plank. Alternate tapping each shoulder with the opposite hand. The key is keeping your hips from rocking. Anti-rotation core strength." },
            "seated-lateral-raise": { injuryFlags: [], name: "Seated Lateral Raises", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Seated on bench, slight lean forward. Raise dumbbells to the sides. Sitting prevents leg drive so the deltoid does all the work." },
  "lat-pulldown-cable": { name: "Lat Pulldown (Cable)", muscle: "Back", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Grip just outside shoulder width, palms facing away. Sit tall, slight lean back, chest up. Pull the bar to your upper chest, leading with your elbows. Squeeze your lats at the bottom of the pull. Control the bar back up, do not let it yank you. Every rep starts with your shoulders packed down." },
    "dumbbell-lat-pullover": { injuryFlags: ["shoulder-overhead"], name: "Dumbbell Pullover", muscle: "Back", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Lie across bench with one dumbbell. Hold with both hands above chest. Lower behind head keeping slight bend in elbows. Pull back using lats, not just your arms."},
  "seated-dumbbell-arm-circles": { name: "Seated Dumbbell Arm Circles", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", vimeoId: "1183584890", coachingCue: "Sit tall, arms extended to sides with light dumbbells. Make small controlled circles forward or backward. Keep shoulders down and away from ears. Reps count for each way." },
  "seated-lateral-dumbbell-arm-circles": { name: "Seated Lateral Dumbbell Arm Circles", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate", vimeoId: "1183584890", coachingCue: "Small circles with arms extended to the sides. Creates constant deltoid tension. Go slow. The burn adds up fast." },
  "swiss-ball-leg-lift": { name: "Swiss Ball Leg Lift", muscle: "Core", equipment: "Swiss Ball", difficulty: "intermediate" , injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Lie flat on your back on the mat. Grip the Swiss ball between your feet and ankles, legs extended.|Keep your lower back pressed into the mat the entire time.|Raise both legs up toward the ceiling, squeezing the ball.|Lower with control, stopping just before your feet touch the floor.|The ball adds weight and forces both legs to work together.|This is NOT lying on the ball - you are lying on the mat with the ball between your legs."},
  "barbell-straight-leg-deadlift": { name: "Barbell Straight Legged Deadlifts", muscle: "Hamstrings", equipment: "Barbell", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Barbell, legs mostly straight. Hinge to feel maximum hamstring stretch, back stays flat. This is more of a hamstring stretch under load than a deadlift." },
      "standing-dumbbell-calf-raise": { injuryFlags: ["ankle-impact"], name: "Standing Dumbbell Calf Raises", muscle: "Calves", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Stand with dumbbells. Rise onto balls of feet to full extension. Hold at the top. Lower to stretch. Do not bounce at the bottom." },
  "jump-rope": { name: "Jump Rope", muscle: "Cardio", equipment: "Jump Rope", difficulty: "beginner", isTime: true , injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Keep elbows close to your sides, wrists doing the rotation.|Stay on the balls of your feet throughout.|Land softly with each jump.|Maintain a steady, controlled rhythm.|Keep core engaged and posture upright." },
    "concentration-curl": { name: "Concentration Curls", muscle: "Biceps", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, injuryFlags: ["elbow-load"], coachingCue: "Seated, elbow braced against inner thigh. Curl straight up. Full extension at bottom. This is strict isolation with no momentum possible." },
  "trx-jump-squat-with-pulse": { name: "TRX Jump Squat with Pulse", muscle: "Quads", equipment: "TRX", difficulty: "intermediate", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Hold TRX handles facing anchor, feet shoulder-width.|Squat down with control, then explode up into a jump.|Land softly with bent knees back into a squat.|Add a small pulse at the bottom before the next jump.|Use the straps for balance only - power comes from your legs.|Stay light on landing. Absorb through the full foot." },
    "forward-plank-diagonal-arm-lift": { injuryFlags: ["wrist-load"],name: "Forward Plank with Diagonal Arm Lift", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", coachingCue: "Start in a high plank with hands under shoulders.|Lift one arm diagonally forward and across - opposite to the raised leg if combining movements.|Hold briefly at the top, keeping hips level.|Don't let the pelvis rotate or drop.|Lower with control and alternate sides.|The goal is stability - slow and deliberate beats fast." },
    "dumbbell-runners-lunge": { injuryFlags: ["ankle-impact","hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], name: "Dumbbell Runner's Lunge", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Hold dumbbells at your sides or one overhead.|Step back into a reverse lunge, lowering the back knee toward the floor.|Drive through the front heel to stand, simultaneously driving the back knee up to hip height.|Keep your torso upright throughout the movement.|The knee drive at the top is explosive - use momentum to build power.|Alternate legs or complete all reps on one side."},
  "bosu-dumbbell-lunge-pushoff": { name: "Bosu Ball Dumbbell Lunge Push-Off", muscle: "Quads", equipment: "Bosu Ball", difficulty: "intermediate", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Stand with one foot on the center of the Bosu dome, dumbbells at sides.|Lower into a lunge, bending both knees to 90 degrees.|Drive explosively through the Bosu foot to push off and stand.|Control the landing back onto the Bosu.|The unstable surface increases glute and stabilizer demand.|Keep your core braced and torso upright throughout." },
    "bosu-bodyweight-lunge-pushoff": { name: "Bosu Ball Bodyweight Lunge Push-Off", muscle: "Quads", equipment: "Bosu Ball", difficulty: "beginner", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Stand with one foot on the center of the Bosu dome, bodyweight only.|Lower into a lunge with control, bending both knees.|Drive through the Bosu foot to stand back up.|Keep your balance by engaging your core and fixing your gaze forward.|The dome surface challenges stability more than a flat floor.|Build confidence here before adding dumbbells." },
  "bosu-dumbbell-lunge-lateral-raise": { injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear","shoulder-impingement"], name: "Bosu Ball Dumbbell Lunge to Lateral Raise", muscle: "Shoulders", equipment: "Bosu Ball", difficulty: "intermediate", coachingCue: "Stand with one foot on the Bosu dome, dumbbell in each hand.|Lower into a lunge position.|As you drive back up, perform a lateral raise, lifting arms to shoulder height.|Lower the dumbbells lower back into the lunge.|The combined movement challenges balance, shoulder strength, and leg stability simultaneously.|Keep a slight bend in the elbows during the raise." },
  "rope-goblet-cable-squat": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], name: "Rope Goblet Cable Squat", muscle: "Quads", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a rope to the low cable pulley. Face the machine holding the rope ends at chest height.|Stand back so there is tension on the cable, feet shoulder-width apart.|Squat down keeping the rope at chest - the cable counterbalances, allowing a more upright torso.|Drive through the heels to stand.|The cable pull helps beginners maintain chest up position.|Go full depth while keeping your knees tracking over your toes." },
  "crossover-step-up": { injuryFlags: ["shoulder-impingement"], name: "Crossover Step Up", muscle: "Glutes", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Stand beside a bench or box with one foot on the platform.|Cross the free leg slightly behind into a curtsy position before the drive.|Press through the heel of the elevated foot to drive yourself up.|Keep your hips square and torso tall - resist rotating.|Lower back into the curtsy position with control.|All reps on one side before switching. The cross pattern loads the glutes and hip stabilizers uniquely." },
    "agility-ladder-in-out": { injuryFlags: ["ankle-impact"], name: "Agility Ladder Drill - In-Out", muscle: "Cardio", equipment: "Agility Ladder", difficulty: "intermediate", coachingCue: "Stand at the end of the ladder in an athletic stance.|Step both feet into the first square, then step both feet out to the sides.|Step both feet into the next square and repeat down the ladder.|Stay on the balls of your feet throughout.|Drive your arms to increase speed and rhythm.|Focus on foot placement accuracy before increasing speed." },
  "agility-ladder-slalom": { injuryFlags: ["ankle-impact"], name: "Agility Ladder Drill - Slalom", muscle: "Cardio", equipment: "Agility Ladder", difficulty: "intermediate", coachingCue: "Stand beside the ladder in an athletic stance.|Jump with both feet diagonally into the first square, then out to the other side.|Continue down the ladder in a slalom (zig-zag) pattern, alternating sides.|Stay low and explosive - minimal ground contact time.|Keep your core tight and arms driving for rhythm.|Accuracy before speed - perfect the pattern first." },
  "agility-ladder-two-foot-run": { injuryFlags: ["ankle-impact","hip-flexion-loaded"], name: "Agility Ladder Drill - Two Foot Run", muscle: "Cardio", equipment: "Agility Ladder", difficulty: "beginner", coachingCue: "Stand at the end of the ladder.|Step both feet into each square sequentially, moving forward.|Keep a quick, light cadence - both feet touch every box.|Stay on the balls of your feet and keep knees slightly bent.|Drive your arms to maintain rhythm and speed.|This is the foundational agility ladder drill - master it before advancing to single-foot patterns." },
  "bodyweight-lunge-pushoff": { name: "Bodyweight Lunge Push-Off", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Step back into a reverse lunge, lowering the back knee toward the floor.|Drive explosively through the front heel to stand, driving the back knee up.|This is a plyometric movement - the drive knee comes up fast.|Land softly and step back into the next rep.|Keep your torso upright and core braced throughout.|A great power developer with no equipment needed." },
  "incline-dumbbell-pronated-back-fly": { name: "Incline Dumbbell Pronated Back Fly", muscle: "Back", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Set bench to 30-45 degrees. Lie face down with a dumbbell in each hand, palms facing down.|With a slight bend in the elbows, lift the dumbbells out and back in a wide arc.|Squeeze the rear delts and upper back at the top.|Lower with control - don't let the weights pull your shoulders forward.|Pronated grip shifts emphasis to the posterior deltoids and rhomboids.|Keep your neck neutral - don't crane upward." },
  "stability-ball-dumbbell-supinated-reverse-fly": { name: "Stability Ball Dumbbell Supinated Reverse Fly", muscle: "Shoulders", equipment: "Swiss Ball", difficulty: "intermediate", coachingCue: "Lie face down over a stability ball, chest supported, feet wide for balance.|Hold dumbbells with palms facing up (supinated grip).|Lift arms out to the sides in a wide arc, squeezing the rear delts at the top.|Lower with control.|Supinated grip increases rear deltoid activation compared to pronated.|Keep your head neutral and core engaged throughout." },
  "stability-ball-dumbbell-pronated-reverse-fly": { name: "Stability Ball Dumbbell Pronated Reverse Fly", muscle: "Shoulders", equipment: "Swiss Ball", difficulty: "intermediate", coachingCue: "Lie face down over a stability ball with feet wide for balance.|Hold dumbbells with palms facing down (pronated grip).|Lift arms out to the sides, leading with the elbows.|Squeeze the rear delts and upper back at the top.|Lower with control - no swinging.|The ball adds instability that increases core and stabilizer demand throughout." },
  "mini-bar-cable-bicep-curl": { injuryFlags: ["elbow-load"], name: "Mini Bar Cable Bicep Curl", muscle: "Biceps", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a short bar to the low cable pulley.|Stand with feet shoulder-width, grip the bar with an underhand grip.|Curl the bar toward your chest, keeping elbows pinned to your sides.|Squeeze hard at the top.|Lower slowly - the cable maintains tension through the full range, unlike a dumbbell.|Don't rock backward to initiate the curl."},
  "mini-bar-cable-upright-row": { injuryFlags: ["shoulder-impingement"], name: "Mini Bar Cable Upright Row", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a short bar to the low cable pulley.|Stand close, grip the bar with an overhand grip, hands close together.|Pull the bar straight up toward your chin, leading with the elbows.|Elbows should rise above the bar at the top.|Lower with control - don't let the cable snap you down.|Keep the bar close to your body throughout the movement."},
  "mini-bar-tricep-pressdown": { injuryFlags: ["elbow-load"], name: "Mini Bar Tricep Pressdown", muscle: "Triceps", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a short bar to the high cable pulley.|Stand with feet hip-width, grip the bar with an overhand grip, elbows bent at sides.|Press the bar straight down until arms are fully extended.|Squeeze the triceps hard at the bottom.|Return slowly - resist the weight on the way up.|Keep upper arms pinned to your sides throughout. Only the forearms move."},
  "humble-row": { name: "Dumbbell Humble Row", muscle: "Back", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Hinge at the hips with a flat back, dumbbells hanging in front.|Row both dumbbells simultaneously, driving elbows straight back and slightly flared wide.|At the top, elbows should be above the line of the back.|Squeeze the upper back and rear delts at the peak.|Lower with control.|This wide-elbow row targets the mid and upper back differently from a traditional row." },
  "cable-90-degree-external-rotation": { injuryFlags: ["lumbar-rotation-loaded"], name: "90 Degree Cable External Rotation", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Set cable to elbow height. Stand side-on to the machine.|Hold the handle with the far hand, upper arm at 90 degrees abduction, elbow bent 90 degrees.|Rotate your forearm upward and back, keeping the upper arm still.|Return slowly to starting position.|This isolates the external rotators - rotator cuff health work.|Light weight only. Control every inch of the movement." },
    "bent-over-dumbbell-supinated-back-fly": { name: "Bent Over Dumbbell Supinated Back Fly", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Hinge forward at the hips, flat back, dumbbells hanging below the chest with palms facing up.|Lift both arms out to the sides in a wide arc, squeezing the rear delts at the top.|Lower with control.|Supinated grip rotates the shoulder into a stronger rear delt position than pronated.|Don't rock or use momentum - this is a small muscle group that needs strict form.|Light to moderate weight only." },
  "bent-over-ez-bar-pronated-row": { name: "Bent Over EZ Bar Pronated Row", muscle: "Back", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Grip the EZ bar with an overhand (pronated) grip on the outer curves.|Hinge to 45 degrees or more, flat back, bar hanging at arms' length.|Drive elbows back and up to row the bar to your lower chest or upper abdomen.|Squeeze the lats and mid-back at the top.|Lower with control and full extension.|Pronated grip shifts more emphasis to the upper back and rear delts." },
  "bent-over-ez-bar-supinated-row": { name: "Bent Over EZ Bar Supinated Row", muscle: "Back", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Grip the EZ bar with an underhand (supinated) grip on the inner curves.|Hinge forward to 45 degrees or more, flat back.|Drive elbows back close to the body, rowing to the lower abdomen.|Supinated grip increases bicep contribution and shifts emphasis toward the lower lats.|Squeeze hard at the top.|Lower slowly - full range of motion on every rep." },
  "cable-rope-hammer-curl": { injuryFlags: ["elbow-load"],name: "Cable Rope Hammer Curl", muscle: "Biceps", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a rope to the low cable pulley.|Stand with feet shoulder-width, grip the rope with a neutral (hammer) grip.|Curl the rope toward your shoulders, keeping elbows pinned to your sides.|At the top, separate the rope ends slightly for a stronger squeeze.|Lower slowly - cable keeps tension through the full range.|Hammer grip targets the brachialis and brachioradialis for fuller arm development." },
  "decline-alternating-dumbbell-chest-press": { name: "Decline Alternating Dumbbell Chest Press", muscle: "Chest", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Set bench to a decline position, feet secured.|Hold a dumbbell in each hand at chest level.|Press one arm to full extension while the other stays at chest.|Alternate each rep, controlling the non-working arm.|Decline angle shifts the focus to the lower chest.|Keep both dumbbells stable - don't let the resting arm drift backward." },
  "incline-barbell-press": { injuryFlags: ["shoulder-impingement"], name: "Incline Barbell Press", muscle: "Chest", equipment: "Barbell", difficulty: "intermediate", coachingCue: "Set the bench to 30-45 degrees. Lie back with eyes under the bar.|Grip slightly wider than shoulder-width, unrack and lower the bar to the upper chest.|Press back up to full extension.|A 30-45 degree incline targets the upper chest. More than 45 shifts too much to the shoulders.|Keep your feet flat, lower back slightly arched, and shoulder blades retracted throughout.|Control the descent - don't bounce the bar off the chest." },
  "kneeling-rope-straight-arm-pulldown": { name: "Kneeling Rope Straight Arm Pulldown", muscle: "Back", equipment: "Cable Machine", difficulty: "intermediate", coachingCue: "Attach a rope to the high cable. Kneel facing the machine, arms extended overhead gripping the rope.|With straight arms, pull the rope down and toward your hips in a wide arc.|Squeeze the lats hard at the bottom.|Return slowly with fully extended arms.|Kneeling removes leg drive and forces the lats to work in isolation.|Keep a slight forward lean and brace your core throughout." },
  "lying-one-arm-dumbbell-tricep-extension": { injuryFlags: ["elbow-load"], name: "Lying One Arm Dumbbell Tricep Extension", muscle: "Triceps", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Lie flat on a bench or floor with one dumbbell in one hand, arm extended straight up.|Keeping the upper arm vertical and stationary, bend the elbow to lower the dumbbell toward the same-side ear.|Extend back to the top and squeeze the tricep.|The upper arm must stay pointing straight up - only the elbow moves.|Use the other hand to lightly support the working elbow if needed.|Complete all reps on one side before switching." },
  "mid-cable-chest-fly": { injuryFlags: ["shoulder-impingement"], name: "Mid Cable Chest Fly", muscle: "Chest", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Set both pulleys to chest height. Stand in the center holding both handles.|Step forward slightly, slight bend in the elbows.|Bring both hands together in front of you in a wide arc, squeezing the chest at the center.|Control the return - don't let the cables pull your arms back too far.|Mid-height pulleys target the middle chest fibers.|Think of hugging a tree - the arc should be wide and smooth."},
  "mini-bar-reverse-cable-bicep-curl": { injuryFlags: ["elbow-load"], name: "Mini Bar Reverse Cable Bicep Curl", muscle: "Biceps", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a short bar to the low cable pulley.|Grip the bar with an overhand (pronated) grip.|Curl the bar toward your chest keeping elbows pinned to your sides.|Lower slowly with control.|Reverse grip targets the brachioradialis and the often-neglected forearm extensors.|This is lighter than a standard curl - don't ego lift here." },
  "dumbbell-alternating-floor-press": { name: "Dumbbell Alternating Floor Press", muscle: "Chest", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Lie on the floor with a dumbbell in each hand, elbows resting on the ground at 45 degrees.|Press one arm to full extension while the other rests on the floor.|Lower it back and press the opposite side.|The floor limits range of motion, reducing shoulder stress.|Great for building pressing strength safely.|Keep your core engaged and lower back flat on the floor throughout." },
  "neutral-grip-assisted-pullup": { injuryFlags: ["wrist-load"], name: "Neutral Grip Assisted Pull Up", muscle: "Back", equipment: "Assisted Pull Up Machine", difficulty: "beginner", coachingCue: "Set the counterweight assistance to an appropriate level.|Grip the neutral (parallel) handles with palms facing each other.|Pull yourself up until your chin clears the bar, squeezing the lats.|Lower with control - a full hang at the bottom.|Neutral grip is easier on the wrists and elbows than other grip variations.|Use the minimum counterweight assistance needed to complete full reps with good form." },
  "neutral-grip-machine-shoulder-press": { injuryFlags: ["shoulder-overhead"], name: "Neutral Grip Machine Shoulder Press", muscle: "Shoulders", equipment: "Shoulder Press Machine", difficulty: "beginner", coachingCue: "Sit upright with back flat against the pad, feet flat on the floor.|Grip the handles with palms facing each other (neutral grip).|Press straight up to near full extension - don't lock out hard.|Lower back to ear height with control.|Neutral grip reduces shoulder impingement risk compared to a barbell press.|Adjust the seat so the handles start at shoulder height." },
  "one-arm-cable-diagonal-raise": { name: "One Arm Cable Diagonal Raise", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a handle to the low cable. Stand side-on to the machine.|With a slight bend in the elbow, raise the cable diagonally across your body to shoulder height.|The path is low-to-high and across - not straight up.|Lower with control.|This diagonal pattern targets the anterior and medial deltoid simultaneously.|Keep your core tight and avoid leaning away from the machine." },
  "one-arm-cable-front-raise": { injuryFlags: ["shoulder-impingement"], name: "One Arm Cable Front Raise", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a handle to the low cable. Stand facing away from the machine.|With a slight bend in the elbow, raise the cable directly in front of you to shoulder height.|Lower with control - the cable maintains tension at the bottom unlike a dumbbell.|Complete all reps on one side then switch.|Keep your torso upright - no leaning back to help the movement.|Isolates the anterior deltoid with constant resistance throughout." },
  "one-arm-dumbbell-overhead-tricep-extension": { injuryFlags: ["elbow-load","shoulder-overhead"], name: "One Arm Dumbbell Overhead Tricep Extension", muscle: "Triceps", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Stand or sit holding one dumbbell with one hand, arm extended overhead.|Keeping the upper arm close to your ear and stationary, lower the dumbbell behind your head by bending the elbow.|Extend back to the top, squeezing the tricep hard.|Don't let the elbow flare out to the side - keep it pointing up.|Complete all reps on one side before switching.|Use the other hand to lightly hold the working elbow steady if needed."},
  "one-arm-tricep-pressdown": { injuryFlags: ["elbow-load"], name: "One Arm Tricep Pressdown", muscle: "Triceps", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a single handle to the high cable. Stand facing the machine.|Grip the handle with one hand, elbow bent and pinned to your side.|Press the handle straight down until the arm is fully extended.|Squeeze the tricep hard at the bottom.|Return slowly - resist the cable pulling your arm back up.|Single arm work allows you to correct imbalances between sides. Complete all reps before switching." },
  "pendlay-row": { name: "Pendlay Row", muscle: "Back", equipment: "Barbell", difficulty: "advanced", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Load a barbell on the floor. Stand over it with feet hip-width, bar over mid-foot.|Hinge to a horizontal torso position - more parallel to the floor than a standard row.|Explosively pull the bar to your lower chest, leading with the elbows.|Lower the bar completely back to the floor each rep - this is a dead stop row.|Each rep starts from a dead stop, which eliminates momentum.|Keep a flat back. The explosive pull develops raw back power." },
  "seated-alternating-dumbbell-arnold-press": { injuryFlags: ["shoulder-impingement","shoulder-overhead"], name: "Seated Alternating Dumbbell Arnold Press", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Sit with back supported, dumbbells at shoulder height with palms facing you.|Press one arm overhead, rotating the wrist so the palm faces away at the top.|Lower back to the start with the rotation reversing.|Alternate sides each rep.|The rotation recruits all three deltoid heads throughout the range of motion.|Keep your core braced and avoid arching the lower back." },
    "seated-cable-one-arm-row": { name: "Seated Cable One Arm Row", muscle: "Back", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Sit at the cable row station, one hand gripping a single handle attachment.|Sit tall with a slight forward lean at the hip - not a rounded back.|Drive the elbow straight back, pulling the handle to your hip.|Squeeze the lat at the end of the pull.|Rotate the torso slightly into the movement for full range - don't over-rotate.|Lower with control and full extension before each rep." },
  "seated-dumbbell-alternating-hammer-shoulder-press": { injuryFlags: ["elbow-load","shoulder-overhead"], name: "Seated Dumbbell Alternating Hammer Shoulder Press", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Sit with back supported, dumbbells at shoulder height with palms facing each other (neutral/hammer grip).|Press one arm overhead while the other stays at shoulder height.|Lower and press the opposite arm.|Hammer grip reduces internal shoulder rotation, making this easier on the rotator cuff.|Alternate each rep in a controlled rhythm.|Keep your core braced and don't arch your lower back on the press." },
  "seated-dumbbell-front-raise": { injuryFlags: ["shoulder-impingement"], name: "Seated Dumbbell Front Raise", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Sit upright on a bench with dumbbells in both hands resting on your thighs.|Raise both arms simultaneously straight in front of you to shoulder height.|Lower with control - don't let them drop.|Keep a slight bend in the elbows and palms facing down throughout.|The seated position isolates the anterior deltoid by removing momentum.|Stop at shoulder height - going higher reduces delt tension."},
  "seated-rope-cable-face-pull": { injuryFlags: ["shoulder-impingement"], name: "Seated Rope Cable Face Pull", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Sit on a bench facing the cable with a rope attached at face height.|Grip the rope ends with thumbs pointing in, pull toward your face splitting the rope apart.|At full pull, hands should be beside your ears, elbows high and flared.|Squeeze the rear delts and external rotators hard at the peak.|Lower with control.|This is a rotator cuff health and rear delt exercise - light to moderate weight only."},
  "seated-zottman-curl": { injuryFlags: ["elbow-load"], name: "Seated Zottman Curl", muscle: "Biceps", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Sit upright with a dumbbell in each hand, palms facing up.|Curl both dumbbells up in a standard supinated curl.|At the top, rotate both wrists so palms face down (pronated).|Lower the dumbbells slowly in this pronated position - this is the key.|At the bottom, rotate back to supinated and repeat.|The supinated curl builds the bicep. The pronated lowering builds the brachioradialis and forearms. One movement, two benefits." },
  "single-arm-cable-tricep-kickback": { injuryFlags: ["elbow-load"], name: "Single Arm Cable Tricep Kickback", muscle: "Triceps", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a handle to the low cable. Hinge forward at the hips, back flat.|Hold the handle with one hand, upper arm parallel to the floor and pinned.|Extend the forearm back until the arm is fully straight, squeezing the tricep.|Lower with control - the cable maintains tension at the start position unlike a dumbbell kickback.|Keep the upper arm completely still. Only the forearm moves.|Complete all reps on one side before switching." },
    "standing-french-press": { injuryFlags: ["elbow-load"], name: "Standing French Press", muscle: "Triceps", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Stand with feet shoulder-width. Hold one dumbbell overhead with both hands gripping the top end.|Keeping upper arms close to your head and stationary, lower the dumbbell behind your head by bending both elbows.|Extend back to the top, squeezing the triceps hard.|Don't let your elbows flare wide - keep them pointed up throughout.|The standing position adds core demand vs seated.|Full range of motion - go mobility allows."},
  "underhand-grip-tricep-pressdown": { injuryFlags: ["elbow-load"],name: "Supinated Cable Tricep Pressdown", muscle: "Triceps", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach a bar or rope to the high cable. Grip with palms facing up (supinated/underhand grip).|Pin elbows to your sides and press the handle straight down to full extension.|Squeeze the triceps hard at the bottom.|Return slowly - resist the cable pulling upward.|Supinated grip shifts the emphasis to the long head of the triceps.|Lighter load than overhand - control is more important than weight here." },
  "trx-bicep-curl": { injuryFlags: ["elbow-load"], name: "TRX Bicep Curl", muscle: "Biceps", equipment: "TRX", difficulty: "beginner", coachingCue: "Face the anchor point, hold TRX handles with an underhand grip, arms extended.|Lean back to create resistance - the more you lean, the harder it gets.|Curl your hands toward your temples, keeping elbows high and in line with your shoulders.|Lower with control, returning to the starting lean.|Keep your body in a straight line from head to heels - no bending at the hips.|Bodyweight bicep training with constant tension through the full range." },
  "trx-overhead-tricep-extension": { injuryFlags: ["elbow-load","shoulder-overhead"], name: "TRX Overhead Tricep Extension", muscle: "Triceps", equipment: "TRX", difficulty: "intermediate", coachingCue: "Face away from the anchor point, holding handles overhead with palms facing down.|Lean forward, arms extended overhead - the further you lean, the harder it gets.|Bend at the elbows to lower your head toward your hands.|Press back to full extension, squeezing the triceps.|Keep your upper arms fixed beside your head throughout - only the elbows bend.|Maintain a rigid body position. Don't let your hips sag." },
  "resistance-band-wide-grip-bicep-curl": { injuryFlags: ["elbow-load"],name: "Resistance Band Wide Grip Bicep Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the center of the band, gripping both ends wider than shoulder-width, palms up.|Curl both hands toward your shoulders, keeping elbows pinned to your sides.|Squeeze hard at the top.|Lower slowly - resist the band pulling your arms down.|Wide grip increases activation of the short (inner) head of the bicep.|Keep your torso upright - no swinging." },
  "lunge-to-bicep-curl-band": { injuryFlags: ["elbow-load","hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], name: "Resistance Band Lunge to Curl", muscle: "Full Body", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the center of the band, one end in each hand, palms facing up.|Step forward into a lunge, lowering the back knee toward the floor.|As you lower, curl both hands toward your shoulders simultaneously.|Drive through the front heel to stand, lowering the arms rise.|The curl happens during the lunge descent - the two movements work together.|Alternate legs each rep or complete all on one side." },
  "resistance-band-side-to-side-lunge": { injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], name: "Resistance Band Side to Side Lunge", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, coachingCue: "Stand in the band slightly wider than shoulder-width, band resting across your forearms to create tension.|Lateral lunge to one side, pushing the hips back and bending the stepping knee.|Keep the opposite leg straight and chest tall.|Push off to return to center and immediately lunge to the other side.|The band on your forearms creates constant horizontal resistance throughout the movement.|Don't let the bent knee cave inward - keep it tracking over the toes." },
  "resistance-band-squatting-curl": { injuryFlags: ["elbow-load","knee-deep-flexion","knee-impact","knee-shear"], name: "Resistance Band Squatting Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band low. Sit back into a squat position with both elbows resting on your knees.|Grip the band with both hands, palms facing up.|Curl both hands toward your face, squeezing the biceps at the top.|Lower with control - the band pulls your arms back down.|This imitates a preacher curl, locking the upper arms in place for strict bicep isolation.|Keep your elbows firmly on your knees throughout - they are your anchor." },
  "resistance-band-scarecrow": { name: "Resistance Band Scarecrow", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor band at chest height. Stand facing the anchor holding handles with elbows bent 90 degrees, upper arms parallel to the floor.|Rotate forearms upward and back - like a scarecrow position - keeping upper arms still.|Return slowly to starting position.|This isolates the external rotators and rear deltoids.|Light resistance only - this is a rotator cuff and postural health exercise.|Keep your upper arms completely still throughout. Only the forearms rotate." },
  "resistance-band-drag-curl": { injuryFlags: ["elbow-load"],name: "Resistance Band Drag Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the center of the band, gripping both ends with an underhand grip.|Instead of curling forward, drag the band straight up your body, pulling your elbows back behind your torso.|The hands travel up along your abdomen - not in an arc in front.|This unique path emphasizes the long head of the bicep.|Lower by reversing the drag.|Keep your elbows driving back throughout - that's the key cue." },
  "seated-band-tricep-kickback": { injuryFlags: ["elbow-load"], name: "Seated Band Tricep Kickback", muscle: "Triceps", equipment: "Resistance Band", difficulty: "beginner", eachSide: true, coachingCue: "Sit on a bench or chair with the band anchored behind you at low height.|Hinge forward slightly at the hips, upper arm pinned parallel to the floor.|Extend the forearm back until the arm is fully straight, squeezing the tricep.|Lower with control - resist the band pulling your arm forward.|Keep the upper arm completely still throughout. Only the forearm moves.|Complete all reps on one side before switching." },
  "seated-dumbbell-bicep-curl": { injuryFlags: ["elbow-load"], name: "Seated Dumbbell Bicep Curl", muscle: "Biceps", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Sit upright on a bench with a dumbbell in each hand, palms facing up.|Curl both dumbbells toward your shoulders, keeping elbows pinned to your sides.|Squeeze hard at the top.|Lower slowly - full extension at the bottom.|The seated position eliminates momentum and body swing, forcing strict form.|Keep your back flat against the bench throughout." },
  "wall-pushup": { injuryFlags: ["wrist-load"], name: "Wall Pushup", muscle: "Chest", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Stand facing a wall, arms extended, palms flat on the wall at shoulder height.|Bend your elbows to lower your chest toward the wall, keeping your body in a straight line.|Push back to the start.|The further your feet are from the wall, the harder it gets.|A great starting point for those building toward a floor pushup.|Keep your core tight and avoid letting your hips sag or pike." },
      "squat-jumps": { name: "Jump Squat", muscle: "Quads", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Start with feet shoulder-width apart.|Perform a squat, then explode into a jump.|Land softly and return to the squat position.|Maintain good squat form.|Explode into the jump using lower body power.|Land with control to protect joints." },
      "standing-dumbbell-arm-circles": { name: "Standing Dumbbell Arm Circles", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", vimeoId: "1183583375", coachingCue: "Arms extended, forward or backward circles. Small controlled movements. Deltoid endurance work. Great finisher or warm-up." },
  "t-pushup": { name: "T Pushups", muscle: "Chest", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["wrist-load"], coachingCue: "Start in a pushup position.|Lower your chest to the floor.|As you press back up, rotate your body to one side into a side plank, one arm reaching overhead.|Return to plank and repeat to the other side.|This adds thoracic rotation and oblique engagement to a standard pushup.|Keep your core locked and hips level throughout the rotation." },
    "behind-back-one-arm-cable-curl": { injuryFlags: ["elbow-load"], name: "Behind the Back One Arm Cable Curls", muscle: "Biceps", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true, coachingCue: "Set the cable low, stand with your back to the cable stack.|Hold the handle behind your back, palm facing up.|Curl the handle forward and up toward your shoulder.|Squeeze the bicep hard at the top  - hold for a beat.|Lower with control against the cable.|This angle puts peak tension at the very top of the curl where standard curls lose tension." },
  "reverse-barbell-curl": { name: "Reverse Barbell Curl", muscle: "Biceps", equipment: "Barbell", difficulty: "intermediate", injuryFlags: ["wrist-load", "elbow-load"], coachingCue: "Overhand grip on bar. Curl up, forearms do more work. Hits the brachioradialis and forearms heavily. Harder than it looks." },
    "pallof-press": { injuryFlags: ["lumbar-rotation-loaded"],name: "Pallof Press", muscle: "Core", equipment: "Cable Machine", difficulty: "intermediate", coachingCue: "Set the cable at chest height, stand sideways to the stack.|Hold the handle with both hands at your chest.|Press the cable straight out in front of you  - arms fully extended.|Hold for a beat, then return to your chest.|The cable tries to rotate you toward the stack. Resist it completely.|Your core, obliques, and hips are all working to stay square. That's the exercise." },
  "planking-window-washers": { name: "Planking Window-Washers", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", eachSide: true , injuryFlags: ["wrist-load"], coachingCue: "Start in a forearm plank  - elbows under shoulders, body in a straight line.|Keeping your upper body still, rotate your hips side to side in a slow arc  - like a windshield wiper.|Your feet pivot on the floor hips swing.|Keep your shoulder blades down and your elbows planted  - the rotation is all in the hips.|Don't let your hips drop to the floor on either side.|This is oblique work in a plank position. Control the swing."},
  "plyo-side-side-pushup": { name: "Plyo Side-Side Push-Ups", muscle: "Chest", equipment: "Bodyweight", difficulty: "advanced", eachSide: true, injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear","wrist-load"], coachingCue: "Explosive pushup where you launch sideways to land in a new position. Develops lateral chest power and coordination. Land softly with elbows slightly bent." },
  "t-bar-row": { name: "T Bar Row", muscle: "Back", equipment: "T-Bar Row Machine", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Load one end of a barbell in a corner or T-bar machine.|Straddle the bar, hinge forward, grip the handles.|Row the weight toward your chest, driving elbows back.|Squeeze the upper back at the top.|Lower with control.|Keep your back flat and chest up the entire movement."},
      "towel-grip-inverted-row": { name: "Towel Grip Inverted Row", muscle: "Back", equipment: "Barbell", difficulty: "advanced", coachingCue: "Drape a towel over a bar and grip both ends.|Hang beneath the bar, body in a straight line.|Pull your chest up to the towel ends, driving your elbows back.|Lower with control  - full arm extension at the bottom.|The towel grip engages your forearms and grip significantly more than gripping a bar.|Let your grip fatigue be your guide. When your grip goes, the set is done." },
  "agility-ladder-2-foot-step": { name: "Agility Ladder Drill — 2 Foot Step Forward", muscle: "Cardio", equipment: "Agility Ladder", difficulty: "intermediate", isTime: true , injuryFlags: ["ankle-impact"], coachingCue: "Place the ladder flat on the ground.|Run through the ladder stepping both feet into each box before moving forward.|Keep your weight on the balls of your feet.|Arms drive naturally move.|Focus on coordination and foot speed, not just how fast you go.|This builds foot speed and coordination."},
  "agility-ladder-side-step": { name: "Agility Ladder Drill — Side Step", muscle: "Cardio", equipment: "Agility Ladder", difficulty: "intermediate", isTime: true , injuryFlags: ["ankle-impact"], coachingCue: "Stand sideways to the ladder.|Step laterally through each box with both feet before moving to the next.|Keep a slight squat position throughout.|Stay on the balls of your feet.|Move with rhythm  - don't rush the foot placement.|Builds lateral quickness and hip mobility."},
  "clapping-pushup": { name: "Clapping Pushups", muscle: "Chest", equipment: "Bodyweight", difficulty: "advanced", injuryFlags: ["wrist-load"], coachingCue: "Explosive pushup leaving the ground at the top. Clap hands before landing. Keep core rigid. Develops fast-twitch chest power." },
  "barbell-overhead-press": { name: "Barbell Overhead Press", muscle: "Shoulders", equipment: "Barbell", difficulty: "intermediate", injuryFlags: ["shoulder-overhead", "neck-flexion"], coachingCue: "Bar at shoulder height on rack. Press overhead to full lockout. Bar travels in a straight line. Do not lean excessively back. Core braced throughout." },
  "supinated-inverted-row": { name: "Supinated Inverted Row", muscle: "Back", equipment: "Barbell", difficulty: "intermediate" , coachingCue: "Grip a bar at hip height with an underhand grip, palms facing you.|Hang beneath the bar, body in a straight line.|Pull your chest up to the bar, driving elbows back and close to your sides.|Lower with control  - full arm extension at the bottom.|Supinated grip increases bicep involvement.|Elevate your feet to increase difficulty."},
    "simultaneous-dumbbell-front-lateral-raise": { injuryFlags: ["shoulder-impingement"], name: "Simultaneous Dumbbell Front & Lateral Raise", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate" , coachingCue: "Hold dumbbells at your sides.|Raise both arms simultaneously  - one straight in front, one out to the side.|Both reach shoulder height at the same time.|Lower with control.|Alternate which arm goes front and which goes lateral each rep.|Keep your torso still. No rocking."},
      "assisted-chin-up": { name: "Supinated Chin-Ups", muscle: "Back", equipment: "Pull Up Bar", difficulty: "intermediate", coachingCue: "Underhand grip, shoulder-width or closer. Recruits more bicep and lower lat. Full hang at bottom, chin over bar at top. No momentum." },
  "pronated-inverted-row": { name: "Pronated Inverted Row", muscle: "Back", equipment: "Barbell", difficulty: "intermediate", coachingCue: "Overhand grip, body straight like a plank. Pull chest to bar, squeeze shoulder blades. The more horizontal your body, the harder it is." },
  "cuban-barbell-press": { name: "Cuban Barbell Press", muscle: "Shoulders", equipment: "Barbell", difficulty: "advanced", coachingCue: "Stand holding the bar in a wide overhand grip at hip height.|Pull the bar up in an upright row, elbows high.|At the top, rotate your forearms forward  - like a front rack position.|Press the bar overhead to full extension.|Reverse the motion to return.|This trains external rotation strength and shoulder health through a full range of motion." },
  "bench-tricep-dips": { name: "Bench Tricep Dips", muscle: "Triceps", equipment: "Bench", difficulty: "beginner", injuryFlags: ["elbow-load","wrist-load"], coachingCue: "Hands on bench behind you, feet forward. Lower body by bending elbows to 90 degrees. Push back up through your palms. Keep hips close to the bench." },
  "barbell-back-half-squat": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], name: "Barbell Back Half Squat", muscle: "Quads", equipment: "Barbell", difficulty: "advanced" , coachingCue: "Set the barbell across your upper back in a squat rack.|Stand with feet shoulder-width.|Lower only halfway  - thighs at 45 degrees, not parallel.|Drive back up through your heels.|This is a partial range movement  - the point is to overload the top half of the squat.|Control the descent. No bouncing at the bottom."},
    "trap-bar-deadlift": { name: "Trap Bar Deadlift", muscle: "Hamstrings", equipment: "Trap Bar", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Standing inside the trap bar. Neutral grip handles. Hip hinge with more upright torso than conventional deadlift. Great for learning deadlift mechanics." },
  "decline-medicine-ball-russian-twist": { name: "Decline Medicine Ball Russian Twist", muscle: "Core", equipment: "Medicine Ball", difficulty: "advanced", eachSide: true, injuryFlags: ["lumbar-rotation-loaded"] , coachingCue: "Anchor your feet at the top of the decline bench, sit up to about 45 degrees.|Hold the medicine ball with both hands, arms slightly bent.|Rotate side to side, touching the ball to the bench on each side.|The decline angle increases the ab engagement compared to flat ground.|Keep your chest up  - don't hunch over the ball.|The decline makes this significantly harder. Go lighter on the ball than you think."},
    "standing-split-rotational-chop": { name: "Standing Split Rotational Chop", muscle: "Core", equipment: "Cable Machine", difficulty: "advanced", eachSide: true , injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Set the cable low. Stand in a split stance  - one foot forward  - sideways to the machine.|Grip the handle with both hands and pull it up and across your body in a diagonal arc  - low to high.|Rotate through your torso and extend your arms at the top.|Return slowly  - don't let the cable yank you back.|Your hips initiate the rotation, your core transfers it, your arms finish it.|This is a full rotational power movement. Feel it from your hips through your obliques."},
  "lying-straight-leg-pulse-ups": { name: "Lying Straight Leg Pulse-Ups", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", coachingCue: "Lying on back, legs straight up. Small pulsing hip raise using lower abs. Core braced, lower back stays down." },
  "lying-swiss-ball-leg-raises": { name: "Lying Swiss Ball Leg Raises", muscle: "Core", equipment: "Swiss Ball", difficulty: "intermediate", injuryFlags: ["hip-flexion-loaded","lumbar-flexion-loaded"], coachingCue: "Lying flat on your back on a mat. Swiss ball is held between your feet. Raise both legs up to 90 degrees, then lower slowly. Keep lower back pressed into the mat. The ball adds load and requires coordinating both legs." },
  "low-to-high-cable-fly": { name: "Low to High Cable Flye", muscle: "Chest", equipment: "Cable Machine", difficulty: "intermediate", injuryFlags: ["shoulder-impingement"], coachingCue: "Cable set low, pull up and across your body in an arc. Targets upper pec fibers. Squeeze at the point where your hands meet." },
  "high-cable-chest-fly": { name: "High Cable Chest Flyes", muscle: "Chest", equipment: "Cable Machine", difficulty: "intermediate", injuryFlags: ["shoulder-impingement"], coachingCue: "Cable set high, pull down and inward in an arc. Targets the lower and inner pec. Squeeze hard when hands come together." },
  "trx-lunge-switches": { name: "TRX Lunge Switches", muscle: "Quads", equipment: "TRX", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Hold the TRX handles, lean back slightly for support.|Step back into a lunge.|Drive up explosively and switch legs mid-air.|Land softly in a lunge on the opposite side.|The TRX helps with balance  - don't lean on it.|Absorb each landing with soft knees."},
      "alternate-grip-barbell-deadlift": { name: "Alternate Grip Barbell Deadlift", muscle: "Hamstrings", equipment: "Barbell", difficulty: "advanced", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"] , coachingCue: "One hand overhand, one hand underhand  - alternate grip side each set.|Stand with feet hip-width, bar over midfoot.|Hinge at the hips and grip the bar.|Drive your feet through the floor and lock out at the top, squeezing your glutes.|Lower with control.|The alternate grip allows you to hold heavier loads without the bar rolling."},
  "standing-barbell-drag-curl": { injuryFlags: ["elbow-load"], name: "Standing Barbell Drag Curls", muscle: "Biceps", equipment: "Barbell", difficulty: "intermediate", coachingCue: "Hold the barbell at hip level, underhand grip.|Drag the bar straight up your body  - keeping it in contact with your torso.|Your elbows drive up and back bar moves.|Squeeze the biceps hard at the top.|Lower the bar back along your body.|This motion forces the elbows behind the bar, which isolates the biceps more than a standard curl." },
    "pull-up": { name: "Strict Pull Ups", muscle: "Back", equipment: "Pull Up Bar", difficulty: "advanced", coachingCue: "Dead hang from the bar, hands slightly wider than shoulder width, overhand grip.|Pull yourself up until your chin clears the bar  - no kipping, no swinging.|Lower back to a full dead hang  - arms completely straight.|Full range every rep.|This is a test of pure pulling strength.|If you can't do a full strict rep, use the assisted machine and build toward it progressively." },
  "kettlebell-squat": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], name: "Kettle Bell Squat", muscle: "Quads", equipment: "Kettlebell", difficulty: "intermediate", coachingCue: "KB held at chest or by the handle at waist. Standard squat mechanics. Drive through heels, chest up, knees track over toes." },
  "standing-zottman-curl": { name: "Standing Zottman Curls", muscle: "Biceps", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["elbow-load"], coachingCue: "Stand with dumbbells at your sides.|Curl with a supinated grip on the way up.|At the top, rotate to a pronated grip.|Lower with the overhand grip  - take 2 to 3 seconds down.|Rotate back to supinated at the bottom before the next rep.|Bicep curl up, brachioradialis work on the way down. One movement, double the benefit." },
      "medicine-ball-squat-jumps": { name: "Medicine Ball Weighted Jump Squat", muscle: "Quads", equipment: "Medicine Ball", difficulty: "advanced", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Medicine ball held at chest. Squat and jump. The ball shifts your center of gravity slightly forward which challenges your core." },
  "low-rope-rows": { name: "Low Rope Rows", muscle: "Back", equipment: "Cable Machine", difficulty: "intermediate", coachingCue: "Rope attachment, low pulley. Row to your midsection splitting the rope at the end. Hits the mid back and rear delts." },
    "close-grip-bench-press": { name: "Close Grip Bench Press", muscle: "Chest", equipment: "Barbell", difficulty: "intermediate", injuryFlags: ["elbow-load"], coachingCue: "Narrow grip on bar, elbows stay closer to body. Shifts load more to triceps and inner chest. Lower to chest and press straight up. Do not let elbows flare wide." },
  "barbell-bench-press": { injuryFlags: ["shoulder-impingement"], name: "Barbell Bench Press", muscle: "Chest", equipment: "Barbell", difficulty: "intermediate", coachingCue: "Grip just outside shoulder width. Bar touches lower chest at the bottom. Press up in a slight arc. Shoulder blades pinched, back slightly arched, feet flat." },
    "chest-dips": { name: "Chest Dips", muscle: "Chest", equipment: "Dip Bar", difficulty: "intermediate", injuryFlags: ["elbow-load","wrist-load"], coachingCue: "Lean forward throughout the entire movement. Lower until you feel the chest stretch. Press back up through your chest, not your triceps. Upright posture turns this into a tricep exercise." },
  "pec-deck-flye": { name: "Pec Deck Flye", muscle: "Chest", equipment: "Pec Deck Machine", difficulty: "intermediate", injuryFlags: ["shoulder-impingement"], coachingCue: "Elbows on pads, bring arms together in front of your chest. Squeeze hard at the midpoint. Slow controlled return. Let the pec get a full stretch before the next rep." },
      "weighted-diamond-pushup": { name: "Weighted Diamond Pushup", muscle: "Chest", equipment: "Weight Plate", difficulty: "intermediate", injuryFlags: ["wrist-load"] , coachingCue: "Place your hands together in a diamond shape under your chest.|Add a weight plate on your upper back for resistance.|Lower your chest toward your hands, elbows driving slightly back.|Press back up to full extension, squeezing the triceps.|Keep your core tight  - the added weight makes stability harder.|Don't let your hips sag under the load."},
  "diamond-pushup": { name: "Diamond Pushup", muscle: "Chest", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["wrist-load"], coachingCue: "Hands form a diamond shape under your chest. Narrow hand position loads the inner chest and triceps heavily. Lower slow, press strong." },
  "band-upper-chest-hex-press": { name: "Band Upper Chest Hex Press", muscle: "Chest", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Stand on the band with both feet, handles at your sides, palms facing each other.|Bring the handles together in front of your chest, this is the hex position.|Press upward and forward at a 45-degree angle, keeping the handles close together throughout.|Squeeze the upper chest hard at the top.|Lower with control, keeping tension on the band the whole way down.|The angle of the press is everything here. Too vertical and it becomes a shoulder press, too horizontal and you lose the upper chest." },
      "filly-press": { name: "Filly Press", muscle: "Shoulders", equipment: "Kettlebells", difficulty: "advanced", eachSide: true, coachingCue: "Hold a heavy kettlebell in a front-rack position on one side - resting on forearm and bicep.|With the other hand, perform a strict overhead Arnold press with a dumbbell.|Start the dumbbell with palm facing you, rotating to face away press overhead.|Squeeze your glutes and brace your core hard - resist twisting toward the kettlebell side.|Keep the rack arm locked and elbow up throughout.|Stack the pressing shoulder directly overhead at the top. Slow and controlled tempo." },
    "2-1-eccentric-cable-row": { name: "2/1 Eccentric Cable Rows", muscle: "Back", equipment: "Cable Machine", difficulty: "advanced", eachSide: true, injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Set up at a cable row station with both hands on the handle.|Pull with both arms to the fully contracted position.|Release one hand and lower with only one arm  - slow 3 to 4 second negative.|Pull back up with both hands and repeat.|The eccentric overload is the entire point  - that slow single-arm lowering builds significant strength.|Alternate the lowering arm each rep or every set." },
      "bosu-ball-dumbbell-deadlift-to-row": { name: "Bosu Ball Dumbbell Deadlift to Row", muscle: "Back", equipment: "Bosu Ball", difficulty: "advanced", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"] , coachingCue: "Stand on the flat side of the bosu ball, holding dumbbells.|Hinge at the hips into a deadlift position.|At the bottom, perform a dumbbell row.|Return to standing.|The bosu adds instability that forces your core and stabilizers to work harder.|Go lighter than you would on solid ground."},
    "smith-machine-shrug": { name: "Smith Machine Shrug", muscle: "Back", equipment: "Smith Machine", difficulty: "intermediate", injuryFlags: ["neck-flexion"], coachingCue: "Set the bar at hip height, grip just outside shoulder width.|Stand tall, shoulders relaxed.|Shrug straight up  - think about touching your shoulders to your ears.|Hold at the top for a beat.|Lower slowly.|No rolling the shoulders. Straight up and straight down."},
  "single-arm-underhand-dumbbell-row": { name: "Single-Arm Underhand-Grip Dumbbell Row", muscle: "Back", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Place one knee and hand on a bench for support.|Hold the dumbbell with a supinated grip, palm facing up.|Row toward your hip, driving the elbow straight back.|Squeeze the lat and bicep at full contraction.|Lower with control.|Underhand grip increases bicep involvement and allows a deeper squeeze."},
        "single-leg-deadlift-band": { name: "Single Leg Deadlift (Band)", muscle: "Hamstrings", equipment: "Resistance Band", difficulty: "intermediate", eachSide: true, injuryFlags: ["ankle-impact","lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Stand on the band with one foot, hold handles in front of you.|Hinge at the hip, extending your free leg straight behind you torso drops toward parallel.|Keep back flat and a slight bend in the standing knee.|Drive through your heel to return to standing.|Keep hips square throughout." },
  "ez-bar-spider-curl": { injuryFlags: ["elbow-load"], name: "EZ Bar Spider Curl", muscle: "Biceps", equipment: "EZ Bar", difficulty: "intermediate", coachingCue: "Set an incline bench to 45 degrees and lie face down with your chest on the pad, feet planted on the floor.|Grip the EZ bar with an underhand grip, hands shoulder-width apart.|Let your arms hang straight down, fully extended.|Keeping your upper arms completely stationary, curl the bar up toward your chin by contracting your biceps.|Squeeze hard at the top, then lower with control back to full extension.|No swinging, no shoulder involvement — all bicep."},
  "machine-shoulder-press": { name: "Machine Shoulder Press", muscle: "Shoulders", equipment: "Shoulder Press Machine", difficulty: "beginner", injuryFlags: ["shoulder-overhead"], coachingCue: "Adjust seat so handles are at shoulder height. Press straight up. Machine guides the path. Great for focusing on pure deltoid strength." },
    "cable-lateral-raise": { name: "Cable Lateral Raise", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true, injuryFlags: ["shoulder-impingement"], coachingCue: "Stand sideways to a low cable with the handle in your outside hand.|Keep a slight bend in your elbow throughout.|Raise your arm out to the side until it reaches shoulder height.|Hold briefly at the top.|Lower with control — don't let the cable pull you.|The cable keeps constant tension through the full range. Use it." },
  "standing-dumbbell-hammer-curl": { name: "Standing Dumbbell Hammer Curl", muscle: "Biceps", equipment: "Dumbbell", difficulty: "beginner", eachSide: false, injuryFlags: ["elbow-load"], coachingCue: "Stand with dumbbells at your sides, palms facing in.|Keep your elbows pinned to your sides throughout.|Curl both dumbbells up together, keeping the neutral grip.|Hold briefly at the top.|Lower with control.|The neutral grip shifts more load to the brachialis and brachioradialis — the muscles that build arm thickness." },
  "bosu-ball-seated-dumbbell-press-to-tricep-extension": { name: "Bosu Ball Seated Dumbbell Press to Tricep Extension", muscle: "Shoulders", equipment: "Bosu Ball", difficulty: "intermediate", eachSide: false, injuryFlags: ["elbow-load"], coachingCue: "Sit on the flat side of a Bosu ball with a dumbbell in each hand.|Press the dumbbells overhead to full extension.|From the top, bend at the elbows and lower the dumbbells behind your head into a tricep extension.|Press back up to the top and lower to the start.|Keep your core tight — the Bosu adds instability throughout.|Move with control on every phase." },
  "egyptian-cable-lateral-raise": { name: "Egyptian Cable Lateral Raise", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "advanced", eachSide: true, injuryFlags: ["shoulder-impingement"], coachingCue: "Stand sideways to the cable, the handle in the hand closest to the machine.|Reach your arm across your body to grip the handle  - pre-loading the stretch.|Raise your arm out and up to shoulder height in a lateral arc.|Hold at the top.|Lower with control, crossing your body again.|This angle pre-stretches the deltoid at the bottom. Go lighter  - you'll feel why immediately." },
    "standing-cable-external-rotation": { injuryFlags: ["lumbar-rotation-loaded"], name: "Standing Cable External Rotation", muscle: "Shoulders", equipment: "Cable Machine", difficulty: "beginner", eachSide: true, coachingCue: "Set the cable at 90 degrees  - at elbow height.|Stand sideways to the stack, elbow bent at 90 degrees and pinned to your side.|Rotate your forearm outward, away from your body, against the cable resistance.|Hold at the end range.|Return slowly with control.|Rotator cuff work. Always go light. Slow and controlled. This is shoulder health work." },
      "seated-arnold-press": { name: "Seated Arnold Press", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["shoulder-impingement","shoulder-overhead"], coachingCue: "Seated for stability. Rotate palms from facing you to facing forward press. All three delt heads recruited in one movement." },
          "dumbbell-curl-with-static-hold": { injuryFlags: ["elbow-load"], name: "Dumbbell Curl with Static Hold", muscle: "Biceps", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, coachingCue: "One arm curls while the other holds a dumbbell at 90 degrees. The static hold creates continuous tension and time under tension for both arms." },
    "single-arm-rope-extension": { name: "Single Arm Rope Extensions", muscle: "Triceps", equipment: "Cable Machine", difficulty: "intermediate", eachSide: true, injuryFlags: ["elbow-load"], coachingCue: "Single rope handle on high cable. Press down with one arm, elbow pinned. Full extension at bottom. Great for addressing imbalances between arms." },
        "hack-squat": { name: "Hack Squat", muscle: "Quads", equipment: "Hack Squat Machine", difficulty: "intermediate", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Position yourself in the machine, shoulders and back against the pads.|Place feet shoulder-width on the platform.|Lower until thighs are parallel or deeper.|Drive back up, squeezing your quads.|Don't lock out hard at the top.|Keep your lower back pressed against the pad throughout the movement."},
    "braced-squat": { name: "Braced Squat", muscle: "Quads", equipment: "Cable Machine", difficulty: "beginner", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Attach a rope to a low cable and hold it at chest height.|Stand back from the stack, arms extended.|Use the cable counterbalance squat deep.|The cable allows you to sit further back than bodyweight alone.|Drive through your heels to stand.|This is a goblet squat variation that teaches depth and upright torso."},
          "machine-calf-raises": { injuryFlags: ["ankle-impact"], name: "Machine Calf Raises", muscle: "Calves", equipment: "Calf Raise Machine", difficulty: "beginner", coachingCue: "Shoulders under pads. Rise onto balls of feet. Hold at the top, slow descent to a full stretch. Slow controlled reps beat fast sloppy ones." },
      "smith-machine-reverse-lunge": { name: "Smith Machine Reverse Lunge", muscle: "Quads", equipment: "Smith Machine", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Barbell on back in Smith machine. Step back into reverse lunge. Machine stabilizes the bar so you can focus on the leg movement." },
  "dumbbell-bulgarian-split-squat": { name: "Dumbbell Bulgarian Split Squat", muscle: "Quads", equipment: "Dumbbells", difficulty: "advanced", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Place your rear foot on a bench, front foot forward.|Hold dumbbells at your sides.|Lower your back knee toward the floor.|Drive through your front heel to stand.|Keep your front shin|This is one of the hardest single-leg movements. Take your time setting up the foot position."},
  "crossover-dumbbell-step-up": { name: "Crossover Dumbbell Step Up", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", eachLeg: true, injuryFlags: ["shoulder-impingement"] , coachingCue: "Stand beside a box or step, holding dumbbells.|Cross the far foot over and step onto the box.|Drive through that heel to stand on top.|Step back down and repeat.|The crossover motion fires the glute medius and hip stabilizers more than a standard step-up.|Don't let your knee cave inward."},
  "dumbbell-lateral-step-up": { name: "Dumbbell Lateral Step Up", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", eachLeg: true, coachingCue: "Stand beside a step or low platform, holding dumbbells.|Step laterally onto the platform with the closest foot.|Drive through that heel to bring the other foot up.|Step back down with control.|This builds lateral hip strength and stability that standard step-ups don't.|Keep your torso upright and core tight."},
    "walking-dumbbell-lunge": { name: "Dumbbell Walking Lunge", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Hold dumbbells at your sides, stand tall.|Step forward into a lunge, back knee nearly touching the floor.|Drive through your front heel to step the back foot forward into the next lunge.|Keep your torso upright  - don't lean forward.|Alternate legs walk.|Control each step. This is not a race."},
  "dumbbell-lunge-switches": { name: "Dumbbell Lunge Switches", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Hold dumbbells and get into a lunge position.|Jump up and switch legs, landing in the opposite lunge.|Keep your torso upright and absorb the landing.|The dumbbells add load to the plyometric movement.|Land softly  - control every landing before the next switch.|This builds explosive leg power and coordination."},
          "single-arm-step-up-and-press": { name: "Single-Arm Step Up and Press", muscle: "Full Body", equipment: "Dumbbells", difficulty: "advanced", eachSide: true, coachingCue: "Stand beside a step or box, hold one dumbbell at shoulder height.|Step up onto the box with the closest foot.|As you drive up, press the dumbbell overhead.|Lower the dumbbell and step back down.|This combines a lower body and upper body movement in one.|Drive through the stepping heel. Don't use momentum."},
  "dumbbell-renegade-row": { injuryFlags: ["lumbar-flexion-loaded", "wrist-load"], name: "Dumbbell Renegade Row", muscle: "Back", equipment: "Dumbbells", difficulty: "intermediate", eachSide: true, coachingCue: "Start in a plank position with both hands on dumbbells on the floor.|Row one dumbbell toward your hip while stabilizing with the other arm.|Lower with control and row the other side.|Keep your hips completely square  - no rotation.|Your core is working just back on this exercise.|Go lighter than you think. The plank position changes everything." },
  "kettlebell-swings": { name: "Kettle Bell Swings", muscle: "Full Body", equipment: "Kettlebell", difficulty: "intermediate", injuryFlags: ["lumbar-hinge-heavy"], coachingCue: "Hinge at hips, swing KB between legs, then drive hips forward explosively to swing the bell to chest height. This is a HIP HINGE not a squat. Power from the hips, not the arms." },
  "swiss-ball-reverse-hyper": { injuryFlags: ["lumbar-extension"], name: "Swiss Ball Reverse Hyper", muscle: "Glutes", equipment: "Swiss Ball", difficulty: "intermediate", coachingCue: "Lie face down over the swiss ball  - hips on the ball, hands on the floor for support, legs hanging.|Raise both legs up behind you until they're parallel to the floor or slightly higher.|Lower with control.|This is a lower back, glute, and hamstring movement.|Keep the movement controlled  - don't swing the legs up with momentum.|The swiss ball allows your hips to flex freely, giving you a full range of motion that a bench doesn't."},
    "bosu-ball-mountain-climbers": { injuryFlags: ["hip-flexion-loaded"], name: "Bosu Ball Mountain Climbers", muscle: "Cardio", equipment: "Bosu Ball", difficulty: "advanced", isTime: true, coachingCue: "Hands on Bosu ball, mountain climber pattern. The Bosu adds instability which increases shoulder and core demand. Maintain a rigid body position." },
          "ab-wheel-rollout": { injuryFlags: ["lumbar-flexion-loaded", "wrist-load"], name: "Ab Wheel Rollouts", muscle: "Core", equipment: "Ab Wheel", difficulty: "advanced", coachingCue: "Kneel on the floor holding the ab wheel with both hands directly under your shoulders.|Roll forward slowly, extending your arms and lowering your hips toward the floor.|At the furthest point you can control, pause  - then pull yourself back to the start.|Keep your core braced the entire time. Your back should not arch.|This is one of the hardest core exercises. Start with a short range and build.|If you can't return with control, you went too far. Dial it back."},
      "front-elbow-plank": { injuryFlags: ["wrist-load"], name: "Front Elbow Plank", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", isTime: true, coachingCue: "Standard forearm plank. Straight line from head to heels. Brace everything. Do not let the hips drop."},
  "raised-legs-toe-touches": { injuryFlags: ["lumbar-flexion-loaded"], name: "Raised-Legs Toe Touches", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", coachingCue: "Legs raised straight to 90 degrees. Reach hands up toward feet. Crunch straight up. Lower back on floor." },
  "medicine-ball-russian-twists": { name: "Medicine Ball Russian Twists", muscle: "Core", equipment: "Medicine Ball", difficulty: "intermediate", eachSide: true, injuryFlags: ["lumbar-rotation-loaded"] , coachingCue: "Sit on the floor, knees bent, feet either flat or slightly raised  - raised is harder.|Lean back to about 45 degrees  - find the balance point where your core is engaged.|Hold the medicine ball at your chest and rotate side to side, touching the ball to the floor on each side.|The ball adds load to every rotation  - feel it in your obliques.|Keep your chest up. Don't hunch forward.|Control the twist  - momentum defeats the purpose."},
    "hanging-leg-raises": { name: "Captain's Chair Leg Raise", muscle: "Core", equipment: "Captain's Chair", difficulty: "intermediate", injuryFlags: ["hip-flexion-loaded","lumbar-flexion-loaded"] , coachingCue: "Step into the captain's chair, back flat against the pad, forearms on the armrests.|Hang with legs straight.|Keeping legs straight, raise them until they're parallel to the floor or higher.|Lower with control  - don't swing or drop.|Straight legs make this significantly harder than the knee raise version.|If you can't keep legs straight with control, bend slightly at the knee until you build the strength."},
  "kneeling-cable-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Kneeling Cable Pulldown Crunch", muscle: "Core", equipment: "Cable Machine", difficulty: "intermediate" , coachingCue: "Attach the rope to the high cable, rope behind your head, elbows wide.|You can face toward OR away from the machine - both work, try both to see which you feel more.|Kneel on the floor or a pad directly below the cable.|Crunch your rib cage toward your pelvis - pulling the rope down fold.|Hold the contraction for a beat.|Return slowly - don't let the cable yank you back up.|This is a cable crunch, not a pulldown. Your arms don't move - your abs do the pulling.|Keep your hips still. All movement comes from the spine flexing."},
                "bench-reverse-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Bench Reverse Crunch", muscle: "Core", equipment: "Bench", difficulty: "intermediate" , coachingCue: "Lie on a flat bench, hands gripping the edge above your head for stability.|Bring your knees to your chest, then curl your hips up off the bench  - driving your knees toward the ceiling.|Lower back with control, knees stopping just before they fully extend.|The bench gives your upper body an anchor, which lets you focus entirely on the hip curl.|The movement is a posterior pelvic tilt  - your lower abs are lifting your hips, not just your knees bending.|Keep it slow on the way down."},
  "quadruped-plank-kb-pull-through": { name: "Quadruped Plank KB Pull Through", muscle: "Core", equipment: "Kettlebell", difficulty: "advanced", eachSide: true, injuryFlags: ["wrist-load"], coachingCue: "On all fours in plank position. Reach one hand under your body to pull a kettlebell to the other side. Anti-rotation core strength." },
    "shoulder-taps": { name: "Shoulder Taps", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", isTime: true , coachingCue: "Start in a high plank  - arms straight, shoulders over wrists, body in a straight line.|Lift one hand and tap the opposite shoulder.|Return and alternate sides.|Keep your hips completely square  - don't rock side to side tap.|The challenge is the anti-rotation demand  - your core is working to prevent your hips from shifting.|Go slow. Control the tap. The slower you go, the harder your core works."},
      "swiss-ball-knee-tucks": { name: "Swiss Ball Knee Tucks", muscle: "Core", equipment: "Swiss Ball", difficulty: "advanced", coachingCue: "Hands on floor in plank position, feet on Swiss ball. Pull knees toward chest, rolling the ball forward. Roll back out. Core and hip flexors with balance challenge." },
    "swiss-ball-pike": { name: "Swiss Ball Pike", muscle: "Core", equipment: "Swiss Ball", difficulty: "advanced", coachingCue: "Start in a high plank with your shins on top of the swiss ball, arms straight.|Drive your hips up toward the ceiling, rolling the ball toward your hands  - pike position.|Return to flat plank with control.|Keep your legs throughout.|The pike is a shoulder, core, and hip flexor challenge all in one.|Don't rush the return. The eccentric phase lower back to plank is where a lot of the work happens."},
  "assisted-sit-ups": { name: "Assisted Sit Ups", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band low to a door or sturdy base. Sit on the floor facing the anchor, knees bent, feet flat. Hold the band ends at chest height. Lower back slowly, then pull yourself up using your core with the band assisting. Keep tension on the band throughout." },
  "toe-taps": { name: "Toe Taps (on low platform)", muscle: "Cardio", equipment: "Low Platform", difficulty: "beginner", coachingCue: "Step up and tap the top of a low platform alternately with each foot. Cardiovascular drill with lateral agility. Increase speed get comfortable." },
    "jumping-jacks": { injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"], name: "Jumping Jacks", muscle: "Cardio", equipment: "Bodyweight", difficulty: "beginner", isTime: true , coachingCue: "Start with feet together and arms at your sides.|Jump, spreading legs wide, and raise arms overhead.|Return to the starting position with another jump.|Feet together to wide jump.|Arms follow the legs in a fluid motion.|Engage core throughout." },
  "stationary-marches": { injuryFlags: [], name: "Stationary Marches", muscle: "Cardio", equipment: "Bodyweight", difficulty: "beginner", isTime: true, coachingCue: "March in place driving knees to hip height. Controlled cardiovascular movement. Good for warm-ups or active recovery between strength sets." },
  "step-touch": { name: "Step Touch", muscle: "Cardio", equipment: "Bodyweight", difficulty: "beginner", isTime: true, coachingCue: "Step to one side tapping the foot together, then the other side. Basic lateral movement pattern. Used in warm-up and low-intensity cardio." },
  "garland-pose": { name: "Garland Pose", muscle: "Mobility", equipment: "Bodyweight", difficulty: "beginner", isTime: true, coachingCue: "Deep squat with feet wider than hips, toes pointed out. Press elbows against inner knees to encourage hip and groin opening. Hold and breathe." },
  "forward-side-leg-swings": { injuryFlags: ["lumbar-hinge-heavy"], name: "Forward & Side Leg Swings", muscle: "Mobility", equipment: "Bodyweight", difficulty: "beginner", eachLeg: true, coachingCue: "Hold support. Swing leg forward and back then side to side. Dynamic hip mobility drill. Use momentum but keep the swings controlled."},
      "resistance-tricep-pressdown": { injuryFlags: ["elbow-load"], name: "Resistance Band Tricep Pressdown", muscle: "Triceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band anchored high. Press down, elbows stay at sides. Full extension. Band gives ascending resistance which is hardest at lockout."},
    "standing-band-russian-twist": { name: "Standing Band Russian Twist", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Band anchored at chest height. Stand sideways, pull band across body with rotation. Oblique and rotational anti-resistance." },
  "band-pull-apart": { name: "Band Pull Apart", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band at chest height, arms extended. Pull band apart to your sides, stretching the band across your chest. Rear delts and rhomboids. Hold the stretch for a beat." },
  "resistance-band-stationary-lunge": { name: "Resistance Band Stationary Lunge", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Band adds resistance. Stationary split squat position. Front knee tracks over front foot. Drive up through front heel." },
  "resistance-band-bicep-curl": { injuryFlags: ["elbow-load"], name: "Resistance Band Bicep Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band under feet, curl straight up. Ascending resistance which is hardest at the top. Same mechanics curl."},
    "lying-single-leg-hamstring-curl-band": { injuryFlags: [], name: "Lying Leg Curl (Band)", muscle: "Hamstrings", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Lie face down on a mat with the band looped around one ankle and anchored behind you. Bend your knee and pull your heel towards your glutes against the resistance of the band. Keep your hips and upper body flat on the ground throughout. Slowly lower and repeat."},
  "bicep-curls-21s": { injuryFlags: ["elbow-load"], name: "Bicep Curls 21s", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Hold dumbbells or a bar at hip level, palms up.|Perform 7 reps from the bottom to 90 degrees  - lower half only.|Then 7 reps from 90 degrees to the top  - upper half only.|Then 7 full range reps without stopping.|21 total reps. That is one full set.|Keep your elbows pinned the entire time. No swinging." },
  "resistance-band-jump-squats": { name: "Resistance Band Jump Squats", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Place the band just above your knees or under your feet.|Lower into a squat position.|Explode up into a jump, driving your arms overhead.|Land softly with bent knees and immediately drop back into the next squat.|The band adds resistance on the way up.|Control the landing every time."},
  "dumbbell-step-ups": { injuryFlags: ["knee-deep-flexion", "knee-impact"], name: "Dumbbell Step Up", muscle: "Quads", equipment: "Dumbbells", difficulty: "beginner", eachLeg: true, coachingCue: "Stand in front of a low platform  - shin height or lower.|Place one foot on the platform.|Drive through that heel to step up.|Step back down with control.|The lower height makes this more accessible while still building the glute and quad.|Perfect for beginners or high-rep finishing exercise."},
        "resistance-band-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Resistance Band Crunch", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band anchored high, kneeling. Crunch elbows toward hips against band resistance." },
  "resistance-band-ab-twist": { injuryFlags: ["lumbar-rotation-loaded"],name: "Ab Twist (Band)", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Attach the band at mid-height to a door anchor or fixed point.|Stand sideways to the anchor, holding the band with both hands at your chest.|Rotate away from the anchor, keeping your hips facing forward.|The rotation comes from your core  - not your arms.|Return with control and repeat.|This is a rotational core exercise. Keep your hips locked. Only your torso moves." },
  "banded-wall-sit": { name: "Banded Wall Sit", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", isTime: true, injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Place the band around knees.|Sit against a wall with knees at a 90-degree angle.|Hold the position for the specified time.|Keep back against the wall.|Knees at a 90-degree angle pushing out against band.|Engage quads and glutes." },
      "resistance-band-front-raise": { injuryFlags: ["shoulder-impingement"], name: "Resistance Band Front Raise", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band under feet, raise forward to shoulder height. Band provides ascending resistance. Front delt isolation." },
  "resistance-band-lateral-raise": { injuryFlags: [], name: "Resistance Band Lateral Raise", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band under feet, raise to sides to shoulder height. Same mechanics lateral raise with ascending resistance from the band." },
  "half-kneeling-lat-pulldown": { name: "1/2 Kneeling Lat Pulldown", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Half kneeling position, cable overhead. Pull elbow down to hip. Kneeling eliminates cheating with your lower body and forces core stability." },
  "one-arm-bent-over-row-band": { injuryFlags: ["lumbar-flexion-loaded"], name: "Crank the Mower", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", eachSide: true, coachingCue: "Hold a dumbbell in one hand, hinge forward at the hips with a flat back.|Pull the dumbbell back and up in a motion that mimics pulling a lawnmower cord  - elbow driving back and up.|Squeeze the back and rear delt at the top.|Lower with control.|Keep your torso stable throughout  - don't let it rotate.|This is a unique elbow-back row that emphasizes the upper back and rear delt."},
  "standing-rows-band": { name: "Standing Rows (Band)", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band anchored in front of you. Row both handles to your ribs, elbows driving back. Keep shoulders down and back. Squeeze and hold each rep." },
  "bent-over-band-reverse-fly": { name: "Bent Over Reverse Fly", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Hinge forward, soft elbows, raise dumbbells to the sides. Rear delts and upper back do the work. Do not use momentum. Control the lowering." },
  "tricep-kickbacks": { name: "Tricep Kickbacks", muscle: "Triceps", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["elbow-load"], coachingCue: "Hinge forward, upper arm parallel to floor. Extend arm back to straight. Upper arm does not move. Squeeze tricep hard at full extension." },
  "resistance-band-reverse-curl": { injuryFlags: ["elbow-load","wrist-load"], name: "Resistance Band Reverse Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band under feet, overhand grip. Curl up with pronated wrists. Forearms and brachioradialis work heavily." },
  "standing-band-arm-circles": { name: "Standing Resistance Band Arm Circles", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", vimeoId: "946456284", coachingCue: "Band in hands, make circles forward or backward. Small controlled movements. Deltoid endurance work." },
  "resistance-band-deadlift": { name: "Resistance Band Deadlift", muscle: "Hamstrings", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"] , coachingCue: "Stand on the band with feet hip-width apart.|Hinge at the hips, keeping a slight bend in the knees.|Stand up, squeezing glutes at the top.|Keep the back straight throughout.|Hinge at the hips, not the waist.|Squeeze glutes at the top of the movement." },
  "standing-back-extension": { injuryFlags: ["elbow-load","lumbar-extension"], name: "Standing Back Extension", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Standing with band or cable. Extend from a bent-over position to upright. Lower back and glutes. Controlled extension." },
  "modified-shoulder-tap": { name: "Kneeling Pushup Shoulder Tap", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["wrist-load"], coachingCue: "Kneeling pushup. At the top, alternate shoulder taps. Anti-rotation challenge between each rep." },
      "standing-chest-press-band": { name: "Standing Chest Press (Band)", muscle: "Chest", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band anchored behind, standing. Press forward in a chest press motion. Core must stay braced to not rotate. Functional pressing strength." },
      "lunge-switches-band": { name: "Lunge Switches (Band)", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], vimeoId: "946571736", coachingCue: "Attach the band at chest height to a door anchor.|Stand facing the anchor in a lunge position, holding the band with both hands.|Step back into a lunge, creating tension on the band.|Drive forward to switch legs, maintaining your grip.|The band adds horizontal resistance that challenges your balance and core.|Keep your torso upright throughout the lunge switches." },
  "adduction-ankle-straps": { name: "Adduction (Ankle Straps)", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, vimeoId: "946450969", coachingCue: "Band around ankle, pull leg across your midline. Inner thigh is fully loaded. Stand tall, core braced. Controlled throughout." },
    "knee-pushup": { name: "Knee Pushup", muscle: "Chest", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["wrist-load"], coachingCue: "Knees on ground, body in a straight line from knees to head. Same hand position pushup. Reduces load to make pushups accessible. Focus on form." },
  "assisted-reverse-lunge": { name: "Assisted Reverse Lunge", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Hold onto a wall or rack for balance support.|Step one foot back and lower the back knee toward the floor.|Drive through your front heel to return to standing.|The support removes the balance challenge so you can focus on range and control.|Chest up, core engaged.|Build toward doing it without support."},
  "glute-bridge": { name: "Glute Bridge", muscle: "Glutes", equipment: "Bodyweight", difficulty: "beginner" , coachingCue: "Lie on your back, knees bent, feet flat on the floor hip-width apart.|Drive through your heels and raise your hips until your body forms a straight line from knees to shoulders.|Squeeze your glutes hard at the top.|Lower with control.|Don't let your lower back hyperextend at the top.|Full squeeze every rep."},
      "lying-curl-ups": { name: "Lying Curl Ups", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["elbow-load"], coachingCue: "Lying on back, curl upper back off floor and hold. More of an isometric hold than a dynamic crunch. Core must maintain the position." },
  "dumbbell-floor-press": { name: "Dumbbell Floor Press", muscle: "Chest", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Lying on floor, dumbbells at chest. Press straight up. The floor acts safety stop at the bottom. Good for shoulder health." },
  "seated-v-bar-cable-row": { injuryFlags: ["lumbar-flexion-loaded"], name: "Seated V-Bar Rows", muscle: "Back", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "V-bar neutral grip. Pull to your navel. Sit tall, no hunching. Controlled return to full extension on every rep."},
    "bird-dog": { injuryFlags: [], name: "Bird Dog", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", eachSide: true, coachingCue: "Get into a tabletop position on all fours  - hands under shoulders, knees under hips.|Keep your back completely flat.|Extend one arm forward and the opposite leg back simultaneously.|Hold for a beat, then return to tabletop.|Alternate sides.|The challenge is keeping your hips square and your back flat while your limbs extend. Don't let it sag." },
  "pop-squat": { name: "Pop Squat", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand with feet together.|Jump out to a wide squat, landing with feet wide and lowering into the squat.|Jump back to feet together.|The pop out and back creates a plyometric hip abduction movement.|Keep your knees tracking over your toes on every landing.|Land softly  - absorb the impact through your legs."},
  "dumbbell-romanian-deadlift": { name: "Dumbbell Romanian Deadlift", muscle: "Hamstrings", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"] , coachingCue: "Stand holding dumbbells in front of your thighs.|Hinge at the hips, pushing them back lower the dumbbells along your legs.|Feel the stretch in your hamstrings.|Drive your hips forward to return to standing.|Keep the dumbbells close to your body throughout.|Flat back the entire time. This is a hip hinge, not a squat."},
      "dumbbell-incline-press": { name: "Dumbbell Incline Press", muscle: "Chest", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Incline bench, dumbbells. Same bench press with dumbbells. Each arm works independently. Good range of motion and upper chest focus." },
  "lying-single-leg-hamstring-curl": { injuryFlags: [], name: "Lying Single Leg Hamstring Curl", muscle: "Hamstrings", equipment: "machine", difficulty: "beginner", eachLeg: true, coachingCue: "Lie face down on the machine, one leg on the pad, one leg relaxed.|Curl the working leg toward your glute.|Squeeze the hamstring at the top.|Lower with control.|Single-leg work corrects imbalances between sides.|Don't let your hip rise off the pad."},
          "dumbbell-deficit-glute-bridge": { name: "Dumbbell Deficit Glute Bridge", muscle: "Glutes", equipment: "Dumbbells", difficulty: "beginner" , coachingCue: "Lie flat on your back on the floor with your heels elevated on a bench or platform in front of you.|Place a dumbbell across your hip crease and hold it steady with both hands.|Drive your hips up by digging your heels into the platform and squeezing your glutes hard at the top.|The elevated heel position increases the range of motion and puts more demand on the hamstrings than a standard glute bridge.|Lower your hips back to the floor with control and repeat.|Keep your core braced. Do not hyperextend at the top."},
    "dumbbell-good-morning": { name: "Dumbbell Good Morning", muscle: "Hamstrings", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["lumbar-extension","lumbar-hinge-heavy"] , coachingCue: "Hold dumbbells at your sides or on your shoulders.|Hinge at the hips with a soft knee bend, pushing your hips back.|Lower your torso until it's nearly parallel to the floor.|Drive your hips forward to return to standing.|This is a hamstring and lower back movement.|Keep your back flat the entire time  - no rounding."},
  "resistance-band-squats": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], name: "Resistance Band Squats", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band under feet, held at shoulders. Squat against band resistance. Band is hardest at the standing position."},
    "band-cross-body-curl": { injuryFlags: ["elbow-load"], name: "Band Cross Body Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the band with feet shoulder width apart.|With one hand, perform a curl across the body.|Alternate sides for each repetition.|Keep a straight back.|Engage biceps during the curls.|Control the band on the way down." },
  "band-pallof-press": { injuryFlags: ["lumbar-rotation-loaded"], name: "Band Pallof Press", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Attach band at chest height.|Stand perpendicular to the anchor point.|Extend arms, resisting band pull.|Stand with feet more than shoulder-width apart.|Keep core engaged throughout.|Control the press, resisting the band pull." },
  "resistance-band-calf-raise": { injuryFlags: ["ankle-impact"], name: "Resistance Band Calf Raises", muscle: "Calves", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Place the resistance band under the balls of your feet.|Stand with feet hip-width apart, core engaged.|Hold handles or ends of the band.|Rise onto your toes, squeezing your calves.|Lower down with control.|Increase resistance gradually for progression." },
      "lying-bicycle-crunches": { name: "Lying Bicycle Crunches", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", isTime: true, injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"] , coachingCue: "Lie on your back, hands lightly behind your head  - don't pull on your neck.|Bring one knee toward your chest while rotating your opposite elbow toward that knee.|Extend the other leg out at the same time, keeping it just off the floor.|Alternate in a slow, deliberate pedaling motion.|The rotation should come from your torso, not just your elbows.|Keep both shoulder blades off the floor throughout the entire set."},
    "heel-touches": { name: "Heel Touches", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", eachSide: true, coachingCue: "Lying on back, knees bent. Alternate reaching each hand to touch the heel on that side. Lateral crunch motion. Side abs and obliques." },
  "upper-chest-wide-fly": { name: "Upper Chest Wide Fly (Band)", muscle: "Chest", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Band anchored below. Wide arc fly motion targeting upper pec. Squeeze when hands meet in front of your upper chest." },
  "upper-chest-narrow-fly": { name: "Upper Chest Narrow Fly (Band)", muscle: "Chest", equipment: "Resistance Band", difficulty: "beginner" , coachingCue: "Attach the band at chest height and hold with both hands close together in a narrow grip.|Stand back to create tension.|Press both hands together and forward in a fly motion, hands nearly touching at the end.|Squeeze the inner chest hard at the peak.|Return with control, full stretch at the start.|The narrow grip shifts the emphasis to the inner chest and sternal fibers."},
  "cross-body-upper-chest-fly": { name: "Cross Body Upper Chest Fly (Band)", muscle: "Chest", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["shoulder-impingement"], coachingCue: "Band anchored to the side and low. Pull across your body and up. Targets upper inner pec from a different angle. Squeeze at the top." },
  "stationary-lunge": { name: "Stationary Lunge", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand with feet together.|Step one foot forward into a lunge.|Lower the back knee towards the ground.|Keep a straight back and chest up.|Lower the back knee towards the ground.|Engage quads and glutes." },
  "resistance-band-bent-over-row": { name: "Resistance Band Bent Over Row", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Band under your feet, overhand grip. Hinge forward, row both handles to your lower chest. Good scapular retraction at the top." },
      "wall-sit": { name: "Wall Sit", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", isTime: true, injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Back flat against wall, knees at 90 degrees. Hold this static position. Quads work isometrically. Breathe steadily. The goal is time, not reps." },
  "alternating-hammer-curl": { injuryFlags: ["elbow-load"], name: "Alternating Hammer Curl", muscle: "Biceps", equipment: "Dumbbells", difficulty: "beginner", eachSide: true , coachingCue: "Stand with dumbbells at your sides, neutral grip  - palms facing each other.|Curl one dumbbell up while the other stays down.|Lower with control and alternate.|Keep elbows pinned to your sides.|The neutral grip emphasizes the brachialis and brachioradialis.|No swinging. Strict alternating reps."},
  "calf-raises": { injuryFlags: ["ankle-impact"], name: "Calf Raises", muscle: "Calves", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Both feet, rise onto balls of feet. Hold at top. Lower to stretch. Seems simple. Do it slowly through full range and you will feel it."},
  "underhand-dumbbell-row": { name: "Underhand Dumbbell Row", muscle: "Back", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Hold dumbbells with a supinated grip, palms facing up.|Hinge forward at the hips, back flat.|Row both dumbbells toward your lower abdomen.|Drive elbows straight back, close to your sides.|Squeeze the lats and biceps at the top.|Lower with control. Underhand grip shifts more work onto the biceps and lower lats."},
  "seated-to-standing": { injuryFlags: ["knee-deep-flexion"], name: "Body Weight Squat to Chair", muscle: "Quads", equipment: "Chair", difficulty: "beginner" , coachingCue: "Stand in front of a chair or bench.|Lower yourself sitting down, controlling the descent.|Lightly touch the chair and drive back up.|This teaches proper squat mechanics and depth.|Don't collapse onto the chair  - controlled touch and press.|Heels stay flat. Chest stays up."},
  "assisted-static-lunge": { name: "Assisted Static Lunge", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Hold onto a wall or rack for balance.|Step into a lunge and hold the bottom position.|Use the support to focus on range and control without worrying about balance.|Drive through your front heel to stand.|This is a progression tool  - build toward doing it without support.|Keep your torso upright throughout."},
  "superman": { name: "Superman", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["lumbar-extension"] , coachingCue: "Lie face down on the floor, arms extended overhead, legs straight.|Simultaneously raise your arms, chest, and legs off the floor  - squeezing your glutes and lower back.|Hold at the top for a beat.|Lower with control.|Keep your head neutral  - don't crane your neck to look up.|This strengthens the entire posterior chain. The hold at the top maximizes the contraction."},
  "heel-tap-band": { name: "Heel Tap (Band, attach low)", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", eachSide: true, coachingCue: "Band around ankles. Lying on back, knees bent. Push heels down toward floor against band resistance. Core brace throughout." },
  "swiss-ball-wall-squat": { name: "Swiss Ball Wall Squats", muscle: "Quads", equipment: "Swiss Ball", difficulty: "beginner", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Place the ball between your lower back and the wall.|Walk your feet forward slightly.|Lower into a squat, letting the ball roll up your back.|Drive through your heels to return to standing.|The ball teaches you to keep your back upright through the full range.|Go to parallel or deeper if your mobility allows."},
  "calf-raises-2up-1down": { injuryFlags: ["ankle-impact"], name: "Calf Raises 2 Up 1 Down", muscle: "Calves", equipment: "Bodyweight", difficulty: "beginner", eachLeg: true , coachingCue: "Stand on a step with heels hanging off the edge.|Rise onto both toes  - 2 count up.|Transfer weight to one foot at the top.|Lower on one leg  - slow 3 second negative.|The eccentric overload on one leg builds significantly more calf strength.|Switch legs each rep."},
      "leg-press": { name: "Machine Leg Press", muscle: "Quads", equipment: "Leg Press Machine", difficulty: "beginner", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Set the seat so your knees are at 90 degrees at the bottom.|Place feet shoulder-width on the platform.|Press through your heels to full extension  - don't lock out the knees hard.|Lower with control, going mobility allows.|Keep your lower back against the seat the entire time.|Heels stay flat on the platform. Don't let them rise."},
      "resistance-band-bulgarian-split-squat": { name: "Resistance Band Bulgarian Split Squat", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"] , coachingCue: "Stand with one foot on the band, holding the handles.|Place the other foot back on a platform or bench behind you.|Lower the back knee towards the ground, keeping front knee over ankle.|Drive through the front foot on the band to return to standing.|Complete all reps on one leg before switching.|Keep a straight back and chest up throughout." },
  "donkey-kicks": { injuryFlags: ["ankle-impact"], name: "Resistance Band Single Leg Glute Extension", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", eachLeg: true, coachingCue: "Band anchored low, around ankle. Standing, extend leg back against resistance. Squeeze the glute at peak extension."},
      "seated-resistance-band-rows": { injuryFlags: ["lumbar-flexion-loaded"], name: "Seated Row (Band)", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Sit on a mat with legs extended and loop the band around the soles of your feet.|Hold one end in each hand with a neutral grip.|Sit tall with a slight bend in the knees.|Pull the band toward your lower ribcage, driving elbows straight back.|Squeeze the shoulder blades together at the end of the pull.|Slowly return to the start under control." },
    "upper-chest-alternating-press": { name: "Upper Chest Alternating Press (Band)", muscle: "Chest", equipment: "Resistance Band", difficulty: "beginner", eachSide: true, coachingCue: "Band anchored behind. Alternating press targeting the upper chest. Each arm presses independently while the other holds." },
  "bent-over-back-fly": { name: "Bent Over Back Fly", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Bent over, raise arms back and to the sides. Pure rear delt. Back stays flat. Hinged and controlled." },
    "drop-lunge": { name: "Drop Lunge", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Drop one leg behind and across the other into a lunge. Similar to curtsy squat. Targets outer glute and hip stabilizers." },
      "band-front-lateral-raise": { injuryFlags: ["shoulder-impingement"], name: "Band Front & Lateral Raise", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the band with feet shoulder-width apart.|Lift one arm straight in front and the other out to the side simultaneously.|Control the descent of the band.|Keep a slight bend in the elbows.|Lift arms to shoulder height.|Control the band on the way back."},
        "trx-squat": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], name: "TRX Squat", muscle: "Quads", equipment: "TRX", difficulty: "beginner", coachingCue: "Hold TRX straps for balance, lean back slightly. Squat to full depth. The straps allow you to reach a deeper squat position." },
      "straight-arm-pulldown": { injuryFlags: [], name: "Straight Arm Pulldown", muscle: "Back", equipment: "Cable Machine", difficulty: "beginner" , coachingCue: "Stand at the high cable with a bar or rope.|Arms extended, slight bend in the elbows.|Pull the bar down in an arc to your thighs, keeping arms straight.|Squeeze the lats at the bottom.|Return slowly  - don't let the cable yank your arms back up.|No bending at the elbows. Straight arms the entire movement."},
  "standing-straight-arm-pulldown-band": { name: "Standing Straight Arm Pulldown (Band)", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band high above you.|Stand back to create tension, arms extended.|Pull the band down in an arc to your thighs, keeping arms straight.|Squeeze the lats at the bottom.|Return slowly — control the band back up.|No bending at the elbows. Straight arms throughout." },
    "one-arm-lat-pulldown-band": { name: "One Arm Lat Pulldown", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", eachSide: true, coachingCue: "Stand with feet hip-width apart and raise both hands overhead.|Keep one hand stationary while you pull the other hand down towards your side.|Engage your lat muscles pull down.|Repeat for the desired number of repetitions, then switch sides." },
    "seated-cable-row-wide-pronated": { injuryFlags: ["lumbar-flexion-loaded"], name: "Seated Cable Row (Wide Pronated)", muscle: "Back", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Wide overhand grip on bar attachment. Row to your upper abs. Wide grip hits the upper back and rear delts more than narrow." },
  "seated-dumbbell-press": { name: "Seated Dumbbell Overhead Shoulder Press", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", injuryFlags: ["shoulder-overhead"], coachingCue: "Seated upright, dumbbells at shoulder height. Press straight up to nearly locked. Lower controlled. No leg drive in the seated position." },
    "lying-rear-delt-fly": { name: "Lying Rear Delt Flyes", muscle: "Shoulders", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Lying face down on flat bench. Raise dumbbells in a rear delt fly pattern. Eliminates momentum and isolates the rear delt completely." },
  "dumbbell-floor-pec-fly": { name: "Dumbbell Floor Pec Fly", muscle: "Chest", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Lying on floor, fly motion with dumbbells. Floor limits how far arms can drop which protects the shoulder. Squeeze at the top where your hands meet." },
            "lying-heel-tap": { name: "Lying Heel Tap", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Lie on your back, knees bent, feet flat on the floor, arms at your sides.|Engage your core and tilt your pelvis so your lower back presses into the floor.|Reach one hand down to tap the heel on the same side, then alternate.|The movement is side to side  - your torso barely moves.|Keep the lower back pinned to the floor the entire time.|This is a small, controlled movement. Feel it in your obliques, not your neck." },
  "hyperextension-side-bend": { injuryFlags: ["elbow-load","lumbar-extension"], name: "Hyperextension Side Bend", muscle: "Core", equipment: "Machine", difficulty: "intermediate", coachingCue: "Position yourself sideways in the hyperextension machine, hip on the pad, feet anchored.|Arms crossed at your chest or one hand behind your head.|Lower your top shoulder toward the floor, bending laterally at the waist.|Drive back up using your obliques  - squeeze hard at the top.|Keep your hips square against the pad throughout.|This is lateral flexion work for the obliques, not a back exercise. Control the descent."},
  "straight-leg-toe-touches": { injuryFlags: ["lumbar-flexion-loaded"], name: "Lying Straight Leg Toe Touch", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Lie flat on your back, legs extended straight up toward the ceiling.|Arms extended toward your feet.|Crunch up and reach your hands toward your toes.|Lower with control  - don't let your upper body crash back down.|Keep your legs throughout.|The legs act fixed point. You're crunching up to meet them."},
  "knees-to-elbow-high-plank": { injuryFlags: ["wrist-load"], name: "Knees to Elbow High Plank", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", coachingCue: "Start in a high plank position  - arms straight, hands under shoulders.|Drive one knee toward the elbow on the same side, rotating slightly at the hip.|Return to plank and alternate sides.|Keep your hips  - don't let them pike or sag.|Your shoulder and core stability are both working here.|The rotation should come from the hip, not by twisting your whole body."},
  "alternating-bent-leg-v-up": { name: "Alternating Bent Leg V-Up", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", coachingCue: "Lie flat, arms extended overhead, legs straight.|Simultaneously raise one bent knee and reach the opposite hand toward it.|Lower back to flat and alternate sides.|The bent knee makes this more accessible than a full V-up while still demanding serious hip flexor and lower ab engagement.|Keep the lowering phase controlled  - don't let your arms or legs crash down.|Breathe out on each crunch, in lower." },
  "aquaman": { name: "Aquaman", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Lie face down on the floor, arms extended overhead, legs straight.|Simultaneously raise the opposite arm and opposite leg off the floor  - like a swimming motion.|Lower and alternate sides.|Keep your head neutral  - don't crane your neck up.|This is a posterior chain and lower back stability exercise, not a crunch.|The range of motion is small. Focus on the contraction, not height." },
  "bosu-ball-front-elbow-plank": { injuryFlags: ["wrist-load"], name: "Bosu Ball Front Elbow Plank", muscle: "Core", equipment: "Bosu Ball", difficulty: "intermediate", isTime: true, coachingCue: "Place your forearms on the flat side of the bosu ball, elbows under your shoulders.|Extend into a plank  - body in a straight line from head to heels.|The instability of the bosu forces constant micro-adjustments from your core.|Keep your hips level  - don't let them sag or pike.|Breathe steadily. Brace like you're about to take a punch.|Harder than a floor plank. Build the duration progressively."},
  "bosu-ball-high-plank": { injuryFlags: ["wrist-load"], name: "Bosu Ball High Plank", muscle: "Core", equipment: "Bosu Ball", difficulty: "intermediate", isTime: true, coachingCue: "Place both hands on the flat side of the bosu ball, arms straight, shoulders over wrists.|Hold a high plank position  - body straight from head to heels.|The bosu creates instability that your wrists, shoulders, and core all have to manage simultaneously.|Keep your hips level and your gaze just ahead of your hands.|Don't let the bosu tip side to side  - that's your core preventing it.|Progress to adding movement like shoulder taps once you can hold steady."},
  "hanging-knee-raise": { name: "Captain's Chair Knee Raise", muscle: "Core", equipment: "Machine", difficulty: "beginner", coachingCue: "Step into the captain's chair, back flat against the pad, forearms on the armrests, hands gripping the handles.|Hang with your legs straight.|Drive both knees up toward your chest.|Lower with control  - don't swing or let momentum take over.|Keep your back against the pad throughout  - don't let it arch away.|Squeeze your abs at the top of the movement. The lower back should stay neutral." },
  "criss-cross-leg-raise": { name: "Criss Cross Leg Raise", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["hip-flexion-loaded","lumbar-flexion-loaded"], coachingCue: "Lie flat on your back, hands under your glutes or at your sides for support.|Raise both legs to about 45 degrees.|Cross one leg over the other in a scissoring motion, then switch  - alternating which leg is on top.|Keep your lower back pressed into the floor throughout.|The crossing motion engages the inner thighs and lower abs together.|Keep the movement controlled  - no flailing. Feel each cross." },
  "decline-medicine-ball-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Decline Medicine Ball Crunch", muscle: "Core", equipment: "Medicine Ball", difficulty: "intermediate", coachingCue: "Anchor your feet at the top of a decline bench, lie back holding a medicine ball at your chest.|Crunch up, bringing the ball toward your knees.|Lower with control  - don't let gravity yank you back.|The decline angle increases the range of motion compared to a flat crunch.|Keep the medicine ball close to your body throughout.|Exhale on the way up. Slow on the way down."},
  "decline-medicine-ball-sit-up": { injuryFlags: ["hip-flexion-loaded", "lumbar-flexion-loaded"], name: "Decline Medicine Ball Sit Up", muscle: "Core", equipment: "Medicine Ball", difficulty: "intermediate", coachingCue: "Anchor your feet at the top of a decline bench, lie back holding a medicine ball at your chest.|Sit all the way up, driving the ball overhead at the top.|Lower back with control through the full range.|Full sit-up  - not a crunch. You're going all the way up and all the way down.|The medicine ball adds load and teaches you to extend through the top.|Keep the movement smooth. No jerking off the bench." },
  "dumbbell-hyperextension-side-bend": { injuryFlags: ["elbow-load","lumbar-extension"], name: "Dumbbell Hyperextension Side Bend", muscle: "Core", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Stand holding a dumbbell in one hand, arm at your side.|Bend laterally at the waist toward the dumbbell side, letting it lower toward your knee.|Drive back up using the opposite oblique  - squeeze it hard at the top.|The dumbbell provides resistance on the lowering phase and pulls your oblique into work on the return.|Keep your torso facing forward  - don't twist.|Stand tall at the top. This is a lateral flexion exercise, not a lean." },
  "dumbbell-hyperextension": { name: "Dumbbell Hyperextension", muscle: "Core", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["elbow-load","lumbar-extension"], coachingCue: "Position yourself face-down in the hyperextension machine, hip bones on the pad, feet anchored.|Hold a dumbbell at your chest or behind your head for added resistance.|Lower your upper body toward the floor by hinging at the hips.|Drive back up using your lower back and glutes  - squeeze at the top.|Don't hyperextend past neutral at the top  - stop when your body is in a straight line.|This is a posterior chain movement. Feel it in your lower back, glutes, and hamstrings." },
  "floor-reverse-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Floor Reverse Crunch", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Lie on your back, hands flat on the floor beside your hips or under your glutes.|Bring your knees to your chest, then curl your hips off the floor  - driving your knees toward your face.|Lower back with control, feet not quite touching the floor before the next rep.|The movement comes from your pelvis tilting, not just your knees bending.|Keep your lower back pressed into the floor at the bottom.|This isolates the lower abs more directly than a standard crunch."},
  "high-plank-window-washers": { injuryFlags: ["wrist-load"], name: "High Plank Window-Washers", muscle: "Core", equipment: "Bodyweight", difficulty: "intermediate", isTime: true, coachingCue: "Start in a high plank  - arms straight, shoulders over wrists, body in a straight line.|Keeping your arms straight, rotate your hips side to side in a slow, controlled arc  - like a windshield wiper.|Your feet stay planted and pivot hips swing.|Keep your shoulders square and your arms still  - the rotation is all in the hips and obliques.|The range of motion is controlled  - don't let your hips touch the floor on either side.|This is an oblique and anti-rotation challenge in a plank position."},
  "back-hyperextension": { name: "Hyperextension", muscle: "Core", equipment: "Machine", difficulty: "beginner", injuryFlags: ["elbow-load","lumbar-extension"], coachingCue: "Position yourself face-down in the hyperextension machine, hip bones on the pad, feet anchored.|Arms crossed at your chest or hands behind your head.|Lower your upper body toward the floor by hinging at the hips.|Drive back up using your lower back and glutes  - stop when your body is in a straight line.|Don't arch past neutral at the top.|This builds lower back endurance and posterior chain strength. Go through the full range." },
  "kettle-bell-side-bend": { name: "Kettlebell Side Bend", muscle: "Core", equipment: "Kettlebells", difficulty: "beginner", coachingCue: "Stand holding a kettlebell in one hand, arm at your side.|Bend directly to that side, letting the kettlebell lower toward your knee.|Drive back up using the opposite oblique  - squeeze at the top.|Keep your torso facing forward  - this is pure lateral flexion, no rotation.|Stand completely upright at the top before the next rep.|The opposite oblique is doing the work on the return, not your lower back." },
  "modified-forward-plank": { injuryFlags: ["wrist-load"], name: "Kneeling Forward Elbow Plank", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", isTime: true, coachingCue: "Kneel on the floor, then lower onto your forearms  - elbows under your shoulders.|Extend your body so your weight is on your knees and forearms  - body in a straight line from knees to shoulders.|Hold the position, breathing steadily.|The kneeling position makes this more accessible than a full plank while still building core endurance.|Keep your hips down  - don't let them pike up or sag.|Progress to a full forearm plank when you can hold this position comfortably for 30+ seconds."},
  "kneeling-high-plank": { injuryFlags: ["wrist-load"], name: "Kneeling High Plank", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", isTime: true, coachingCue: "Kneel on the floor, then place your hands down  - shoulders over wrists.|Body in a straight line from knees to head  - hips in line, not piked or sagging.|Hold and breathe steadily.|This is the starting point for building plank strength before progressing to a full high plank.|Keep your core braced the entire time  - don't relax at any point.|When this feels easy for 30+ seconds, progress to a full high plank."},
  "lying-leg-raises": { name: "Lying Leg Raise", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["hip-flexion-loaded","lumbar-flexion-loaded"], coachingCue: "Lie flat on your back, legs straight, hands under your glutes or at your sides.|Keeping your legs straight, raise them to 90 degrees  - perpendicular to the floor.|Lower with control, stopping just before your heels touch the floor.|Keep your lower back pressed into the floor throughout  - especially on the way down.|If your lower back arches, bend your knees slightly until you build the strength for straight legs.|The slower the descent, the harder it gets. That's where the lower ab work happens." },
  "modified-medicine-ball-russian-twist": { injuryFlags: ["lumbar-rotation-loaded"], name: "Modified Medicine Ball Russian Twist", muscle: "Core", equipment: "Medicine Ball", difficulty: "beginner", coachingCue: "Sit on the floor, knees bent, feet flat, holding a medicine ball at your chest.|Lean back slightly  - find the balance point where your core is engaged.|Rotate the ball side to side, touching it to the floor (or close to it) on each side.|Feet stay flat on the floor  - this is the modification that makes it accessible.|Keep your chest up and your movement controlled. Don't rush the rotation.|Feel the obliques engaging on each twist. The ball adds load to every rotation."},
    "modified-side-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Modified Side Crunch", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Lie on your side, knees bent and stacked, bottom arm extended for support, top hand behind your head.|Crunch your top elbow toward your top hip, lifting your shoulder off the floor.|Lower with control.|Keep your hips stacked  - don't let the bottom hip roll back.|This isolates the obliques in a position that's easier on the lower back than a standard side crunch.|Feel the squeeze in your side on every rep. Don't pull on your neck."},
  "swiss-ball-crunch": { injuryFlags: ["ankle-impact","hip-flexion-loaded","lumbar-flexion-loaded"], name: "Swiss Ball Crunch", muscle: "Core", equipment: "Swiss Ball", difficulty: "beginner", coachingCue: "Sit on a swiss ball and walk your feet forward until your lower back is resting on the ball.|Cross your arms at your chest or place hands behind your head.|Crunch up  - bringing your shoulders off the ball  - then lower through the full range.|The ball gives you a greater range of motion than a floor crunch: you get the stretch at the bottom.|Keep your feet flat and core tight throughout.|Don't pull on your neck. Lead with your chest, not your chin."},
  "swiss-ball-knee-tuck": { name: "Swiss Ball Knee Tuck", muscle: "Core", equipment: "Swiss Ball", difficulty: "intermediate", coachingCue: "Start in a high plank with your shins resting on top of the swiss ball.|Drive both knees toward your chest, rolling the ball forward with your feet.|Extend back out to the starting plank position.|Keep your arms straight and your shoulders stable throughout.|The ball rolling forward is controlled by your core and hip flexors  - not momentum.|Keep your hips from piking up tuck. Stay level." },
  "swiss-ball-push-pull": { name: "Swiss Ball Push-Pull", muscle: "Core", equipment: "Swiss Ball", difficulty: "advanced", isTime: true, coachingCue: "Start in a forearm plank with your forearms on top of the swiss ball.|Roll the ball forward by extending your arms, then pull it back by bending your elbows.|The push-pull motion creates an unstable, shifting load that your core has to constantly resist.|Keep your hips level  - no piking or sagging.|This is one of the most demanding plank variations. The ball never lets your core switch off.|Go through a small range. You don't need a big push to feel this." },
  "wall-oblique-pop": { name: "Wall Oblique Pop", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Stand sideways to a wall, feet hip-width apart, outer hand on the wall for light support.|Drive your outer knee up toward your outer elbow in a lateral crunch motion.|Lower and repeat, then switch sides.|The 'pop' refers to the explosive, punchy contraction of the oblique at the top of each rep.|Keep the movement sharp and deliberate  - this isn't a slow controlled rep, it's a pop.|The wall is just for balance, not weight bearing. Let your oblique do the work." },
  "high-plank": { injuryFlags: ["wrist-load"], name: "High Plank", muscle: "Core", equipment: "Bodyweight", difficulty: "beginner", isTime: true, coachingCue: "Place your hands flat on the floor, directly under your shoulders, arms straight.|Body in a straight line from head to heels  - no sagging hips, no piked-up glutes.|Feet hip-width apart, weight on the balls of your feet.|Brace your core like you're about to take a punch.|Breathe steadily  - don't hold your breath.|This is the foundation of almost every plank variation. Master it first."},
  "resistance-band-standing-palloff-press": { injuryFlags: ["lumbar-rotation-loaded"], name: "Resistance Band Standing Palloff Press", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Anchor the band at chest height to a door or fixed point.|Stand sideways to the anchor, feet shoulder-width apart, holding the band with both hands at your chest.|Press the band straight out in front of you  - arms fully extended.|Hold for a beat, then return.|The band is pulling you toward the anchor. Resist that rotation completely.|Keep your hips and shoulders square. The stillness is the exercise." },
  "band-overhead-side-bend": { name: "Band Overhead Side Bend", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the center of the band, gripping both ends overhead with arms extended.|Bend directly to one side, allowing the band to create light resistance.|Drive back up using your oblique on the opposite side.|Keep both arms extended overhead throughout.|This is lateral flexion  - your torso faces forward, no twisting.|Feel the stretch on the way down and the squeeze on the way back up." },
  "banded-prone-reach-pull": { injuryFlags: [], name: "Banded Prone Reach Pull", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Lie face down, band looped around both wrists.|Arms extended overhead on the floor.|Pull both arms back toward your hips against the band resistance  - like a Superman pull.|Return with control, letting the band guide your arms back overhead.|Keep your head neutral and your core engaged throughout.|This trains the posterior chain and shoulder stabilizers together."},
  "resistance-band-half-kneeling-diagonal-lift": { name: "Resistance Band Half-Kneeling Diagonal Lift", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Anchor the band low at a door. Kneel on one knee sideways to the anchor, far knee down.|Grip the band with both hands low, near the anchor side.|Pull the band up and diagonally across your body  - low to high  - rotating through your torso.|Return slowly against the resistance.|This is a reverse wood chop  - the movement pattern mirrors a chopping motion going upward.|Your hips stay still. The rotation comes from your core." },
  "resistance-band-half-kneeling-diagonal-lift-no-anchor": { name: "Resistance Band Half-Kneeling Diagonal Lift (No Anchor)", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Kneel on one knee, stand the band under the down knee.|Grip both ends with both hands low on the band side.|Pull upward and diagonally across your body  - low to high  - rotating through your torso.|Return slowly.|Same movement anchored version  - the band under the knee creates the resistance.|Hips stay still. Rotation from the core." },
  "resistance-band-half-kneeling-palloff-press": { injuryFlags: ["lumbar-rotation-loaded"], name: "Resistance Band Half-Kneeling Palloff Press", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Anchor the band at chest height. Kneel on one knee sideways to the anchor.|Hold the band at your chest with both hands.|Press straight out in front of you  - hold  - return.|The kneeling position removes your legs from compensating. Your core does all the anti-rotation work.|Keep your torso completely square to the front  - the band will try to rotate you toward the anchor.|This is one of the best core stability exercises there is." },
  "resistance-band-woodchop": { injuryFlags: ["lumbar-rotation-loaded"], name: "Resistance Band Half-Kneeling Woodchop", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Anchor the band high. Kneel on one knee sideways to the anchor, near knee down.|Grip the band with both hands high, near the anchor side.|Pull the band down and diagonally across your body  - high to low  - rotating through your torso.|Return slowly against the resistance.|This is a classic wood chop pattern  - the movement comes from your core, not your arms.|Hips stay still. Initiate from the obliques." },
  "resistance-band-leg-lift": { name: "Resistance Band Lying Leg Lift", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band low. Lie on your back with the band around your ankles.|Legs straight, lower back pressed into the floor.|Raise both legs against the band resistance, keeping them straight.|Lower with control  - the band adds resistance on the way down.|Keep your lower back flat throughout  - especially on the descent.|The band makes this harder on the lowering phase where most of the work happens." },
  "resistance-band-lying-russian-twist": { name: "Resistance Band Lying Russian Twist", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["lumbar-rotation-loaded"], coachingCue: "Anchor the band at low height. Lie on your back, knees bent.|Hold the band with both hands, arms extended toward the anchor.|Rotate your knees side to side  - toward the anchor and away  - against the resistance.|Keep your shoulders flat on the floor throughout.|The band adds resistance to one direction of the twist.|This is a lower-body rotation pattern that challenges the obliques from a different angle." },
  "resistance-band-side-bend": { name: "Resistance Band Side Bend", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the band with one foot, holding both ends in the hand on that side.|Let the band pull your arm down slightly  - that's the start position.|Bend away from the band side, then drive back using your oblique.|Keep your torso facing forward  - pure lateral flexion, no rotation.|The band provides resistance return to upright.|Stand completely tall at the top before the next rep." },
  "resistance-band-standing-woodchop": { injuryFlags: ["lumbar-rotation-loaded"], name: "Resistance Band Standing Woodchop", muscle: "Core", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Anchor the band high. Stand sideways to the anchor, feet shoulder-width.|Grip the band with both hands, arms extended toward the anchor.|Pull the band down and across your body in a diagonal arc  - high to low.|Rotate through your torso, hips following.|Return slowly against the resistance.|This is rotational power training. Your core initiates, your hips follow." },
  "alternating-cross-body-hammer-curl-band": { injuryFlags: ["elbow-load"], name: "Resistance Band Alternating Cross Body Hammer Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the center of the band, gripping both ends with a neutral grip  - palms facing each other.|Curl one hand across your body toward the opposite shoulder, keeping the neutral grip.|Lower with control and alternate.|The cross-body motion puts more emphasis on the long head of the bicep than a standard curl.|Keep your elbows pinned to your sides throughout.|No swinging. Pure curl." },
  "alternating-shoulder-press-band": { name: "Resistance Band Alternating Shoulder Press", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["shoulder-overhead"], coachingCue: "Stand on the center of the band, gripping both ends at shoulder height.|Press one arm overhead while the other stays at shoulder height.|Lower and alternate.|Keep your core braced  - alternating presses create a small rotational demand.|Drive straight up  - no flaring the elbow out wide.|Control the return. The band has tension all the way down." },
  "resistance-band-alternating-side-pushup": { name: "Resistance Band Alternating Side Pushup", muscle: "Chest", equipment: "Resistance Band", difficulty: "intermediate", injuryFlags: ["wrist-load"], coachingCue: "Loop the band around your back, gripping both ends in your hands in a pushup position.|Perform a pushup, then at the top shift your weight to one side  - like a lateral pushup motion  - then back to center.|Alternate sides each rep.|The band adds resistance on the press while the lateral shift adds a stability and shoulder challenge.|Keep your core tight throughout  - hips don't sag or pike.|The band will feel tighter press up. That's intentional." },
  "resistance-band-bent-over-pronated-row": { name: "Resistance Band Bent Over Pronated Row", muscle: "Back", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded"], coachingCue: "Stand on the center of the band, hinge forward at the hips with a flat back.|Grip both ends with an overhand grip  - palms facing down.|Row both hands toward your lower chest, driving elbows back.|Squeeze the upper back at the top.|Lower with control.|Overhand grip shifts more emphasis to the upper back and rear delts compared to an underhand row." },
  "resistance-band-close-grip-curl": { injuryFlags: ["elbow-load"], name: "Resistance Band Close Grip Bicep Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the band, feet together, gripping both ends close together  - hands nearly touching.|Curl both hands up toward your shoulders.|Squeeze at the top.|Lower with control.|The narrow grip shifts more emphasis to the long head of the bicep.|Keep your elbows pinned and your torso still. No swinging." },
  "resistance-band-front-lateral-raise": { injuryFlags: ["shoulder-impingement"], name: "Resistance Band Front & Lateral Raise", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the band, gripping both ends at your sides.|Raise both arms simultaneously  - one straight in front, one out to the side.|Both reach shoulder height at the same time.|Lower with control and alternate which arm goes front and which goes lateral.|Keep your torso still throughout.|This hits the anterior and medial deltoids in one movement." },
  "resistance-band-half-kneeling-concentration-curl": { injuryFlags: ["elbow-load"], name: "Resistance Band Half-Kneeling Concentration Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Kneel on one knee, anchor the band under the down knee.|Hold the end of the band in the hand on the same side, elbow braced against your inner thigh.|Curl toward your shoulder, squeezing at the top.|Lower slowly to full extension.|Bracing the elbow against your thigh eliminates momentum completely  - pure bicep isolation.|Same principle dumbbell concentration curl, adapted for the band." },
  "resistance-band-hammer-curl": { injuryFlags: ["elbow-load"], name: "Resistance Band Hammer Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Stand on the band, gripping both ends with a neutral grip  - palms facing each other.|Curl both arms up simultaneously, keeping the neutral grip throughout.|Squeeze at the top.|Lower with control.|Neutral grip targets the brachialis and brachioradialis more than a standard curl.|Keep elbows pinned. No rotation at the top." },
      "resistance-band-shoulder-press": { name: "Resistance Band Shoulder Press", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", injuryFlags: ["shoulder-overhead"], coachingCue: "Stand on the center of the band, gripping both ends at shoulder height, palms facing forward.|Press both arms overhead to full extension.|Lower back to shoulder height with control.|Keep your core braced  - the band creates upward resistance that can pull you off balance if you're not tight.|Drive straight up.|The band gets harder press higher  - the top is where you feel it most." },
  "resistance-band-squatting-preacher-curl": { name: "Resistance Band Squatting Preacher Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "intermediate", injuryFlags: ["elbow-load","knee-deep-flexion","knee-impact","knee-shear","wrist-load"], coachingCue: "Anchor the band low. Sit in a deep squat position facing the anchor.|Rest your upper arms on your inner thighs  - like a natural preacher bench.|Curl toward your shoulders against the band resistance.|Squeeze at the top.|Lower to full extension.|The squat position and thigh brace eliminate all momentum  - pure bicep isolation in an unconventional position." },
  "resistance-band-back-fly": { name: "Resistance Band Standing Back Fly", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band at chest height. Stand facing the anchor, gripping both ends.|Extend both arms out to the sides in a reverse fly motion, squeezing your rear delts at the end.|Return with control  - don't let the band snap your arms back.|Keep a slight bend in the elbows throughout.|Hinge forward slightly at the hips for a more direct rear delt pull.|This is rear delt and upper back work. Go light and feel the contraction." },
  "resistance-band-tension-curl": { injuryFlags: ["elbow-load"], name: "Resistance Band Tension Bicep Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Hold the band with both hands, one end in each hand with the band stretched between them  - creating constant tension even at rest.|Curl both arms up while maintaining the tension between your hands throughout.|The band being held under tension adds isometric resistance to the standard curl motion.|Squeeze at the top.|Lower with control.|The tension through the band activates more shoulder and bicep stabilizers than a standard curl." },
  "resistance-band-single-arm-tricep-extension": { injuryFlags: ["elbow-load"], name: "Resistance Band Single Arm Tricep Extension", muscle: "Triceps", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band low or stand on it. Reach one hand behind your head, gripping the band.|Extend your forearm upward to full lockout  - squeezing the tricep at the top.|Lower with control, feeling the stretch at the bottom.|Keep your upper arm vertical  - only your forearm moves.|One arm at a time allows you to focus on and correct imbalances between sides.|The overhead position targets the long head of the tricep through a full stretch." },
  "squatting-concentration-curl-band": { injuryFlags: ["elbow-load","knee-deep-flexion","knee-impact","knee-shear"], name: "Resistance Band Squatting Concentration Curl", muscle: "Biceps", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Anchor the band low. Sit in a deep squat facing the anchor, one elbow braced against your inner thigh.|Curl toward your shoulder against the band.|Squeeze hard at the top.|Lower to full extension.|The squat and braced elbow create total isolation  - no momentum possible.|Single arm version allows you to really focus on each bicep separately." },
  "resistance-band-tension-front-raise": { injuryFlags: ["shoulder-impingement"], name: "Resistance Band Tension Front Raise", muscle: "Shoulders", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Hold the band with both hands, creating tension between them with the band stretched across.|Raise both arms in front of you to shoulder height, maintaining the tension throughout.|Lower with control.|The band stretched between your hands creates resistance even during the raise itself  - not just from being anchored.|Keep your torso still and arms straight.|This variation activates more anterior deltoid and shoulder stabilizers than a standard front raise." },
    "banded-stationary-squat": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], name: "Banded Stationary Squat", muscle: "Quads", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Place the band just above your knees  - not around your feet.|Stand with feet shoulder-width, toes slightly out.|Lower into a squat, actively pushing your knees out against the band throughout.|Drive through your heels to stand  - keep pushing the knees out.|The band around the knees activates the hip abductors and glutes differently than a band under your feet.|This is about the knee tracking and glute activation, not added load." },
  "resistance-band-thruster": { name: "Resistance Band Thruster", muscle: "Full Body", equipment: "Resistance Band", difficulty: "intermediate", coachingCue: "Stand on the center of the band, gripping both ends at shoulder height.|Lower into a squat.|Drive up explosively through your heels and press both arms overhead reach the top.|Lower the band back to shoulders descend into the next squat.|One fluid movement  - squat and press happen together.|This is a full-body conditioning exercise. The band makes it harder at the top where the press happens." },
  "band-abductor-hip-flexion": { name: "Band Abductor Hip Flexion", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band at ankle height, loop it around one ankle.|Stand sideways to the anchor  - working leg farthest from it.|Lift the working leg out and away from your body in a lateral arc  - hip abduction with a slight forward component.|Lower with control against the band.|This combines hip abduction with hip flexion  - a unique angle that targets the hip abductors and TFL.|Keep your standing leg slightly bent and your torso upright." },
  "band-adductor-hip-flexion": { name: "Band Adductor Hip Flexion", muscle: "Glutes", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band at ankle height, loop it around the ankle closest to the anchor.|Stand sideways to the anchor  - working leg closest to it.|Bring the working leg across your body  - hip adduction with a slight forward component.|Lower with control back to start.|This targets the hip adductors and inner thigh in a standing position.|Keep your standing leg stable and your torso upright throughout." },
  "band-forward-hip-flexion": { name: "Band Forward Hip Flexion", muscle: "Core", equipment: "Resistance Band", difficulty: "beginner", coachingCue: "Anchor the band behind you at ankle height, loop it around one ankle.|Stand facing away from the anchor.|Drive the working knee up and forward  - hip flexion against the band resistance.|Lower with control.|The band creates resistance on the forward drive  - challenging the hip flexors and lower abs.|Keep your standing leg slightly bent and your torso upright throughout." },
    "dumbbell-thruster": { name: "Dumbbell Thruster", muscle: "Full Body", equipment: "Dumbbells", difficulty: "intermediate", coachingCue: "Hold dumbbells at shoulder height, palms facing in.|Lower into a full squat, keeping the dumbbells at shoulders.|Drive up explosively through your heels.|As you reach the top, press the dumbbells overhead.|Lower back to shoulders descend into the next squat.|One fluid movement  - squat and press happen together." },
  "eccentric-goblet-squat": { name: "Eccentric Goblet Squat (5-4-3-2-1)", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Hold a dumbbell or kettlebell at chest height.|Lower into a squat using a 5-second count.|Hold in the bottom position.|Drive back up with control.|The slow eccentric builds more strength than a standard squat.|Stay braced throughout the descent." },
  "ez-bar-good-morning": { name: "EZ Bar Good Morning", muscle: "Hamstrings", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["lumbar-extension","lumbar-hinge-heavy"], coachingCue: "Place the EZ bar across your upper back.|Stand with feet shoulder-width, soft knee bend.|Hinge at the hips, pushing them back lower your torso.|Lower until your torso is nearly parallel to the floor.|Drive your hips forward to return to standing.|Flat back the entire time. Feel the stretch in your hamstrings." },
  "ez-bar-romanian-deadlift": { name: "EZ Bar Romanian Deadlift", muscle: "Hamstrings", equipment: "EZ Bar", difficulty: "intermediate", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Hold the EZ bar at hip level with the angled grip.|Hinge at the hips, pushing them back lower the bar along your legs.|Feel the stretch build in your hamstrings.|Drive your hips forward to return to standing.|Keep the bar close to your body throughout.|Flat back the entire time. No rounding at the lower back." },
  "goblet-squat-jump": { name: "Goblet Squat Jump", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Hold a dumbbell at your chest with both hands.|Lower into a squat.|Explode up into a jump, keeping the dumbbell at your chest.|Land softly with bent knees and immediately descend into the next squat.|The dumbbell at your chest keeps you upright and adds load to the jump.|Absorb every landing  - don't crash down." },
  "kettlebell-suitcase-deadlift": { name: "Kettlebell Suitcase Deadlift", muscle: "Full Body", equipment: "Kettlebells", difficulty: "beginner", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Place a kettlebell beside each foot.|Hinge at the hips and grip the handles.|Drive through your heels to stand, keeping the kettlebells at your side.|Your torso stays square  - don't tilt toward the weight.|Lower with control.|This builds anti-lateral-flexion strength in your core and obliques." },
    "low-cable-squat": { injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear"], name: "Low Cable Squat", muscle: "Quads", equipment: "Cable Machine", difficulty: "beginner", coachingCue: "Attach the rope to the low cable, hold at chest height.|Stand back and squat down, using the cable counterbalance.|The cable allows you to sit back further than a bodyweight squat.|Drive through your heels to stand.|Keep your torso upright  - let the cable do the balancing work.|Great for learning squat mechanics and depth."},
  "low-platform-dumbbell-step-up": { name: "Low Platform Dumbbell Step-Up", muscle: "Quads", equipment: "Dumbbells", difficulty: "beginner", coachingCue: "Stand in front of a low platform holding dumbbells.|Place one foot fully on the platform.|Drive through that heel to stand on top.|Step back down with control.|Don't push off the floor with the trailing foot.|Keep your chest up and core tight throughout." },
  "low-platform-side-step-up": { name: "Low Platform Side Step-Up", muscle: "Glutes", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Stand beside a low platform.|Step laterally onto it with the closest foot.|Drive through that heel to bring your other foot up.|Step back down with control.|The lateral movement fires the hip abductors and outer glutes.|Keep your torso upright throughout." },
  "low-platform-step-ups": { name: "Low Platform Step-Up", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", coachingCue: "Stand in front of a low platform.|Place one foot fully on the surface.|Drive through that heel to stand on top.|Step back down with control.|All the work stays on the stepping leg  - don't push off the floor with the trailing foot.|Great entry-level step-up for beginners." },
  "machine-calf-2to1": { injuryFlags: ["ankle-impact"], name: "Machine Calf Raise 2-to-1", muscle: "Calves", equipment: "Machine", difficulty: "intermediate", eachLeg: true, coachingCue: "Stand on the calf raise platform with both feet.|Drive up onto both toes.|At the top, shift weight to one foot.|Lower slowly on one leg  - 3 second negative.|The eccentric overload on one leg builds significantly more calf strength.|Switch legs each rep or each set."},
  "machine-pause-single-leg-extension": { name: "Machine Pause Single Leg Extension", muscle: "Quads", equipment: "Machine", difficulty: "intermediate", eachLeg: true, injuryFlags: [], coachingCue: "Sit in the leg extension machine, one leg on the pad.|Extend to full lockout and hold for 2 to 3 seconds at the top.|Lower with control.|The pause eliminates momentum and keeps maximum tension on the quad.|Go lighter than you would for standard extensions.|Keep the non-working leg relaxed." },
  "modified-bulgarian-split-squat": { name: "Modified Bulgarian Split Squat", muscle: "Quads", equipment: "Bodyweight", difficulty: "beginner", eachLeg: true, injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Place your rear foot on a low elevation rather than a full bench height.|Front foot forward, hands on hips or holding dumbbells.|Lower your back knee toward the floor.|Drive through your front heel to stand.|The lower rear foot elevation makes this more accessible than the standard Bulgarian.|Find your foot position first, then add range." },
  "dumbbell-plyo-step-up": { name: "Dumbbell Plyo Step Up", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["knee-deep-flexion","knee-impact","knee-shear","ankle-impact"], coachingCue: "Hold dumbbells, stand in front of a box.|Step up explosively and drive the trail knee up at the top.|Step back down with control.|The explosive knee drive develops single-leg power.|Land with control every rep.|Don't let your knee cave on the landing." },
  "split-squat-jump": { name: "Split Squat Jump", muscle: "Quads", equipment: "Bodyweight", difficulty: "intermediate", eachLeg: true, injuryFlags: ["ankle-impact","hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Get into a split squat position.|Lower into the bottom position.|Explode up into a jump, keeping your feet in the split stance.|Land softly in the same position and immediately descend.|This is a single-position plyometric  - no switching legs mid-air.|Control every landing before the next jump." },
  "swiss-ball-single-leg-hamstring-curl": { injuryFlags: [], name: "Swiss Ball Single Leg Hamstring Curl", muscle: "Hamstrings", equipment: "Swiss Ball", difficulty: "advanced", eachLeg: true, coachingCue: "Lie on your back, one heel on the swiss ball, one leg raised.|Drive your hips up into a bridge.|Curl the ball toward you by bending your knee.|Extend back out with control.|Single leg makes this significantly harder than the two-leg version.|Keep your hips elevated throughout the entire set."},
  "t-bar-moving-lunge": { name: "T-Bar Moving Lunge", muscle: "Quads", equipment: "Barbell", difficulty: "advanced", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Straddle one end of a loaded barbell, holding it between your legs.|Step forward into a walking lunge.|The bar hangs between your legs move.|Drive through your front heel and step into the next lunge.|The bar creates a unique loading angle for the hips and glutes.|Keep your torso upright and core braced." },
    "trx-stationary-lunge": { name: "TRX Stationary Lunge", muscle: "Quads", equipment: "TRX", difficulty: "beginner", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Hold the TRX handles for balance support.|Step into a lunge position.|Lower your back knee toward the floor.|Drive through your front heel to return to the top.|The TRX removes the balance challenge so you can focus on depth and form.|Build toward doing it without the support." },
  "tuck-jump": { name: "Tuck Jump", muscle: "Full Body", equipment: "Bodyweight", difficulty: "intermediate", injuryFlags: ["ankle-impact","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Stand with feet hip-width.|Jump up and drive your knees toward your chest at the peak.|Land softly with bent knees.|Immediately jump again.|The tuck develops explosive power and coordination.|Land on the full foot  - not just your toes. Absorb each landing." },
  "vipr-romanian-deadlift": { name: "ViPR Romanian Deadlift", muscle: "Hamstrings", equipment: "ViPR", difficulty: "advanced", injuryFlags: ["lumbar-flexion-loaded","lumbar-hinge-heavy"], coachingCue: "Hold the ViPR tube at hip level.|Hinge at the hips, pushing them back lower the tube along your legs.|Feel the stretch build in your hamstrings.|Drive your hips forward to return to standing.|The ViPR's shifting load challenges your grip and stability.|Flat back the entire time." },
  "vipr-side-shuffle": { name: "ViPR Side-to-Side Shuffle", muscle: "Full Body", equipment: "ViPR", difficulty: "intermediate", coachingCue: "Hold the ViPR at chest height or at your sides.|Shuffle laterally  - two or three steps in each direction.|Stay low in an athletic position throughout.|Keep your weight on the balls of your feet.|The ViPR adds load and shifts your center of gravity move.|Stay light on your feet. Quick, controlled steps." },
  "dumbbell-moving-lateral-lunge": { name: "Moving Dumbbell Lateral Lunge", muscle: "Quads", equipment: "Dumbbells", difficulty: "intermediate", injuryFlags: ["hip-flexion-loaded","knee-deep-flexion","knee-impact","knee-shear"], coachingCue: "Hold dumbbells at your sides.|Step wide to one side and lower into a lateral lunge, pushing your hips back.|Drive through that heel and step the other foot to meet it.|Continue moving laterally, alternating sides.|Keep the lunging knee over your foot throughout.|Stay upright  - don't lean forward into the lunge." }
};

