// ─── Exercise Difficulty Range (spans multiple program tiers) ──────────────
// Each exercise in EXERCISES_DATA carries a single static "difficulty" tag,
// but the same exercise ID often actually appears across multiple program
// tiers (e.g. a "beginner"-tagged row variation also showing up in an
// intermediate-6x program day). Showing only the static tag understates
// this. Rather than hand-maintaining a second lookup table (which would
// silently drift out of sync the moment a program is edited - the exact
// failure mode already hit twice tonight with stale data disagreeing with
// its source of truth), this computes the real span once, at module load,
// by scanning PROGRAMS itself: the tier is inferred from each program key's
// own prefix (beginner-/intermediate-/advanced-), and every exercise id used
// anywhere in that program's days is recorded against that tier. After this
// one-time scan, lookups are O(1) and can never go stale relative to
// PROGRAMS, because they are derived from it directly rather than copied.
const DIFFICULTY_TIER_ORDER = ["beginner", "intermediate", "advanced"];
const exerciseDifficultyTiers = (() => {
  const map = {};
  for (const programKey of Object.keys(PROGRAMS)) {
    const tier = DIFFICULTY_TIER_ORDER.find(t => programKey.startsWith(t));
    if (!tier) continue;
    const days = PROGRAMS[programKey]?.days || [];
    for (const day of days) {
      for (const group of day.groups || []) {
        for (const ex of group.exercises || []) {
          if (!ex?.id) continue;
          if (!map[ex.id]) map[ex.id] = new Set();
          map[ex.id].add(tier);
        }
      }
    }
  }
  return map;
})();

// Returns a display label like "Beginner" or "Beginner-Advanced" (span of
// the lowest to highest tier this exercise actually appears in across real
// programs). Falls back to the exercise's own static difficulty tag if it
// was never found in any program's exercise list (e.g. a newly-added
// exercise not yet wired into a program day).
const getExerciseDifficultyLabel = (exerciseId, fallbackDifficulty) => {
  const tiers = exerciseDifficultyTiers[exerciseId];
  const capitalize = (t) => t.charAt(0).toUpperCase() + t.slice(1);
  if (!tiers || tiers.size === 0) {
    return fallbackDifficulty ? capitalize(fallbackDifficulty) : "";
  }
  const present = DIFFICULTY_TIER_ORDER.filter(t => tiers.has(t));
  if (present.length <= 1) return capitalize(present[0] || fallbackDifficulty || "");
  const lo = present[0];
  const hi = present[present.length - 1];
  return `${capitalize(lo)}-${capitalize(hi)}`;
};

// Filter exercises based on session length
// Exercise priority scoring for intelligent filtering
// Higher score = more important to keep
const getGroupPriority = (group) => {
  if (group.type === "cardio") return 0; // Always last priority
  const exercises = group.exercises || [];
  let score = 0;
  exercises.forEach(ex => {
    const data = EXERCISES_DATA[ex.id];
    if (!data) return;
    const muscle = (data.muscle || "").toLowerCase();
    // Compound lower body = highest priority (most caloric burn)
    if (["quads", "hamstrings", "glutes"].includes(muscle)) score += 4;
    // Compound upper body = high priority
    else if (["back", "chest"].includes(muscle)) score += 3;
    // Shoulders = medium priority
    else if (muscle === "shoulders") score += 2;
    // Arms/isolation = lower priority
    else if (["triceps", "biceps"].includes(muscle)) score += 1;
    // Core = lowest (trained indirectly by compounds)
    else if (muscle === "core") score += 0.5;
  });
  return score;
};

// Detect the dominant focus of a day from its groups
// Generate intelligent focus summary from filtered groups
// ─── Derive workout title from actual exercise muscles ─────────────────────────
// Reads exercise IDs → EXERCISES_DATA muscles → computes accurate title
// This is what shows on the WorkoutListScreen hero and the weekly view card
const deriveWorkoutTitle = (groups, dayType, focus) => {
  if (!groups || groups.length === 0) return "Workout";

  // Honor explicit rest/cardio day types
  if (dayType === "rest") return "Rest Day";

  // Pure cardio day — no exercise groups
  const hasOnlyCardio = groups.every(g => g.type === "cardio");
  if (hasOnlyCardio) return "Cardio";

  const hasCardio = groups.some(g => g.type === "cardio");
  const workoutGroups = groups;

  // Pure cardio day — no strength groups at all
  if (workoutGroups.length === 0 && hasCardio) return "Cardio";

  // Collect all muscle groups from actual exercises
  const muscleCounts = {};
  workoutGroups.forEach(g => {
    (g.exercises || []).forEach((ex) => {
      const exData = EXERCISES_DATA[ex.id];
      if (!exData) return;
      const muscle = exData.muscle || "";
      // Map muscles to categories
      if (["Back", "Biceps"].includes(muscle)) {
        muscleCounts["Back & Biceps"] = (muscleCounts["Back & Biceps"] || 0) + 1;
      } else if (["Chest", "Triceps"].includes(muscle)) {
        muscleCounts["Chest & Triceps"] = (muscleCounts["Chest & Triceps"] || 0) + 1;
      } else if (["Quads", "Hamstrings", "Glutes", "Calves"].includes(muscle)) {
        muscleCounts["Legs"] = (muscleCounts["Legs"] || 0) + 1;
      } else if (muscle === "Shoulders") {
        muscleCounts["Shoulders"] = (muscleCounts["Shoulders"] || 0) + 1;
      } else if (muscle === "Core") {
        muscleCounts["Abs"] = (muscleCounts["Abs"] || 0) + 1;
      } else if (muscle === "Full Body") {
        muscleCounts["Full Body"] = (muscleCounts["Full Body"] || 0) + 1;
      }
    });
  });

  // Determine dominant category and combination
  const hasLegs = muscleCounts["Legs"] > 0;
  const hasUpper = (muscleCounts["Back & Biceps"] || 0) + (muscleCounts["Chest & Triceps"] || 0) + (muscleCounts["Shoulders"] || 0) > 0;
  const hasAbs = muscleCounts["Abs"] > 0;
  const hasBack = muscleCounts["Back & Biceps"] > 0;
  const hasChest = muscleCounts["Chest & Triceps"] > 0;
  const hasShoulders = muscleCounts["Shoulders"] > 0;
  const upperTypes = [hasBack, hasChest, hasShoulders].filter(Boolean).length;

  let title = "";

  if (hasLegs && hasUpper) {
    title = "Upper Body & Legs";
  } else if (hasLegs && hasAbs && !hasUpper) {
    title = "Legs & Abs";
  } else if (hasLegs && !hasUpper && !hasAbs) {
    title = "Legs";
  } else if (hasBack && hasChest && hasShoulders) {
    // All three upper groups = just "Upper Body"
    title = "Upper Body";
  } else if (hasBack && hasChest && !hasShoulders && !hasLegs) {
    title = "Upper Body";
  } else if (hasChest && hasShoulders && !hasBack && !hasLegs) {
    // Chest + Shoulders is still "Upper Body" — too verbose otherwise
    title = "Upper Body";
  } else if (hasBack && hasShoulders && !hasChest && !hasLegs) {
    title = "Back, Biceps & Shoulders";
  } else if (hasBack && !hasChest && !hasShoulders && !hasLegs) {
    title = "Back & Biceps";
  } else if (hasChest && !hasBack && !hasShoulders && !hasLegs) {
    title = "Chest & Triceps";
  } else if (hasShoulders && !hasBack && !hasChest && !hasLegs) {
    title = hasAbs ? "Shoulders & Abs" : "Shoulders";
  } else if (hasUpper && upperTypes >= 2) {
    title = "Upper Body";
  } else if (Object.keys(muscleCounts).length > 0) {
    const sorted = Object.entries(muscleCounts).sort((a, b) => b[1] - a[1]);
    title = sorted.slice(0, 2).map(e => e[0]).join(" & ");
  } else {
    title = "Full Body";
  }

  // Append Abs suffix only if abs are significant AND title doesn't already say Upper Body
  if (hasAbs && !title.includes("Abs") && !title.includes("Upper Body")) {
    const absCount = muscleCounts["Abs"] || 0;
    const total = Object.values(muscleCounts).reduce((a, b) => a + b, 0);
    if (absCount / total >= 0.25) title += " & Abs";
  }

  // Pure cardio day — no strength exercises at all
  if (hasCardio && Object.keys(muscleCounts).length === 0) return "Cardio";

  if (hasCardio) title += " & Cardio";

  return title || "Workout";
};

const getFocusSummary = (groups, dayType) => {
  return deriveWorkoutTitle(groups, dayType);
};

const getDayFocus = (groups) => {
  const exerciseGroups = groups.filter(g => g.type !== "cardio");
  const focuses = exerciseGroups.map(g => g.focus || "full");
  const hasUpper = focuses.some(f => f.includes("upper"));
  const hasLower = focuses.some(f => f.includes("lower"));
  const hasCore = focuses.some(f => f === "core");
  if (hasUpper && hasLower) return "full";
  if (hasLower) return "lower";
  if (hasUpper) return "upper";
  if (hasCore) return "core";
  return "full";
};

// Filters cardio option lines based on what equipment the building actually has.
// Non-bullet lines (headers/descriptions) always pass through.
const filterCardioNote = (note, buildingEquipment) => {
  if (!buildingEquipment || buildingEquipment.length === 0) return note;
  const equipmentRules = {
    "Treadmill Walk or Run": ["treadmill"],
    "Stationary Bike": ["bike"],
    "Elliptical": ["elliptical"],
    "Stairmaster": ["stairmaster"],
    "Jump Rope": ["jump-rope"],
    "Rowing Machine": ["rowing-machine"],
  };
  const lines = note.split("\n");
  const hasRowingMachine = lines.some(l => l.trim() === "• Rowing Machine");
  const rowingAvailable = buildingEquipment.includes("rowing-machine");
  const filtered = lines.filter(line => {
    if (!line.startsWith("•")) return true;
    const label = line.replace("•", "").trim();
    const required = equipmentRules[label];
    if (!required) return true;
    return required.some(eq => buildingEquipment.includes(eq));
  });
  if (rowingAvailable && !hasRowingMachine) {
    const jumpRopeIdx = filtered.findIndex(l => l.trim() === "• Jump Rope");
    if (jumpRopeIdx !== -1) {
      filtered.splice(jumpRopeIdx, 0, "• Rowing Machine");
    } else {
      const lastBullet = filtered.map((l, i) => l.startsWith("•") ? i : -1).filter(i => i !== -1).pop();
      if (lastBullet !== undefined) filtered.splice(lastBullet, 0, "• Rowing Machine");
    }
  }
  return filtered.join("\n");
};

// Recursively removes any undefined value anywhere in an object or array before it's sent
// to Firestore. Firestore rejects writes containing undefined outright (it only allows a
// real value, null, or the key being absent entirely), and undefined can sneak in from many
// different nested sources (dynamically-built exercise data, optional fields, etc). Rather
// than track down every individual possible source one at a time, this guarantees a write
// can never fail for this reason again, no matter where the undefined value originated.
const stripUndefinedDeep = (value) => {
  if (Array.isArray(value)) {
    return value.map(stripUndefinedDeep);
  }
  if (value && typeof value === "object" && !(value instanceof Date)) {
    const cleaned = {};
    Object.keys(value).forEach(key => {
      const v = value[key];
      if (v !== undefined) {
        cleaned[key] = stripUndefinedDeep(v);
      }
    });
    return cleaned;
  }
  return value;
};

const parseInjuryFlags = (injuryText, isSenior = false) => {
  const flags = [];
  // All seniors automatically get impact protection regardless of reported injuries —
  // high-impact and jumping movements carry real fall/joint risk at any fitness level once
  // someone is 65+, not just for those who happen to have entered a relevant injury.
  if (isSenior) flags.push("ankle-impact", "knee-impact", "knee-shear");
  if (!injuryText || injuryText === "none") return [...new Set(flags)];
  const text = injuryText.toLowerCase();
  // Knee — catches: knee, knees, acl, mcl, meniscus, patella, kneecap, pcl
  if (text.includes("knee") || text.includes("knees") || text.includes("acl") || text.includes("mcl") || text.includes("meniscus") || text.includes("patella") || text.includes("kneecap") || text.includes("pcl")) {
    flags.push("knee-deep-flexion", "knee-impact", "knee-shear");
  }
  // Back — unambiguous medical terms always count; the generic word "back" only
  // counts alongside real injury context, since "back" alone is often idiomatic
  // ("get back into the gym", "a while back", "back on track").
  const hasUnambiguousBackTerm = text.includes("spine") || text.includes("lumbar") || text.includes("disc") || text.includes("herniat") || text.includes("sciatica") || text.includes("scoliosis") || text.includes("sacral") || text.includes("si joint");
  const hasBackWithContext = text.includes("back") && (
    text.includes("lower back") || text.includes("upper back") || text.includes("mid back") || text.includes("middle back") || text.includes("bad back") ||
    text.includes("pain") || text.includes("hurt") || text.includes("ache") || text.includes("sore") ||
    text.includes("injur") || text.includes("issue") || text.includes("problem") ||
    text.includes("sprain") || text.includes("strain") || text.includes("tweak") ||
    text.includes("surgery") || text.includes("chronic") || text.includes("bulge") || text.includes("slip")
  );
  if (hasUnambiguousBackTerm || hasBackWithContext) {
    flags.push("lumbar-flexion-loaded", "lumbar-hinge-heavy", "lumbar-rotation-loaded", "lumbar-extension");
  }
  // Shoulder — catches: shoulder, rotator, labrum, impingement, cuff, bursitis, ac joint, acromial
  if (text.includes("shoulder") || text.includes("rotator") || text.includes("labrum") || text.includes("impingement") || text.includes("cuff") || text.includes("bursitis") || text.includes("ac joint") || text.includes("acromial")) {
    flags.push("shoulder-impingement", "shoulder-overhead");
  }
  // Wrist — catches: wrist, carpal, tendon, tendinitis, tendinopathy
  if (text.includes("wrist") || text.includes("carpal") || (text.includes("tendon") && !text.includes("shoulder")) || text.includes("tendinit") || text.includes("tendinopat")) {
    flags.push("wrist-load");
  }
  // Elbow — catches: elbow, tennis elbow, golfer, epicondyl
  if (text.includes("elbow") || text.includes("tennis elbow") || text.includes("golfer") || text.includes("epicondyl")) {
    flags.push("elbow-load");
  }
  // Hip — catches: hip, groin, it band, iliotibial, psoas, flexor
  if (text.includes("hip") || text.includes("hips") || text.includes("groin") || text.includes("it band") || text.includes("iliotibial") || text.includes("psoas") || text.includes("hip flexor")) {
    flags.push("hip-flexion-loaded");
  }
  // Ankle — catches: ankle, achilles, plantar, foot, feet, shin splint
  if (text.includes("ankle") || text.includes("ankles") || text.includes("achilles") || text.includes("plantar") || text.includes("shin splint") || (text.includes("foot") && !text.includes("football")) || text.includes(" feet")) {
    flags.push("ankle-impact");
  }
  // Neck — catches: neck, cervical, trap, trapezius (upper)
  if (text.includes("neck") || text.includes("cervical")) {
    flags.push("neck-flexion");
  }
  return [...new Set(flags)];
};

// Exercises whose raw "equipment" text is genuinely ambiguous (bare "Machine", generic
// "Row Machine", etc.) — resolved per-exercise-ID by what the exercise's name/coaching cue
// actually describes, rather than guessed from the equipment string alone.

const EQUIPMENT_ID_OVERRIDES = {
  "machine-leg-extension": "leg-extension",
  "machine-pause-single-leg-extension": "leg-extension",
  "hyperextension-side-bend": "hyperextension-bench",
  "hanging-knee-raise": "pull-up-bar",
  "back-hyperextension": "hyperextension-bench",
  "machine-calf-2to1": "calf-raise-machine",
};

// Canonical mapping from raw, messy "equipment" field text (lowercased) to the building
// equipment IDs selectable in the manager dashboard. Bands, bodyweight, and a few universal
// low-cost accessories (chair, low platform, step platform) are intentionally excluded from
// this map — they're treated-available regardless of the building's equipment list.
const EQUIPMENT_CANONICAL_MAP = {
  "dumbbell": "dumbbells", "dumbbells": "dumbbells",
  "barbell": "barbell",
  "ez bar": "ez-bar", "ez_bar": "ez-bar",
  "trap bar": "trap-bar", "hex bar": "trap-bar",
  "bench": "bench",
  "kettlebell": "kettlebells", "kettlebells": "kettlebells",
  "smith machine": "smith-machine",
  "cable machine": "cable-machine", "cable": "cable-machine", "cable_machine": "cable-machine",
  "leg press machine": "leg-press",
  "leg curl machine": "leg-curl",
  "leg extension machine": "leg-extension",
  "hack squat machine": "hack-squat-machine",
  "calf raise machine": "calf-raise-machine",
  "chest press machine": "chest-press-machine",
  "shoulder press machine": "shoulder-press-machine",
  "fly machine": "fly-machine", "pec deck machine": "fly-machine",
  "ab curl machine": "ab-curl-machine",
  "assisted dip machine": "assisted-dip-machine",
  "assisted pull up machine": "assisted-pull-up-machine",
  "row machine": "seated-row-machine",
  "t-bar row machine": "t-bar-row-machine",
  "treadmill": "treadmill",
  "jump rope": "jump-rope",
  "pull up bar": "pull-up-bar", "dip bar": "pull-up-bar", "captain's chair": "pull-up-bar",
  "trx": "trx",
  "swiss ball": "swiss-ball", "swiss_ball": "swiss-ball",
  "medicine ball": "medicine-balls", "medicine_ball": "medicine-balls", "vipr": "medicine-balls",
  "bosu ball": "bosu-ball", "bosu_ball": "bosu-ball",
  "agility ladder": "agility-ladder",
  "plyo box": "plyo-box",
  "ab wheel": "ab-wheel",
  "hyperextension bench": "hyperextension-bench",
  "weight plate": "barbell",
};

// Raw equipment text (or exercise category) that is always allowed, regardless of the
// building's equipment list — bands and bodyweight are Senz's deep, intentional fallback
// content library for low-equipment scenarios, "varies" is a flexible pick-your-own-cardio
// slot, and a few near-universal low-cost items aren't worth gating on.
const isAlwaysAllowedEquipment = (eq) => {
  return eq.includes("band") || eq.includes("bodyweight") || eq === "" || eq === "varies"
    || eq === "chair" || eq === "low platform" || eq === "step platform";
};

// Shared, single source of truth for equipment compatibility — used identically by the
// regular display-time filter, Month 6+ generation, and manual exercise swaps, so there is
// never a divergence between what gets generated and what gets shown to the user. Checks
// the SPECIFIC piece of equipment an exercise needs against what the building actually has,
// rather than only a handful of hardcoded machine types.
const passesEquipmentCheck = (eq, equipmentPreference, buildingEquipment, exerciseId = "") => {
  if (equipmentPreference === "bands" || equipmentPreference === "bands-only") {
    return eq.includes("band") || eq.includes("bodyweight") || eq === "";
  }
  if (equipmentPreference === "bodyweight-only") {
    return eq.includes("bodyweight") || eq === "";
  }
  if (equipmentPreference === "gym" || equipmentPreference === "gym-only") {
    if (eq.includes("band") && !eq.includes("cable")) return false;
  }
  if (isAlwaysAllowedEquipment(eq)) return true;
  if (buildingEquipment.length === 0) return true;

  const overrideKey = EQUIPMENT_ID_OVERRIDES[exerciseId];
  if (overrideKey) return buildingEquipment.includes(overrideKey);

  const canonicalKey = EQUIPMENT_CANONICAL_MAP[eq];
  if (canonicalKey) return buildingEquipment.includes(canonicalKey);

  // Unmapped/unrecognized equipment text — fail open rather than silently hide exercises
  // due to a gap in the mapping table.
  return true;
};


const expandDayTitle = (title) => {
  if (!title) return title;
  return title
    .replace(/— Upper$/i, "— Upper Body")
    .replace(/— Lower$/i, "— Lower Body")
    .replace(/— Upper\//gi, "— Upper Body/")
    .replace(/\/Upper\//gi, "/Upper Body/")
    .replace(/\/Upper$/gi, "/Upper Body")
    .replace(/— Lower\//gi, "— Lower Body/")
    .replace(/\/Lower\//gi, "/Lower Body/")
    .replace(/\/Lower$/gi, "/Lower Body");
};

