const isProgramGenderCompatible = (key, gender) => {
  const isMensProgram = key.startsWith("mens-");
  const isWomensProgram = key.startsWith("womens-");
  if (!isMensProgram && !isWomensProgram) return true;
  if (gender === "male") return isMensProgram;
  if (gender === "female") return isWomensProgram;
  return false;
};

// Athletic-tagged programs are a distinct, specialized category (sport-specific, agility-
// focused work) that never appears outside the athletic_performance goal anywhere in
// getAdvancedProgramPath's paths — unlike the named/hypertrophy programs, which legitimately
// overlap across multiple goals and shouldn't be artificially restricted.
const isProgramGoalCompatible = (key, goal) => {
  if (key.includes("athletic")) return goal === "athletic_performance";
  return true;
};

// A completed cycle's programKey is either a raw pool key (e.g.
// "intermediate-hypertrophy-month-1") or a "month6-" prefixed one (e.g.
// "month6-intermediate-hypertrophy-month-1") for a Month 6+ cycle generated
// FROM that same skeleton. Every place that checks "has this raw pool key
// already been used" needs to recognize both forms same underlying
// program, or a key used repeatedly Month 6+ skeleton never gets
// marked "used" for pool-availability purposes - it keeps looking eligible
// forever, both Month 6+ base and, if it's first in array order, even
// genuine pool-rotation pick, defeating rotation on both fronts from
// the same root cause. Used consistently by generateMonth6Program and
// generateAIProgram below, rather than each doing its own ad hoc check.
const stripMonth6Prefix = (key) => key.startsWith("month6-") ? key.slice("month6-".length) : key;
const getUsedBaseKeys = (previousPrograms) => previousPrograms.map(stripMonth6Prefix);

// Classifies a day's real muscle-group composition into a specific, narrow
// category (not the broad upper-body/lower-body/full-body split used
// elsewhere) - this is what lets Month 6+ Phase 2 recombination (once every
// whole skeleton has been used at least once) match a leg day to another
// template's leg day specifically, a back day to another back day, rather
// than treating any two "upper-body" days, which would
// blur the actual muscle targeting of a borrowed day.
const classifyDayCategory = (groups) => {
  const muscleCounts = {};
  (groups || []).forEach((g) => {
    if (g.type === "cardio") { muscleCounts["Cardio"] = (muscleCounts["Cardio"] || 0) + 1; return; }
    (g.exercises || []).forEach((ex) => {
      const m = (EXERCISES_DATA)[ex.id]?.muscle;
      if (m) muscleCounts[m] = (muscleCounts[m] || 0) + 1;
    });
  });
  const hasLegs = ((muscleCounts["Quads"] || 0) + (muscleCounts["Hamstrings"] || 0) + (muscleCounts["Glutes"] || 0) + (muscleCounts["Calves"] || 0)) > 0;
  const hasBack = (muscleCounts["Back"] || 0) > 0;
  const hasBiceps = (muscleCounts["Biceps"] || 0) > 0;
  const hasChest = (muscleCounts["Chest"] || 0) > 0;
  const hasTriceps = (muscleCounts["Triceps"] || 0) > 0;
  const hasShoulders = (muscleCounts["Shoulders"] || 0) > 0;
  const hasCore = (muscleCounts["Core"] || 0) > 0;
  const upperGroupCount = [hasBack || hasBiceps, hasChest || hasTriceps, hasShoulders].filter(Boolean).length;
  if (hasLegs && upperGroupCount > 0) return "full-body";
  if (hasLegs) return "legs";
  if (upperGroupCount >= 2) return "upper-mixed";
  if (hasBack || hasBiceps) return "back-biceps";
  if (hasChest || hasTriceps) return "chest-triceps";
  if (hasShoulders) return "shoulders";
  if (hasCore) return "core";
  return "full-body";
};

const generateMonth6Program = (profile) => {
  const previousPrograms = profile.previousPrograms || [];
  const experience = profile.effectiveLevel || profile.experience || "beginner";
  const equipment = profile.equipmentPreference || "gym-and-bands";
  const injuries = profile.injuries || "";
  const frequency = profile.frequency || 3;
  const age = parseInt(String(profile.age)) || 30;
  const sessionLength = Number(profile.sessionLength) || 60;
  const isSenior = age >= 65;

  // Build the valid exercise pool — VIMEO + EXERCISES_DATA verified only
  const validExerciseIds = Object.keys(EXERCISES_DATA).filter(
    id => (VIMEO_VIDEOS)[id] && (VIMEO_VIDEOS)[id].vimeoIds?.length > 0
  );

  // Real per-exercise recency, replacing the old permanent seenExerciseIds
  // blacklist. previousPrograms only stores program KEYS, and a "month6-"
  // key never exists in the static PROGRAMS table (Month 6+ content is
  // generated fresh per person, per cycle, and only ever lives on that
  // person's own profile) - so scanning previousPrograms via PROGRAMS[]
  // silently missed every exercise from any past Month 6+ cycle, exactly
  // the population where real long-term variety matters most. exerciseHistory
  // is now written directly at cycle-completion time from the exercises
  // actually used that cycle (see handleNewCycle), so it stays accurate for
  // both pool and Month 6+ cycles. Recency is continuous rather than a hard
  // seen/unseen flag - something used last cycle scores low, something used
  // 10+ cycles ago (or never) scores at the cap, so a small-pool muscle like
  // Calves still gets the best spacing the real content allows instead of
  // either an artificial hard wall or no preference once "seen" stopped
  // meaning anything.
  const exerciseHistory = profile.exerciseHistory || {};
  const currentCycleForRecency = profile.cycleNumber || 1;
  const cyclesSinceUsed = (id) => {
    const lastUsedCycle = exerciseHistory[id];
    if (lastUsedCycle == null) return 1000; // never used - treat fresh
    return currentCycleForRecency - lastUsedCycle;
  };
  // Average recency across a candidate day's own exercises, used only in
  // Phase 2 (every whole skeleton already used at least once this rotation)
  // to pick which eligible template's version of a given day-category is
  // freshest, rather than always defaulting to whichever skeleton happened
  // to be selected cycle's reference.
  const scoreCandidateFreshness = (groups) => {
    const ids = [];
    (groups || []).forEach((g) => (g.exercises || []).forEach((ex) => { if (ex.id) ids.push(ex.id); }));
    if (ids.length === 0) return 0;
    return ids.reduce((sum, id) => sum + cyclesSinceUsed(id), 0) / ids.length;
  };

  // Parse injury flags
  const injuryFlags = [];
  if (injuries && injuries !== "none") {
    const text = injuries.toLowerCase();
    if (text.includes("knee") || text.includes("acl") || text.includes("mcl") || text.includes("pcl") || text.includes("meniscus") || text.includes("patellar") || text.includes("patella")) {
      injuryFlags.push("knee-deep-flexion");
      injuryFlags.push("knee-impact");
      injuryFlags.push("knee-shear");
    }
    const hasUnambiguousBackTerm_m6 = text.includes("spine") || text.includes("lumbar") || text.includes("disc") || text.includes("disk") || text.includes("herniat") || text.includes("sciatica") || text.includes("scoliosis") || text.includes("vertebr");
    const hasBackWithContext_m6 = text.includes("back") && (
      text.includes("lower back") || text.includes("upper back") || text.includes("mid back") || text.includes("middle back") || text.includes("bad back") ||
      text.includes("pain") || text.includes("hurt") || text.includes("ache") || text.includes("sore") ||
      text.includes("injur") || text.includes("issue") || text.includes("problem") ||
      text.includes("sprain") || text.includes("strain") || text.includes("tweak") ||
      text.includes("surgery") || text.includes("chronic") || text.includes("bulge") || text.includes("slip")
    );
    if (hasUnambiguousBackTerm_m6 || hasBackWithContext_m6) {
      injuryFlags.push("lumbar-extension");
      injuryFlags.push("lumbar-flexion-loaded");
      injuryFlags.push("lumbar-hinge-heavy");
      injuryFlags.push("lumbar-rotation-loaded");
    }
    if (text.includes("shoulder") || text.includes("rotator") || text.includes("labrum") || text.includes("cuff") || text.includes("ac joint") || text.includes("bursitis")) {
      injuryFlags.push("shoulder-impingement");
      injuryFlags.push("shoulder-overhead");
    }
    if (text.includes("wrist")) {
      injuryFlags.push("wrist-load");
    }
    if (text.includes("neck") || text.includes("cervical")) {
      injuryFlags.push("neck-flexion");
    }
    if (text.includes("elbow")) {
      injuryFlags.push("elbow-load");
    }
    if (text.includes("hip")) {
      injuryFlags.push("hip-flexion-loaded");
    }
    if (text.includes("ankle") || text.includes("foot")) {
      injuryFlags.push("ankle-impact");
    }
  }

  // Equipment compatibility check — uses the same shared, buildingEquipment-aware logic
  // program display, so Month 6+ generation can never produce an exercise the
  // building doesn't actually have equipment for.
  const isEquipmentCompatible = (exEquipment, exId = "") => {
    if (!exEquipment) return false;
    const eq = exEquipment.toLowerCase();
    const id = exId.toLowerCase();
    if (equipment === "bands" && !(eq.includes("band") || eq.includes("bodyweight") || eq.includes("resistance") || id.includes("band"))) return false;
    if (equipment === "gym" && (eq.includes("band") || id.startsWith("band-"))) return false;
    return passesEquipmentCheck(eq, equipment, profile.buildingEquipment || [], exId);
  };

  const isAppropriateForLevel = (ex, exId) => {
    const name = (ex.name || "").toLowerCase();
    const id = exId.toLowerCase();
    // Seniors keep access to modified/assisted/senior-labeled variants regardless of their
    // experience tier — these are genuinely safer, more appropriate options for someone 65+,
    // not lesser ones. The exclusions below are only meant for young, non-senior users at
    // advanced/intermediate levels who have outgrown the gentler variants.
    if (!isSenior && (experience === "advanced" || experience === "intermediate")) {
      if (name.includes("modified") || name.includes("Modified")) return false;
      if (name.includes("assisted") || name.includes("Assisted")) return false;
      if (id.includes("senior") || name.includes("senior") || name.includes("Senior")) return false;
      if (name.includes("stationary march") || name.includes("Stationary March")) return false;
      if (name.includes("garland pose") || name.includes("Garland Pose")) return false;
      if (name.includes("seated march") || name.includes("Seated March")) return false;
      if (name.includes("wall sit march") || name.includes("Wall Sit March")) return false;
    }
    if (!isSenior && experience === "advanced") {
      if (name.includes("high plank") || name.includes("High Plank") || id.includes("high-plank")) return false;
      if (ex.difficulty === "beginner" && (
        name.includes("march") || name.includes("March") ||
        name.includes("pose") || name.includes("Pose") ||
        name.includes("toe tap") || name.includes("Toe Tap") ||
        name.includes("modified") || name.includes("Modified") ||
        name.includes("step touch") || name.includes("Step Touch") ||
        name.includes("low platform") || name.includes("Low Platform") ||
        id.includes("step-touch") ||
        id.includes("low-platform") ||
        id === "lying-alternate-leg-raise"
      )) return false;    }
    return true;
  };

// Find best substitute for an exercise
const findSubstitute = (originalId, usedInDay, groupMuscles = [], isPrimary = false) => {
    const original = (EXERCISES_DATA)[originalId];
    if (!original) return null;
    const targetMuscle = original.muscle;
    // Prefer the person's real level over the borrowed exercise's own
    // authored difficulty whenever their real level is HIGHER - otherwise
    // borrowing a day from a lower-tier template (Month 6+ Phase 2, or a
    // narrow slice like advanced+bands+female where pools[] genuinely has
    // no higher-tier option to offer) would leave every exercise capped at
    // that lower tier's difficulty forever, rather than actually being
    // upgraded toward what's appropriate for this specific person. Never
    // downgrades - if the borrowed exercise is already tagged at or above
    // the person's level, its own tag is kept as-is.
    const difficultyRank = { beginner: 1, intermediate: 2, advanced: 3 };
    const originalDifficulty = original.difficulty || experience;
    const targetDifficulty = (difficultyRank[experience] || 2) > (difficultyRank[originalDifficulty] || 2) ? experience : originalDifficulty;

    const preferredCandidates = validExerciseIds
    .filter(id => {
      if (id === originalId) return false;
      if (usedInDay.includes(id)) return false;
      if (usedInProgram.includes(id)) return false;
      const ex = (EXERCISES_DATA)[id];
      if (!ex) return false;
      if (ex.muscle === "Cardio") return false;
      if (ex.muscle !== targetMuscle) return false;
      // Don't pick a substitute whose muscle is already represented elsewhere in the group
      if (groupMuscles.filter(m => m === ex.muscle).length > 1) return false;
      if (!isEquipmentCompatible(ex.equipment, id)) return false;
      if (ex.injuryFlags?.some((f) => injuryFlags.includes(f))) return false;
      if (!isAppropriateForLevel(ex, id)) return false;
      // Don't swap in a time-based exercise if original is reps-based
      const originalEx = (EXERCISES_DATA)[originalId];
      if (!originalEx?.isTime && ex.isTime) return false;
      // Exclude movement patterns already used elsewhere in the program
      if (!isPrimary) {
        const _pmv = ["step-up","step up","split squat","bulgarian","extension","pushdown","kickback","raise","fly","curl","crunch","twist","bridge","thrust","pulldown","pullup","shrug","pull-through","swing"];
        const _pMv = _pmv.find(kw => (ex.name+" "+id).toLowerCase().includes(kw)) || null;
        if (_pMv && usedMovementsInProgram.includes(_pMv)) return false;
      }
      // Exclude exercises whose movement pattern already exists in the day
      const movementKeywords = ["pullthrough", "pull-through", "row", "press", "curl", "fly", "raise", "extension", "pushdown", "pulldown", "squat", "deadlift", "lunge", "thrust", "crunch", "plank", "twist", "bridge", "dip", "pullup", "pushup", "swing", "kickback", "shrug", "good-morning", "good morning", "romanian", "rdl", "hip hinge", "glute bridge", "hip thrust", "step-up", "step up", "split squat", "bulgarian"];
      const getMovementKey = (name, id) => {
        const combined = (name + " " + id).toLowerCase();
        return movementKeywords.find(kw => combined.includes(kw)) || null;
      };
      const candidateMovement = getMovementKey(ex.name, id);
      const tooSimilar = usedInDay.some(usedId => {
        const usedEx = (EXERCISES_DATA)[usedId];
        if (!usedEx) return false;
        if (candidateMovement && getMovementKey(usedEx.name, usedId) === candidateMovement) return true;
        const exNameCore = ex.name.toLowerCase().split(" ").slice(0, 3).join(" ");
        const usedCore = usedEx.name.toLowerCase().split(" ").slice(0, 3).join(" ");
        return exNameCore === usedCore;
      });
      if (tooSimilar) return false;
      return true;
    })
      .map(id => {
        const ex = (EXERCISES_DATA)[id];
        let score = 0;
        // Prefer exercises used longer ago (or never) - continuous recency
        // instead of a binary seen/unseen flag, this is the whole point
        score += Math.min(cyclesSinceUsed(id) * 10, 100);
       
        // Same equipment
        if (ex.equipment === original.equipment) score += 30;
        // Same difficulty
        if (ex.difficulty === targetDifficulty) score += 20;
        // Slightly harder is good for progression
        if (ex.difficulty === "intermediate" && targetDifficulty === "beginner") score += 10;
        if (ex.difficulty === "advanced" && targetDifficulty === "intermediate") score += 10;
        // Movement pattern match — extract key movement words from original ID and match
        const originalWords = originalId.toLowerCase().replace(/-/g, " ").split(" ").filter(w => w.length > 3);
        const candidateWords = id.toLowerCase().replace(/-/g, " ").split(" ");
        const movementMatchCount = originalWords.filter(w => candidateWords.includes(w)).length;
        if (movementMatchCount >= 2) score += 80;
        else if (movementMatchCount === 1) score += 40;
        return { id, score };
      })
      .sort((a, b) => b.score - a.score);

      const candidates = preferredCandidates.length > 0 ? preferredCandidates : validExerciseIds
      .filter(id => {
        if (id === originalId) return false; 
        if (usedInDay.includes(id)) return false;
        if (usedInProgram.includes(id)) return false;
        const ex = (EXERCISES_DATA)[id];
        if (!ex) return false;
        if (ex.muscle === "Cardio") return false;
        if (ex.muscle !== targetMuscle) return false;
        if (!isEquipmentCompatible(ex.equipment, id)) return false;
        if (!isPrimary) {
          const _mv = ["step-up","step up","split squat","bulgarian","extension","pushdown","kickback","raise","fly","curl","crunch","twist","bridge","thrust","pulldown","pullup","shrug","pull-through","swing"];
          const _getMv = (n, i) => { const c = (n+" "+i).toLowerCase(); return _mv.find(kw => c.includes(kw)) || null; };
          const _cMv = _getMv(ex.name, id);
          if (_cMv && usedMovementsInProgram.includes(_cMv)) return false;
        }
        if (ex.injuryFlags?.some((f) => injuryFlags.includes(f))) return false;
        if (!isAppropriateForLevel(ex, id)) return false;
        const origEx = (EXERCISES_DATA)[originalId];
        if (!origEx?.isTime && ex.isTime) return false;
        const movementKeywords = ["pullthrough","pull-through","row","press","curl","fly","raise","extension","pushdown","pulldown","squat","deadlift","lunge","thrust","crunch","plank","twist","bridge","dip","pullup","pushup","swing","kickback","shrug","good-morning","good morning","romanian","rdl","hip hinge","glute bridge","hip thrust","step-up","step up","split squat","bulgarian"];
        const getMovementKey = (name, id) => { const combined = (name + " " + id).toLowerCase(); return movementKeywords.find(kw => combined.includes(kw)) || null; };
        const candidateMovement = getMovementKey(ex.name, id);
        return !usedInDay.some(usedId => { const usedEx = (EXERCISES_DATA)[usedId]; if (!usedEx) return false; if (candidateMovement && getMovementKey(usedEx.name, usedId) === candidateMovement) return true; const exNameCore = ex.name.toLowerCase().split(" ").slice(0,3).join(" "); const usedCore = usedEx.name.toLowerCase().split(" ").slice(0,3).join(" "); return exNameCore === usedCore; });
      });
      
      return candidates.length > 0 ? candidates[0].id : null;
  };

  // Select base program — pick one from their pool they've done least recently
  const levelKey = isSenior
    ? (experience === "advanced" ? "senior-advanced" : experience === "intermediate" ? "senior-intermediate" : "senior-beginner")
    : experience;
  const equipKey = equipment === "gym" ? "gym" : equipment === "bands" ? "bands" : "gym-and-bands";
  const poolKey = `${levelKey}-${equipKey}`;

  // Every real constraint EXCEPT recency - reads from pools[], the same
  // manually-curated, already-proven-correct source the separate
  // pool-rotation branch already uses, instead of re-deriving eligibility
  // by guessing from program key NAMES (the previous approach). Confirmed
  // via direct simulation that string-matching genuinely misses real,
  // correctly curated programs whose key names simply don't happen to
  // contain the exact substrings being searched for - a real
  // advanced+bands+female program existed in pools[], but since its key
  // name didn't literally contain both "advanced" and "band", it was
  // invisible to the old filter, leaving zero eligible options and forcing
  // a dangerous unconstrained fallback. Gender and goal still need their
  // own filtering here since pools[] mixes multiple genders and goals
  // within each level+equipment bucket.
  const usedBaseKeysM6 = getUsedBaseKeys(previousPrograms);
  const recentPrograms = usedBaseKeysM6.slice(-3);
  // Confirmed via full systematic simulation sweep: checking whether the
  // RAW pool array exists isn't enough - a real, non-empty array can still
  // filter down to genuinely zero once gender/goal are applied (bands-only
  // pools are almost entirely mens-/womens- tagged, leaving nothing for a
  // nonbinary/prefer-not-to-say user specifically, even though the raw
  // array itself was never empty). This tries the exact equipment tier
  // first and only broadens to the same level's gym-and-bands tier if the
  // exact tier's real, gender/goal-filtered result is genuinely empty - the
  // exercise-substitution pipeline downstream already re-filters every
  // exercise for this person's REAL equipment preference regardless of
  // which skeleton gets borrowed, so broadening the skeleton search here is
  // safe and can only ever produce exercises their own equipment supports.
  const filterEligibleBaseKeys = (list) => list.filter(key => {
    const prog = PROGRAMS[key];
    if (!prog) return false;
    if (!isProgramGenderCompatible(key, profile.gender)) return false;
    if (!isProgramGoalCompatible(key, profile.primaryGoal || "general_fitness")) return false;
    return true;
  });
  const equipmentFallbackOrder = equipKey === "gym-and-bands" ? [poolKey] : [poolKey, `${levelKey}-gym-and-bands`];
  let fullyEligiblePrograms = [];
  for (const tryKey of equipmentFallbackOrder) {
    const candidate = filterEligibleBaseKeys(pools[tryKey] || []);
    if (candidate.length > 0) { fullyEligiblePrograms = candidate; break; }
  }
  // Confirmed via direct simulation: for a narrow slice like advanced+bands
  // (which can have as 1-2 real eligible programs total), avoiding
  // the last 3 cycles unconditionally could empty the pool entirely for
  // several cycles straight, forcing the code down to
  // Object.keys(PROGRAMS)[0] absolute last resort - the literal
  // first key in the whole catalog, with every real constraint (level,
  // equipment, gender, goal) silently bypassed. Only exclude recent
  // programs when doing so leaves at least one option; otherwise fall back
  // to the full eligible set, which still respects every real constraint
  // even when there isn't enough content to also avoid recent repeats.
  const recentExcluded = fullyEligiblePrograms.filter(key => !recentPrograms.includes(key));
  const allPoolPrograms = recentExcluded.length > 0 ? recentExcluded : fullyEligiblePrograms;

  // Pick the base program — prefer ones done longest ago. Reuses the same
  // normalized usedBaseKeysM6 list computed above, rather than checking raw
  // previousPrograms directly, so a key already used (as either a genuine
  // pool cycle or a past Month 6+ skeleton) is correctly excluded either way.
  //
  // Phase 1 (most of a person's tenure): a genuinely unused skeleton exists,
  // firstUnusedKey finds it, exactly Phase 2 (every eligible
  // skeleton has now been used at least once): rather than silently falling
  // back to repeating the same one forever, isSkeletonPoolExhausted switches
  // the day-selection loop below into day-level recombination instead -
  // still using a reference skeleton (baseKey) for the overall day-type
  // sequence, but filling each individual day from whichever eligible
  // template's version of that day-category is freshest, not necessarily
  // the reference skeleton's own.
  const firstUnusedKey = allPoolPrograms.find(k => !usedBaseKeysM6.includes(k));
  const isSkeletonPoolExhausted = !firstUnusedKey;
  const baseKey = firstUnusedKey || allPoolPrograms[0] || Object.keys(PROGRAMS)[0];

  const baseProgram = PROGRAMS[baseKey];
  if (!baseProgram) return { programKey: baseKey };

  // Built once per generation call, not per day, and only when actually
  // needed - every eligible template's real training days, pre-classified
  // by category, ready for the day-selection loop below to search.
  //
  // Deliberately WIDER than allPoolPrograms (which stays scoped to the
  // person's own equipment tier, correct for reference-skeleton selection
  // above): pulls candidate DAYS from every equipment tier at this
  // person's level (gym, bands, gym-and-bands combined), not just their
  // own preference. The exercise-substitution pipeline downstream already
  // re-filters every exercise for their REAL equipment regardless of which
  // day-template it came from (same principle difficulty-upgrade
  // fix), so this is safe. For a narrow slice like advanced+bands (as few
  // as 1-2 real skeletons total), restricting candidates to bands-only
  // templates barely gives Phase 2 anything to recombine from - widening
  // the DAY source while keeping exercise-level equipment filtering intact
  // gives genuine structural variety without requiring any new content.
  const allEquipmentTiersForLevel = [`${levelKey}-gym`, `${levelKey}-bands`, `${levelKey}-gym-and-bands`];
  const widenedCandidateKeys = Array.from(new Set(allEquipmentTiersForLevel.flatMap(k => pools[k] || [])))
    .filter(key => {
      const prog = PROGRAMS[key];
      if (!prog) return false;
      if (!isProgramGenderCompatible(key, profile.gender)) return false;
      if (!isProgramGoalCompatible(key, profile.primaryGoal || "general_fitness")) return false;
      return true;
    });

  const candidateDaysByCategory = {};
  if (isSkeletonPoolExhausted) {
    widenedCandidateKeys.forEach((pk) => {
      const prog = PROGRAMS[pk];
      if (!prog?.days) return;
      prog.days.forEach((d) => {
        if (d.isRest || !d.groups?.length) return;
        const category = classifyDayCategory(d.groups);
        if (!candidateDaysByCategory[category]) candidateDaysByCategory[category] = [];
        candidateDaysByCategory[category].push(d);
      });
    });
  }

  // Generate fresh days by swapping 1 exercise per superset
  const usedInProgram = [];
  const usedMovementsInProgram = [];
  // Calculate rest days from frequency — ignore base program rest structure
  const restDaysByFrequency = {
    6: [7],
    5: [4, 7],
    4: [3, 5, 7],
    3: [2, 4, 6, 7],
    2: [2, 4, 5, 6, 7],
  };
  const restDays = restDaysByFrequency[frequency] || [7];

  const generatedDays = Array.from({ length: 7 }, (_, i) => {
    const dayNum = i + 1;
    if (restDays.includes(dayNum)) return {
      dayNum,
      title: `Day ${dayNum} — Rest`,
      type: "rest",
      focus: "Recovery",
      isRest: true,
      notes: ["Recovery is part of the program.", "Use this day to stretch, walk, or just rest.", "Your next session will be stronger for it."],
      groups: [],
    };
    // Find matching workout day from base program — preserve exact day order, no cycling
    const workoutDayIndex = Array.from({ length: dayNum }, (_, j) => j + 1)
      .filter(d => !restDays.includes(d)).length - 1;
    const workoutDays = baseProgram.days.filter((d) => !d.isRest);
    // Use exact index if available — only fall back to modulo if base program has fewer days than needed
    const isReplayDay = !workoutDays[workoutDayIndex];
    const baseDayReference = workoutDays[workoutDayIndex] || workoutDays[workoutDayIndex % workoutDays.length];
    let baseDay = baseDayReference;
    // Phase 2 only (isSkeletonPoolExhausted): don't just keep reusing the
    // reference skeleton's own version of this day - search every eligible
    // template's matching-category day instead, and use whichever one has
    // the freshest (least recently used) exercises on average. This is what
    // actually extends real variety past the point where whole-skeleton
    // rotation runs out, rather than silently freezing on whichever
    // skeleton happened to be picked cycle's reference.
    if (isSkeletonPoolExhausted && baseDayReference?.groups?.length > 0) {
      const dayCategory = classifyDayCategory(baseDayReference.groups);
      const candidates = candidateDaysByCategory[dayCategory] || [];
      if (candidates.length > 0) {
        const scoredCandidates = candidates.map((c) => ({ day: c, score: scoreCandidateFreshness(c.groups) }));
        scoredCandidates.sort((a, b) => b.score - a.score);
        const freshestCandidate = scoredCandidates[0]?.day;
        if (freshestCandidate) {
          baseDay = { ...baseDayReference, groups: freshestCandidate.groups, notes: freshestCandidate.notes || baseDayReference.notes };
        }
      }
    }
    if (!baseDay) return {
      dayNum,
      title: `Day ${dayNum} — Rest`,
      type: "rest",
      focus: "Recovery",
      isRest: true,
      notes: ["Recovery is part of the program.", "Use this day to stretch, walk, or just rest.", "Your next session will be stronger for it."],
      groups: [],
    };
    const day = { ...baseDay, dayNum, title: baseDay.title.replace(/Day \d+/, `Day ${dayNum}`) };
    const usedInDay = [];
    // Last-resort safety net only - every existing fallback tier below this
    // comment is completely untouched. This only fires in the narrow case
    // where every constraint-respecting search already failed and the code
    // is about to fall back to keeping a slot's original exercise, but that
    // exact exercise happens to already be placed elsewhere in today's day.
    // Returns a same-muscle, still equipment/injury/level-safe alternative
    // that hasn't been used today (preferring whichever such exercise was
    // used longest ago), so the worst case becomes "a rare exercise repeats
    // a bit sooner than ideal" rather than "the same exercise appears twice
    // in one workout." If no such alternative exists either, returns the
    // original unchanged - identical to today's existing behavior in that
    // scenario. Defined here, inside the per-day loop, specifically because
    // it depends on usedInDay, which is itself scoped fresh to each day -
    // defining this at the outer function level (as it originally was)
    // meant it could never actually see usedInDay at all, silently crashing
    // with a ReferenceError the one time this fallback path was ever
    // actually reached, since JS closures only see variables from scopes
    // that existed at DEFINITION time, not wherever the function is called.
    const avoidSameDayDuplicate = (fallbackId) => {
      // Confirmed via direct simulation: this function was only ever
      // designed to solve "avoid the same exercise appearing twice in one
      // day" - its early return let ANY non-duplicate exercise straight
      // through unchanged, including a genuinely equipment-incompatible
      // one, whenever findSubstitute had already failed to find a
      // compatible alternative (a real content gap - e.g. no bands
      // equivalent exists for that specific muscle target). Since this is
      // the true last-resort tail before an exercise reaches the final
      // output, it needs to also require equipment compatibility here, not
      // just non-duplication - otherwise a widened Phase 2 day-borrow with
      // no valid substitute for one specific exercise could still leak a
      // real gym-only exercise (barbell, cable machine) to a bands-only
      // person. Still falls back to the original at the very end if
      // truly nothing else qualifies - a genuine content gap has no better
      // answer than the closest available option.
      const fallbackData = (EXERCISES_DATA)[fallbackId];
      const fallbackEquipmentOk = fallbackData ? isEquipmentCompatible(fallbackData.equipment, fallbackId) : true;
      if (!usedInDay.includes(fallbackId) && fallbackEquipmentOk) return fallbackId;
      const targetMuscle = (EXERCISES_DATA)[fallbackId]?.muscle;
      const alt = validExerciseIds.filter(id => {
        if (usedInDay.includes(id)) return false;
        const exData = (EXERCISES_DATA)[id];
        if (!exData || exData.muscle !== targetMuscle) return false;
        if (!isEquipmentCompatible(exData.equipment, id)) return false;
        if (injuryFlags.length > 0 && exData.injuryFlags?.some((f) => injuryFlags.includes(f))) return false;
        if (!isAppropriateForLevel(exData, id)) return false;
        return true;
      }).sort((a, b) => cyclesSinceUsed(b) - cyclesSinceUsed(a));
      return alt[0] || fallbackId;
    };
    const newGroups = day.groups.map((group) => {
      if (group.type === "cardio") return group;
      const exercises = (group.exercises || []).filter((ex) => {
        const exData = (EXERCISES_DATA)[ex.id];
        if (!exData) return true;
        return isAppropriateForLevel(exData, ex.id);
      });
      let swappedInGroup = false;
      // Identify the primary compound — never swap it (first exercise in group)
      const newExercises = exercises.map((ex, index) => {
        // Primary compound (index 0) — swap if equipment incompatible, injury flagged, OR already used earlier this week
        if (index === 0) {
          const equipmentIncompatible = !isEquipmentCompatible((EXERCISES_DATA)[ex.id]?.equipment || "", ex.id);
          const alreadyUsedThisWeek = usedInProgram.includes(ex.id);
          const injuryBlocked = injuryFlags.length > 0 && (EXERCISES_DATA)[ex.id]?.injuryFlags?.some((f) => injuryFlags.includes(f));
          // Defaults to the original exercise, unchanged - only the genuine
          // last-resort failure tail below ever reassigns this, and only
          // when that would otherwise create a same-day duplicate. Every
          // other path in this block is completely untouched.
          let primaryFallbackId = ex.id;
          
          if (equipmentIncompatible || alreadyUsedThisWeek || injuryBlocked) {
            const substitute = findSubstitute(ex.id, [...usedInDay, ...(isReplayDay ? [] : usedInProgram)], [], true)
              || findSubstitute(ex.id, usedInDay, [], true)
              || (isReplayDay ? validExerciseIds.find(id => {
                  if (usedInDay.includes(id)) return false;
                  const exData = (EXERCISES_DATA)[id];
                  if (!exData) return false;
                  if (exData.muscle !== (EXERCISES_DATA)[ex.id]?.muscle) return false;
                  if (!isEquipmentCompatible(exData.equipment, id)) return false;
                  if (injuryFlags.length > 0 && exData.injuryFlags?.some((f) => injuryFlags.includes(f))) return false;
                  if (!isAppropriateForLevel(exData, id)) return false;
                  return true;
                }) : null);
            if (substitute) {
              usedInDay.push(substitute);
              if (!usedInProgram.includes(substitute)) {
                usedInProgram.push(substitute);
                const _subEx = (EXERCISES_DATA)[substitute];
                const _subMv = ["pullthrough","pull-through","row","press","curl","fly","raise","extension","pushdown","pulldown","squat","deadlift","lunge","thrust","crunch","plank","twist","bridge","dip","pullup","pushup","swing","kickback","shrug","good-morning","good morning","romanian","rdl","hip hinge","glute bridge","hip thrust","step-up","step up","split squat","bulgarian"];
                const _getMvKey = (n, i) => { const c = (n+" "+i).toLowerCase(); return _subMv.find(kw => c.includes(kw)) || null; };
                const _mv = _subEx ? _getMvKey(_subEx.name, substitute) : null;
                if (_mv && !usedMovementsInProgram.includes(_mv)) usedMovementsInProgram.push(_mv);
              }
              return { ...ex, id: substitute };
            }
            // No substitute found — try loose pass: only injury + equipment, ignore usedInProgram
            const looseSubstitute = validExerciseIds.find(id => {
              if (id === ex.id || usedInDay.includes(id)) return false;
              const exData = (EXERCISES_DATA)[id];
              if (!exData) return false;
              if (exData.muscle !== (EXERCISES_DATA)[ex.id]?.muscle) return false;
              if (!isEquipmentCompatible(exData.equipment, id)) return false;
              if (injuryFlags.length > 0 && exData.injuryFlags?.some((f) => injuryFlags.includes(f))) return false;
              if (!isAppropriateForLevel(exData, id)) return false;
              return true;
            });
            if (looseSubstitute) {
              usedInDay.push(looseSubstitute);
              if (!usedInProgram.includes(looseSubstitute)) usedInProgram.push(looseSubstitute);
              return { ...ex, id: looseSubstitute };
            }
            // This is the genuine "every attempt failed" tail - relax the
            // duplicate check only enough to avoid the same exercise
            // appearing twice in one day, per avoidSameDayDuplicate above.
            primaryFallbackId = avoidSameDayDuplicate(ex.id);
            usedInDay.push(primaryFallbackId);
            if (!usedInProgram.includes(primaryFallbackId)) usedInProgram.push(primaryFallbackId);
          }
          usedInDay.push(primaryFallbackId);
          if (!usedInProgram.includes(primaryFallbackId)) {
            usedInProgram.push(primaryFallbackId);
            const _exData = (EXERCISES_DATA)[primaryFallbackId];
            const _exMvKws = ["pullthrough","pull-through","row","press","curl","fly","raise","extension","pushdown","pulldown","squat","deadlift","lunge","thrust","crunch","plank","twist","bridge","dip","pullup","pushup","swing","kickback","shrug","good-morning","good morning","romanian","rdl","hip hinge","glute bridge","hip thrust","step-up","step up","split squat","bulgarian"];
            const _exMv = _exData ? _exMvKws.find(kw => (_exData.name+" "+primaryFallbackId).toLowerCase().includes(kw)) || null : null;
            if (_exMv && !usedMovementsInProgram.includes(_exMv)) usedMovementsInProgram.push(_exMv);
          }
          // Identical to the original "return ex" when primaryFallbackId was
          // never reassigned (the normal, overwhelming majority case) - only
          // differs in the narrow failure case handled above.
          return primaryFallbackId === ex.id ? ex : { ...ex, id: primaryFallbackId };
        }
        // Only swap 1 per group max for VARIETY reasons - but never for a
        // genuine equipment mismatch. Phase 2 day-recombination (widened to
        // pull day-structures from every equipment tier at this person's
        // level, not just their own) can hand this loop a group where EVERY
        // exercise is equipment-incompatible, not just one - the original
        // "swap 1 per group" limit was designed around borrowing from the
        // person's own equipment tier, where at most one exercise per group
        // would ever need correcting. Confirmed via direct simulation that
        // without this override, real gym-only exercises (barbell, cable
        // machine, leg curl machine) were reaching bands-only users
        // whenever they weren't first in their group.
        const origExDataForSwapCheck = (EXERCISES_DATA)[ex.id];
        const isCurrentlyEquipmentIncompatible = origExDataForSwapCheck && !isEquipmentCompatible(origExDataForSwapCheck.equipment, ex.id);
        const alreadySwappedOne = swappedInGroup && !isCurrentlyEquipmentIncompatible;
        if (alreadySwappedOne) {
          usedInDay.push(ex.id);
          return ex;
        }
        // Try to find a substitute
        const groupMuscleSoFar = exercises.slice(0, index).map((e) => (EXERCISES_DATA)[e.id]?.muscle).filter(Boolean);
        const substitute = findSubstitute(ex.id, [...usedInDay, ...usedInProgram], groupMuscleSoFar);
        if (substitute) {
          swappedInGroup = true;
          usedInDay.push(substitute);
          usedInProgram.push(substitute);
          const _accEx = (EXERCISES_DATA)[substitute];
          const _accMvKws = ["pullthrough","pull-through","row","press","curl","fly","raise","extension","pushdown","pulldown","squat","deadlift","lunge","thrust","crunch","plank","twist","bridge","dip","pullup","pushup","swing","kickback","shrug","good-morning","good morning","romanian","rdl","hip hinge","glute bridge","hip thrust","step-up","step up","split squat","bulgarian"];
          const _accMv = _accEx ? _accMvKws.find(kw => (_accEx.name+" "+substitute).toLowerCase().includes(kw)) || null : null;
          if (_accMv && !usedMovementsInProgram.includes(_accMv)) usedMovementsInProgram.push(_accMv);
          const subData = (EXERCISES_DATA)[substitute];
          const newReps = (!subData?.isTime && ex.reps?.toString().includes("secs")) ? "10-12" : ex.reps;
          return { ...ex, id: substitute, reps: newReps, _swapped: true };
        }
        // Every attempt to find a real substitute failed - same last-resort
        // safety net primary-compound case above, only relaxing the
        // duplicate check far enough to avoid the same exercise appearing
        // twice in one day.
        const fallbackId = avoidSameDayDuplicate(ex.id);
        usedInDay.push(fallbackId);
        return fallbackId === ex.id ? ex : { ...ex, id: fallbackId };
      });
      return { ...group, exercises: newExercises };
    });
    // Cap groups to fit session length — 60 min = max 6 groups
    const maxGroups = sessionLength >= 60 ? 6 : sessionLength >= 45 ? 5 : 4;
    const cappedGroups = newGroups.slice(0, maxGroups);

    // Post-process: eliminate duplicate movement patterns across all groups in the day
    const movementKeywords = ["pullthrough", "pull-through", "row", "press", "curl", "fly", "raise", "extension", "pushdown", "pulldown", "squat", "deadlift", "lunge", "thrust", "crunch", "plank", "twist", "bridge", "dip", "pullup", "pushup", "swing", "kickback", "shrug", "good-morning", "good morning", "romanian", "rdl", "hip hinge", "glute bridge", "hip thrust", "step-up", "step up", "split squat", "bulgarian"];
    const getMovementKey = (name, id) => {
      const combined = (name + " " + id).toLowerCase();
      return movementKeywords.find(kw => combined.includes(kw)) || null;
    };
    const dayMovements = [];
    const dayExerciseIds = [];
    const deduplicatedGroups = cappedGroups.map((group) => {
      if (group.type === "cardio") return group;
      const newExercises = group.exercises.map((ex) => {
        const exData = (EXERCISES_DATA)[ex.id];
        const movement = exData ? getMovementKey(exData.name, ex.id) : null;
        const isDuplicate = movement && dayMovements.includes(movement);
        const isIdDuplicate = dayExerciseIds.includes(ex.id);
        const isInjuryBlocked = injuryFlags.length > 0 && (EXERCISES_DATA)[ex.id]?.injuryFlags?.some((f) => injuryFlags.includes(f));
        if (isDuplicate || isIdDuplicate || isInjuryBlocked) {
          // Force swap this exercise
          const substitute = findSubstitute(ex.id, dayExerciseIds, []);
          if (substitute) {
            const subData = (EXERCISES_DATA)[substitute];
            const subMovement = subData ? getMovementKey(subData.name, substitute) : null;
            const subInjuryBlocked = injuryFlags.length > 0 && subData?.injuryFlags?.some((f) => injuryFlags.includes(f));
            if (!subInjuryBlocked && (!subMovement || !dayMovements.includes(subMovement))) {
              dayExerciseIds.push(substitute);
              if (subMovement) dayMovements.push(subMovement);
              return { ...ex, id: substitute };
            }
          }
        }
        if (movement && !dayMovements.includes(movement)) dayMovements.push(movement);
        dayExerciseIds.push(ex.id);
        return ex;
      });
      return { ...group, exercises: newExercises };
    });

    // Regenerate title and focus based on actual muscle groups after all swaps
    const allMuscles = [];
    deduplicatedGroups.forEach((g) => {
      if (g.type === "cardio") { allMuscles.push("Cardio"); return; }
      (g.exercises || []).forEach((ex) => {
        const m = (EXERCISES_DATA)[ex.id]?.muscle;
        if (m && !allMuscles.includes(m)) allMuscles.push(m);
      });
    });
    const hasCardio = allMuscles.includes("Cardio");
    const muscleGroups = allMuscles.filter(m => m !== "Cardio");
    // Map muscle names to display labels
    const muscleToLabel = {
      "Chest": "Chest", "Back": "Back", "Shoulders": "Shoulders",
      "Triceps": "Triceps", "Biceps": "Biceps", "Quads": "Legs",
      "Hamstrings": "Legs", "Glutes": "Glutes", "Core": "Abs",
      "Full Body": "Full Body", "Cardio": "Cardio", "Calves": "Calves",
    };
    const uniqueLabels = [...new Set(muscleGroups.map(m => muscleToLabel[m] || m))];
    // Build concise title — max 3 muscle groups
    const titleParts = uniqueLabels.slice(0, 3);
    if (hasCardio && !titleParts.includes("Cardio") && titleParts.length < 3) titleParts.push("Cardio");
    const newTitle = titleParts.length > 0
      ? `Day ${dayNum} — ${titleParts.join(" & ")}`
      : `Day ${dayNum} — Full Body`;
    const newFocus = [...uniqueLabels.slice(0, 4), ...(hasCardio && !uniqueLabels.includes("Cardio") ? ["Cardio"] : [])].join(", ");
    // Determine type from dominant muscle groups
    const hasUpper = muscleGroups.some(m => ["Chest","Back","Shoulders","Triceps","Biceps"].includes(m));
    const hasLower = muscleGroups.some(m => ["Quads","Hamstrings","Glutes","Calves"].includes(m));
    const hasCore = muscleGroups.includes("Core");
    const newType = hasUpper && hasLower ? "full-body" : hasUpper ? "upper-body" : hasLower ? "lower-body" : hasCore ? "core" : "full-body";
    return { ...day, title: newTitle, focus: newFocus, type: newType, groups: deduplicatedGroups };
  }).filter(Boolean);

  // Clean up _swapped markers
  const cleanDays = generatedDays.map((day) => ({
    ...day,
    groups: (day.groups || []).map((g) => ({
      ...g,
      exercises: (g.exercises || []).map(({ _swapped, ...ex }) => ex),
    })),
  }));

  return { programKey: `month6-${baseKey}`, generatedDays: cleanDays };
};


// ============ WIDENING VERIFICATION ============
console.log("\n\n============ WIDENING VERIFICATION ============");

const testProfiles = [
  { label: "Advanced Male Bands-Only", experience: "advanced", effectiveLevel: "advanced", gender: "male", equipmentPreference: "bands", frequency: 4, primaryGoal: "muscle_gain", age: "28" },
  { label: "Advanced Female Bands-Only", experience: "advanced", effectiveLevel: "advanced", gender: "female", equipmentPreference: "bands", frequency: 3, primaryGoal: "muscle_gain", age: "32" },
  { label: "Intermediate Male Bands-Only", experience: "intermediate", effectiveLevel: "intermediate", gender: "male", equipmentPreference: "bands", frequency: 4, primaryGoal: "fat_loss", age: "29" },
];

for (const baseProfile of testProfiles) {
  console.log(`\n--- ${baseProfile.label} ---`);
  let profile = { ...baseProfile, cycleNumber: 6, previousPrograms: [], exerciseHistory: {}, sessionLength: 60, injuries: "none" };
  const results = [];
  let crashed = false, crashMsg = "";
  const equipmentViolations = [];
  const structuralShapes = new Set();

  for (let cycle = 6; cycle <= 40; cycle++) {
    profile.cycleNumber = cycle;
    try {
      const result = generateMonth6Program(profile);
      const usedIds = [];
      const dayShapes = [];
      (result.generatedDays || []).forEach(day => {
        if (day.isRest) return;
        const exIds = [];
        (day.groups || []).forEach(g => (g.exercises || []).forEach(ex => {
          if (ex.id) { usedIds.push(ex.id); exIds.push(ex.id); }
        }));
        dayShapes.push(exIds.length);
        // Check every exercise used is actually bands-compatible
        exIds.forEach(id => {
          const exData = EXERCISES_DATA[id];
          if (!exData) return;
          const eq = (exData.equipment || "").toLowerCase();
          const bandsIncompatible = ["barbell", "cable machine", "machine", "smith machine", "leg press"].some(bad => eq.includes(bad));
          if (bandsIncompatible && baseProfile.equipmentPreference === "bands") {
            equipmentViolations.push(`cycle ${cycle}: ${id} (${exData.equipment})`);
          }
        });
      });
      structuralShapes.add(dayShapes.join(","));
      results.push({ cycle, programKey: result.programKey, exerciseIds: usedIds });
      const newHistory = { ...profile.exerciseHistory };
      usedIds.forEach(id => { newHistory[id] = cycle; });
      profile = { ...profile, previousPrograms: [...profile.previousPrograms, result.programKey], exerciseHistory: newHistory };
    } catch (e) {
      crashed = true; crashMsg = e.message; break;
    }
  }

  if (crashed) {
    console.log(`  !!! CRASHED at cycle: ${crashMsg}`);
    continue;
  }

  const distinctSkeletons = new Set(results.map(r => r.programKey.replace("month6-", ""))).size;
  console.log("Cycles run:", results.length, "| Distinct skeleton labels:", distinctSkeletons, "| Distinct day-count shapes:", structuralShapes.size);
  console.log("Equipment violations:", equipmentViolations.length, equipmentViolations.length > 0 ? equipmentViolations.slice(0, 10) : "");

  // Exercise overlap in later cycles (post Phase-2 kick-in) - lower = more variety
  if (results.length > 15) {
    const a = new Set(results[results.length - 3].exerciseIds);
    const b = new Set(results[results.length - 2].exerciseIds);
    const overlap = [...a].filter(x => b.has(x)).length;
    console.log(`Late-cycle exercise overlap: ${overlap}/${a.size} identical between consecutive cycles`);
  }
}
